local doorState: { [BasePart]: { number } } = {}
local openUntil: { [Instance]: number } = {}

local function setOpen(target: Instance, open: boolean)
	local list = if target:IsA("BasePart") then { target } else target:GetDescendants()
	for _, p in list do
		if p:IsA("BasePart") then
			if not doorState[p] then
				doorState[p] = { if p.CanCollide then 1 else 0, p.Transparency }
			end
			local saved = doorState[p]
			if open then
				p.CanCollide = false
				p.Transparency = math.max(saved[2], 0.75)
			else
				p.CanCollide = saved[1] == 1
				p.Transparency = saved[2]
			end
		end
	end
	local flag = target:FindFirstChild("Open")
	if flag and flag:IsA("BoolValue") then
		flag.Value = open
	end
end

function PrisonFlow.closeCell(room: any): (boolean, string?)
	local target=markerDoorTarget(room.door)
	if not target or not target.Parent then return false,"missing DoorObject" end
	openUntil[target]=nil
	local ok,why=pcall(setOpen,target,false)
	if not ok then return false,tostring(why) end
	local parts=if target:IsA("BasePart") then {target} else target:GetDescendants()
	for _,part in parts do
		if part:IsA("BasePart") then
			local saved=doorState[part]
			if saved and part.CanCollide~=(saved[1]==1) then return false,"collision restore failed: "..part:GetFullName() end
		end
	end
	target:SetAttribute("CustodyLocked",true);room.door:SetAttribute("CustodyLocked",true)
	if target.Parent and string.lower(target.Parent.Name)=="door" then target.Parent:SetAttribute("CustodyLocked",true) end
	print("[CustodyDiag] DOOR LOCK CONFIRMED "..room.door.Name)
	return true
end

local deathRowExecutionActive=setmetatable({}, {__mode="k"})

-- A Death Row execution is a complete character wipe: cash, bank balance,
-- vehicles, home, weapons, custody history and inmate status all return to
-- the same state as a new visitor. Persist the zeroed EconomyServer schema so
-- a later load does not restore the old profile.
local PrisonSave: any = nil -- v200 prison persistence (set up in Justice init)
local function resetExecutedPlayer(player: Player)
	clearJusticeState(player)
	local function zeroValue(name: string, value: number)
		local item=player:FindFirstChild(name)
		if item and (item:IsA("IntValue") or item:IsA("NumberValue")) then item.Value=value end
	end
	zeroValue("Cash",0);zeroValue("Money",0);zeroValue("Rent",0);zeroValue("PaydayTimer",300)
		for _,name in {"HouseId","SavedHouse","SecurityClass","InmateShirtAssetId","InmatePantsAssetId","PrisonClothesIssued","PrisonDressOutComplete","DeathRowExecutionStarted","DeathRowGasExposure","DeathRowExecutionComplete","EscapeRemainingSentence","EscapeInProgress","EscapeDetected","EscapeCause","EscapeAt","CustodyAutoMove","CustodyOwner","CustodyPhase","CustodyStars","CaseCharges","CaseVerdict","Charges","Facility","AssignedCell","BookingCell","BookingState","SentenceEnd","SentenceSeconds","CounselName","IntakeHoldUntil","SharedTransportWith","SharedTransportDelivered","SharedTransportAtIntake","CustodyResetRecoveryPending"} do
		player:SetAttribute(name,nil)
	end
	local carStorage=player:FindFirstChild("CarStorage")
	if carStorage then carStorage:ClearAllChildren() end
	local held=heldGuns[player]
	if held then for _,tool in held do if tool and tool.Parent then tool:Destroy() end end end
	heldGuns[player]=nil
	for _,container in {player:FindFirstChild("StarterGear"),player:FindFirstChildOfClass("Backpack"),player.Character} do
		if container then for _,item in container:GetChildren() do if item:IsA("Tool") then item:Destroy() end end end
	end
	crimeKeys[player]=nil;recentCrime[player]=nil;previousTeam[player]=nil
	local visitors=teamNamed(JCFG.ReleaseTeam)
	if visitors then player.Neutral=false;player.Team=visitors end
	-- v200: a wipe returns to the player's starting balance (PlayerDefaults),
	-- e.g. aquagaming22 always restarts with $50,000,000 in the bank.
	local startCash,startBank=0,0
	local defaultsModule=game:GetService("ServerScriptService"):FindFirstChild("PlayerDefaults")
	if defaultsModule then
		local okDefaults,defaults=pcall(require,defaultsModule)
		if okDefaults then startCash,startBank=defaults.start(player) end
	end
	zeroValue("Cash",startCash);zeroValue("Money",startBank)
	if PrisonSave then PrisonSave.clear(player) end
	local persisted=false
	local ok,err=pcall(function()
		local store=game:GetService("DataStoreService"):GetDataStore("LasVegas_PlayerData_v1")
		store:SetAsync("player_"..player.UserId,{cash=startCash,bank=startBank,cars={},house=nil})
		persisted=true
	end)
	if not ok or not persisted then warn("[DeathRow] new-player progress reset is session-only; DataStore write failed: "..tostring(err)) end
	print(("[DeathRow] NEW PLAYER RESET %s persisted=%s team=%s"):format(player.Name,tostring(persisted),visitors and visitors.Name or "unchanged"))
	-- v286s: a prison death ends this character: the player picks a new name (CharacterNames)
	-- v290: a new character starts clean - the court record (and the judges' memory of them, the
	-- prison file) and the CityLife profile (warrants, bail, court dates, gang rep, debts, licence)
	if Justice.Records and Justice.Records.wipe then pcall(Justice.Records.wipe,player) end
	local extrasWipe=game:GetService("ServerStorage"):FindFirstChild("ExtrasWipe")
	if extrasWipe and extrasWipe:IsA("BindableFunction") then task.spawn(pcall,extrasWipe.Invoke,extrasWipe,player) end
	for _,name in {"PrisonStars","PriorArrests","RecordEscapes","Warrant","LawyerTrust","CORespect","ProtectiveCustody","CounselRetained"} do player:SetAttribute(name,nil) end
	local died=game:GetService("ServerStorage"):FindFirstChild("CharacterDied")
	if died and died:IsA("BindableEvent") then died:Fire(player) end
end

deathRowExecution=function(player: Player)
	if deathRowExecutionActive[player] or not player.Parent or player:GetAttribute("SecurityClass")~="Death Row" then return end
	local room=PrisonFlow.rooms[player]
	local character,hum,root=Util.charInfo(player)
	if not room or not room.door or not character or not hum or not root or hum.Health<=0 then
		warn("[DeathRow] execution deferred: assigned cell/character unavailable for "..player.Name)
		return
	end
	deathRowExecutionActive[player]=true
	player:SetAttribute("DeathRowExecutionStarted",true)
	player:SetAttribute("CustodyPhase","DeathRowExecution")
	player:SetAttribute("BookingState","DeathRowExecution")
	player:SetAttribute("CustodyAutoMove",true)
	hum.WalkSpeed=0;hum.JumpPower=0;hum.JumpHeight=0;hum.AutoRotate=false;hum:MoveTo(root.Position)
	local outside=PrisonFlow.approach(room)
	local guard=nameEscort(escortCop(outside,room.pos-outside),"EXECUTION OFFICER")
	if guard then guard.cfg.WalkSpeed=7 end
	local doorTarget=markerDoorTarget(room.door)
	if doorTarget then
		doorTarget:SetAttribute("CustodyLocked",nil);room.door:SetAttribute("CustodyLocked",nil)
		if doorTarget.Parent and string.lower(doorTarget.Parent.Name)=="door" then doorTarget.Parent:SetAttribute("CustodyLocked",nil) end
		openMarkedDoor(room.door,4)
	end
	tell(player,"DeathRowExecution","Sentence complete - execution detail at your cell")
	print(("[DeathRow] %s-minute test sentence complete; guard deploying tear gas into %s"):format("1",room.name))
	local throwFrom=(guard and guard.root.Position or outside)+Vector3.new(0,2,0)
	local gasTarget=room.pos+Vector3.new(0,1.5,0)
	local radius=math.max(tonumber(Config.TearGas.Radius) or 24,16)
	local cloudTime=math.max(tonumber(Config.TearGas.CloudTime) or 8,6)
	__require("Weapons").throwTearGas(throwFrom,gasTarget,function(center: Vector3)
		if not player.Parent or player.Character~=character then return end
		player:SetAttribute("DeathRowGasExposure",true)
		print(("[DeathRow] tear gas cloud active for %s at %s"):format(player.Name,tostring(center)))
		local stopAt=os.clock()+cloudTime
		while os.clock()<stopAt and player.Parent and player.Character==character and hum.Health>0 do
			local inside=PrisonNav and PrisonNav.isInsideCell(room,root.Position)
			if inside and Util.flat(root.Position-center).Magnitude<=radius then hum:TakeDamage(12) end
			task.wait(0.5)
		end
		if player.Parent and player.Character==character and hum.Health>0 then
			-- Death normally drops on-hand cash; this is a wipe, so no execution
			-- money pickup should remain in the cell or be claimable by others.
			local cash=player:FindFirstChild("Cash")
			if cash and (cash:IsA("IntValue") or cash:IsA("NumberValue")) then cash.Value=0 end
			hum.Health=0
		end
	end)
	-- Seal the cell after the canister is through the doorway; leave the gas cloud
	-- visible and damaging inside the assigned mapped cell.
	task.wait(1.6)
	local closed,why=PrisonFlow.closeCell(room)
	print(("[DeathRow] cell resealed for %s: %s (%s)"):format(player.Name,tostring(closed),tostring(why)))
	if guard then guard:despawn("death row execution complete") end
	task.wait(cloudTime+0.5)
	if player.Parent then
		resetExecutedPlayer(player)
		player:SetAttribute("SentenceSeconds",0);player:SetAttribute("BookingState","Executed");player:SetAttribute("CustodyPhase","Executed")
		player:SetAttribute("DeathRowExecutionComplete",true)
		-- v196: close the jail / State Prison HUD (normal releases send this too).
		tell(player,"Released","executed")
		print("[DeathRow] execution sequence complete for "..player.Name)
	end
	deathRowExecutionActive[player]=nil
end

openFor = function(target: Instance, secs: number)
	local ancestor: Instance?=target
	while ancestor and ancestor~=prison do
		if ancestor:GetAttribute("CustodyLocked")==true then return end
		ancestor=ancestor.Parent
	end
	local untilT = os.clock() + secs
	openUntil[target] = untilT
	setOpen(target, true)
	task.delay(secs, function()
		if openUntil[target] == untilT then
			openUntil[target] = nil
			setOpen(target, false)
		end
	end)
end

-- v102: physical correctional vehicle gates.  The previous generic openFor()
-- only disabled collision/faded parts; it did not actually clear the cruiser path.
-- GATE1/GATE2 (when present) are treated as sliding leaves and moved outward
-- along the gate's horizontal span, then returned to their exact saved CFrames.
local vehicleGateState: { [Instance]: any } = {}

local function gateLeafCandidates(container: Instance): {Instance}
	local exact={}
	for _,d in container:GetDescendants() do
		local n=string.upper(d.Name)
		if (n=="GATE1" or n=="GATE2") and (d:IsA("Model") or d:IsA("BasePart")) then
			table.insert(exact,d)
		end
	end
	if #exact>=1 then return exact end
	-- Compatibility fallback: direct children that look like movable gate leaves.
	local fallback={}
	for _,d in container:GetChildren() do
		local n=string.lower(d.Name)
		if (d:IsA("Model") or d:IsA("BasePart")) and string.find(n,"gate",1,true) then
			table.insert(fallback,d)
		end
	end
	return fallback
end

local function gateLeafParts(leaf: Instance): {BasePart}
	local parts={}
	if leaf:IsA("BasePart") then
		table.insert(parts,leaf)
	else
		for _,p in leaf:GetDescendants() do
			if p:IsA("BasePart") then table.insert(parts,p) end
		end
	end
	return parts
end

-- v218: the sally-port gates are now swing gates: each GATE model has an anchored
-- "pivitPoint" with a Motor6D per leaf, jointed at the leaf's outer end. Opening
-- swings each leaf 90 degrees about its hinge (toward the pivot side) by tweening
-- the Motor6D's C0, with the leaves non-collidable while they move / stand open.
local swingState: { [Instance]: any } = {}

local function swingGates(target: Instance): { Model }
	local out={}
	local function consider(m: Instance)
		if m:IsA("Model") then
			for _,d in m:GetDescendants() do
				if d:IsA("Motor6D") and d.Part0 and d.Part1 and d.Part0.Anchored then
					table.insert(out,m)
					break
				end
			end
		end
	end
	local n=string.upper(target.Name)
	if n=="GATE" or n=="GATE1" or n=="GATE2" then consider(target) end
	if #out==0 then
		for _,c in target:GetChildren() do
			local cn=string.upper(c.Name)
			if cn=="GATE" or cn=="GATE1" or cn=="GATE2" or cn=="GATE3" then consider(c) end
		end
	end
	return out
end

local function swingGateOpen(gate: Model, secs: number)
	local st=swingState[gate]
	if not st then
		st={untilT=0, motors={}, parts={}}
		for _,d in gate:GetDescendants() do
			if d:IsA("Motor6D") and d.Part0 and d.Part1 and d.Part0.Anchored then
				local p0: BasePart=d.Part0
				local hinge=d.C0.Position
				-- where this leaf's middle sits, in the pivot's space
				local leafModel=d.Part1:FindFirstAncestorWhichIsA("Model")
				local mid: Vector3=d.Part1.Position
				if leafModel and leafModel~=gate then
					local sum,n=Vector3.zero,0
					for _,q in leafModel:GetDescendants() do if q:IsA("BasePart") then sum+=q.Position;n+=1 end end
					if n>0 then mid=sum/n end
				end
				local dir=p0.CFrame:PointToObjectSpace(mid)-hinge
				local best,bestD=math.rad(90),math.huge
				for _,a in {math.rad(90),math.rad(-90)} do
					local d2=(hinge+CFrame.Angles(0,a,0):VectorToWorldSpace(dir)).Magnitude
					if d2<bestD then best,bestD=a,d2 end
				end
				table.insert(st.motors,{m=d, closed=d.C0, opened=CFrame.new(hinge)*CFrame.Angles(0,best,0)*d.C0.Rotation})
			end
		end
		-- v290: the leaves must hang free on their motors. They'd been anchored (every gate part was) -
		-- a Motor6D can't swing an anchored part, so the gates never opened for a transport. Everything
		-- but the hinge posts is welded to a leaf, so it's safe to free it here, server-owned.
		local posts={}
		for _,mo in st.motors do posts[mo.m.Part0]=true end
		for _,p in gate:GetDescendants() do
			if p:IsA("BasePart") and not posts[p] and p.Anchored then
				p.Anchored=false
				pcall(function() p:SetNetworkOwner(nil) end)
			end
		end
		for _,p in gate:GetDescendants() do
			if p:IsA("BasePart") and not p.Anchored then st.parts[p]=p.CanCollide end
		end
		swingState[gate]=st
	end
	local wasOpen=st.untilT>os.clock()
	st.untilT=math.max(st.untilT,os.clock()+secs)
	if not wasOpen then
		for p in st.parts do if p.Parent then p.CanCollide=false end end
		for _,mo in st.motors do
			TweenService:Create(mo.m,TweenInfo.new(2.2,Enum.EasingStyle.Quad,Enum.EasingDirection.InOut),{C0=mo.opened}):Play()
		end
		print("[PoliceSystem] PRISON SWING GATE OPEN: "..gate:GetFullName())
	end
	local mine=st.untilT
	task.delay(secs+0.05,function()
		if swingState[gate]~=st or st.untilT~=mine or os.clock()<st.untilT then return end
		for _,mo in st.motors do
			TweenService:Create(mo.m,TweenInfo.new(2.4,Enum.EasingStyle.Quad,Enum.EasingDirection.InOut),{C0=mo.closed}):Play()
		end
		task.delay(2.5,function()
			if os.clock()<st.untilT then return end
			for p,c in st.parts do if p.Parent then p.CanCollide=c end end
			print("[PoliceSystem] PRISON SWING GATE CLOSED: "..gate:GetFullName())
		end)
	end)
end

physicalGateOpen = function(target: Instance, secs: number)
	if not target or not target.Parent then return end
	local swings=swingGates(target)
	if #swings>0 then
		for _,g in swings do swingGateOpen(g,secs) end
		return
	end
	local leaves=gateLeafCandidates(target)
	if #leaves==0 then
		-- Unknown legacy gate structure: preserve old access behavior rather than fail closed.
		openFor(target,secs)
		return
	end

	-- v105: the real vehicle leaves are Workspace.CorrectionalFacility.GATE1/GATE2.
	-- Determine the opening axis from the two leaf centers themselves, NOT from the
	-- enormous CorrectionalFacility bounding box, then move EACH leaf exactly 60 studs
	-- away from the midpoint as requested.
	local function leafCenter(leaf: Instance): Vector3
		if leaf:IsA("BasePart") then return leaf.Position end
		local cf=leaf:GetBoundingBox();return cf.Position
	end
	local center=Vector3.zero
	for _,leaf in leaves do center+=leafCenter(leaf) end
	center/=#leaves
	local axis=Vector3.new(1,0,0)
	if #leaves>=2 then
		local delta=Util.flat(leafCenter(leaves[2])-leafCenter(leaves[1]))
		if delta.Magnitude>0.1 then axis=delta.Unit end
	else
		local leaf=leaves[1]
		local _,sz=if leaf:IsA("Model") then leaf:GetBoundingBox() else (leaf :: BasePart).CFrame,(leaf :: BasePart).Size
		axis=if sz.X>=sz.Z then Vector3.new(1,0,0) else Vector3.new(0,0,1)
	end
	local slideDistance=60

	local state=vehicleGateState[target]
	if not state then
		state={untilT=0, originals={}}
		vehicleGateState[target]=state
		for _,leaf in leaves do
			for _,p in gateLeafParts(leaf) do
				if not state.originals[p] then
					state.originals[p]={cf=p.CFrame,collide=p.CanCollide,trans=p.Transparency}
				end
			end
		end
	end
	state.untilT=math.max(state.untilT,os.clock()+secs)

	for _,leaf in leaves do
		local parts=gateLeafParts(leaf)
		if #parts>0 then
			local lc=leafCenter(leaf)
			local side=(lc-center):Dot(axis)>=0 and 1 or -1
			local delta=axis*(slideDistance*side)
			for _,p in parts do
				local original=state.originals[p]
				if original then
					p.CanCollide=false
					TweenService:Create(p,TweenInfo.new(1.25,Enum.EasingStyle.Quad,Enum.EasingDirection.Out),{CFrame=original.cf+delta}):Play()
				end
			end
		end
	end
	print(("[PoliceSystem] PRISON VEHICLE GATE OPEN: %s leaves=%d slide=%.1f"):format(target:GetFullName(),#leaves,slideDistance))

	local thisUntil=state.untilT
	task.delay(secs,function()
		local st=vehicleGateState[target]
		if not st or st.untilT~=thisUntil or os.clock()<st.untilT-0.05 then return end
		for p,original in st.originals do
			if p and p.Parent then
				TweenService:Create(p,TweenInfo.new(1.35,Enum.EasingStyle.Quad,Enum.EasingDirection.InOut),{CFrame=original.cf}):Play()
			end
		end
		task.delay(1.4,function()
			local newest=vehicleGateState[target]
			if newest~=st or os.clock()<st.untilT then return end
			for p,original in st.originals do
				if p and p.Parent then
					p.CanCollide=original.collide
					p.Transparency=original.trans
				end
			end
			vehicleGateState[target]=nil
			print("[PoliceSystem] PRISON VEHICLE GATE CLOSED: "..target:GetFullName())
		end)
	end)
end

local function staffPrompt(part: BasePart, target: Instance, label: string, secs: number)
	local prompt = Instance.new("ProximityPrompt")
	prompt.ActionText = label
	prompt.ObjectText = "Staff only"
	prompt.KeyboardKeyCode = Enum.KeyCode.E
	prompt.HoldDuration = 0.3
	prompt.MaxActivationDistance = 10
	prompt.RequiresLineOfSight = false
	prompt.Parent = part
	prompt.Triggered:Connect(function(player)
		if isStaff(player) and not inPrison(player) then
			openFor(target, secs)
		else
			tell(player, "Notice", "Locked - staff only")
		end
	end)
end

local function biggestPart(m: Instance): BasePart?
	local best, size = nil, 0
	for _, p in m:GetDescendants() do
		if p:IsA("BasePart") then
			local v = p.Size.X * p.Size.Y * p.Size.Z
			if v > size then
				best, size = p, v
			end
		end
	end
	return best
end

local function setupDoors()
	if prison then
		local hasNamedVehicleGates=(prison:FindFirstChild("GATE")~=nil or prison:FindFirstChild("GATE1")~=nil or prison:FindFirstChild("GATE2")~=nil)
		for _, c in prison:GetChildren() do
			if c.Name == "PrisonAccess" and c:IsA("BasePart") then
				CollectionService:AddTag(c, "PoliceAutoDoor")
				staffPrompt(c, c, "Open door", 4)
			elseif c.Name == "PrisonGates" then
				CollectionService:AddTag(c, "PoliceAutoDoor")
				local p = biggestPart(c)
				if p then
					staffPrompt(p, c, "Open gate", 10)
				end
			end
		end
		if hasNamedVehicleGates then
			local promptPart=biggestPart(prison:FindFirstChild("GATE") or prison:FindFirstChild("GATE1") or prison:FindFirstChild("GATE2"))
			if promptPart then
				CollectionService:AddTag(promptPart,"PoliceAutoDoor")
				local prompt=Instance.new("ProximityPrompt")
				prompt.ActionText="Open vehicle gates";prompt.ObjectText="Correctional sally port"
				prompt.KeyboardKeyCode=Enum.KeyCode.E;prompt.HoldDuration=0.3;prompt.MaxActivationDistance=12;prompt.RequiresLineOfSight=false;prompt.Parent=promptPart
				prompt.Triggered:Connect(function(player)
					if isStaff(player) and not inPrison(player) then physicalGateOpen(prison,18) else tell(player,"Notice","Locked - staff only") end
				end)
			end
			-- v218: police / staff vehicles (player or AI driven) open the gate they drive up to
			local swings=swingGates(prison)
			if #swings>0 then
				local centers={}
				for _,g in swings do
					local sum,n=Vector3.zero,0
					for _,q in g:GetDescendants() do if q:IsA("BasePart") and not q.Anchored then sum+=q.Position;n+=1 end end
					if n>0 then table.insert(centers,{gate=g,pos=sum/n}) end
				end
				task.spawn(function()
					while prison and prison.Parent do
						task.wait(0.4)
						for _,c in centers do
							local ok,parts=pcall(function() return Workspace:GetPartBoundsInRadius(c.pos,60) end)
							if ok then
								for _,part in parts do
									-- v219: AI cruisers / vans / armored trucks are seatless "ghost cars"
									-- in the PoliceVehicle collision group
									if part.CollisionGroup=="PoliceVehicle" then
										swingGateOpen(c.gate,8);break
									end
									if part:IsA("VehicleSeat") then
										local occ=part.Occupant
										local driver=occ and Players:GetPlayerFromCharacter(occ.Parent)
										local car=part:FindFirstAncestorWhichIsA("Model")
										local civilian=car and (car:GetAttribute("TrafficActive")==true or car:GetAttribute("StolenVehicle")==true)
										local allowed=false
										if driver then
											allowed=isStaff(driver) and not inPrison(driver)
										elseif not civilian then
											allowed=occ~=nil or part.AssemblyLinearVelocity.Magnitude>3
										end
										if allowed then swingGateOpen(c.gate,7);break end
									end
								end
							end
						end
					end
				end)
			end
		end
		-- cell block control panels: each button toggles that block's cell doors
		local allCells: { Instance } = {}
		for _, d in prison:GetDescendants() do
			if d.Name == "CellDoor" and d:IsA("Model") then
				table.insert(allCells, d)
			end
		end
		for _, panel in prison:GetChildren() do
			if panel.Name == "ControlPanel" then
				for _, button in panel:GetChildren() do
					local cd = button:FindFirstChildOfClass("ClickDetector")
					if cd then
						local block = prison:FindFirstChild(button.Name)
						local cells: { Instance } = {}
						if block then
							for _, d in block:GetDescendants() do
								if d.Name == "CellDoor" and d:IsA("Model") then
									table.insert(cells, d)
								end
							end
						end
						if #cells == 0 then
							cells = allCells
						end
						local open = false
						cd.MouseClick:Connect(function(player)
							if not isStaff(player) or inPrison(player) then
								return
							end
							open = not open
							for _, cell in cells do
								setOpen(cell, open)
							end
							tell(player, "Notice", (if open then "Opened " else "Closed ") .. button.Name .. " cells")
						end)
					end
				end
			end
		end
	end
	local station = Workspace:FindFirstChild("PoliceStation")
	if station then
		for _, c in station:GetChildren() do
			if (c.Name == "RestrictedDoor" or c.Name == "CellDoor") and c:IsA("Model") then
				CollectionService:AddTag(c, "PoliceAutoDoor")
				local p = biggestPart(c)
				if p then
					staffPrompt(p, c, "Open door", 4)
				end
			end
		end
	end
end

---------------------------------------------------------------------------
-- client requests
---------------------------------------------------------------------------
local function targetInRange(officer: Player, target: any, range: number): (Player?, BasePart?)
	if typeof(target) ~= "Instance" or not target:IsA("Player") or target == officer then
		return nil, nil
	end
	local _, _, oRoot = Util.charInfo(officer)
	local _, tHum, tRoot = Util.charInfo(target)
	if not oRoot or not tRoot or not tHum or tHum.Health <= 0 then
		return nil, nil
	end
	if (oRoot.Position - tRoot.Position).Magnitude > range then
		return nil, nil
	end
	return target, tRoot
end

local function equipped(player: Player, kind: string): Tool?
	local char = player.Character
	if not char then
		return nil
	end
	for _, t in char:GetChildren() do
		if t:IsA("Tool") and t:GetAttribute("PoliceTool") == kind then
			return t
		end
	end
	return nil
end

local function onRequest(player: Player, action: any, arg: any)
	if action == "Surrender" then
		if not Config.Surrender.Enabled then
			return
		end
		local p = Heat.get(player)
		if not p then
			return
		end
		local on = arg == true
		if not on and p.surrendered and p.arrestProgress > 0.3 then
			Heat.addCrime(player, "ResistingArrest")
		end
		if Heat.setSurrender(player, on) and on then
			radio(string.format("%s is surrendering %s", player.Name, Justice.placeName(p.lastSeenPos or Vector3.zero)), p.lastSeenPos, p.stars)
		end
	elseif action == "Cuff" then
		if not Util.isLaw(player) or not equipped(player, "Cuffs") then
			return
		end
		local target, tRoot = targetInRange(player, arg, LCFG.CuffRange)
		if not target or not tRoot then
			return
		end
		if (target:GetAttribute("WantedStars") or 0) <= 0 then
			tell(player, "Notice", target.Name .. " isn't wanted")
			return
		end
		Justice.jail(target, player)
	elseif action == "Tase" then
		if not Util.isLaw(player) or not equipped(player, "Taser") then
			return
		end
		local now = os.clock()
		if now - (lastTase[player] or 0) < LCFG.TaserCooldown then
			return
		end
		local target, tRoot = targetInRange(player, arg, LCFG.TaserRange)
		if not target or not tRoot then
			return
		end
		if (target:GetAttribute("WantedStars") or 0) <= 0 then
			tell(player, "Notice", "You can only tase wanted suspects")
			return
		end
		lastTase[player] = now
		local _, _, oRoot = Util.charInfo(player)
		local tool = equipped(player, "Taser")
		local handle = tool and tool:FindFirstChild("Handle")
		local from = if handle and handle:IsA("BasePart") then handle.Position elseif oRoot then oRoot.Position else tRoot.Position
		local tChar = target.Character
		local aimPart = tChar and (Util.aimPart(tChar) or tRoot) or tRoot
		if tChar and __require("Weapons").fireTaserProbe(from, tChar, aimPart, { player.Character }) then
			Heat.stun(target, LCFG.TaserStun)
		end
	elseif action == "SelectCounsel" then
		if player:GetAttribute("BookingState")~="Booking" or not bookingCase[player] or player:GetAttribute("CounselName") then return end
		local name=tostring(arg or "")
		local counsel=COUNSEL[name]
		if not counsel then return end
		-- v257: counsel is a retainer + hourly billing (LawFirms); a firm already on retainer costs nothing here
		local law=ServerStorage:FindFirstChild("LawFirms")
		if law and law:IsA("BindableFunction") then
			local okL,res=pcall(law.Invoke,law,"hireAtBooking",player,name)
			if not okL or res~=true then
				tell(player,"Notice",tostring(if okL then res else "Counsel unavailable"))
				return
			end
		elseif counsel.price>0 and not charge(player,counsel.price) then
			tell(player,"Notice",string.format("You need $%d for %s",counsel.price,name))
			return
		end
		task.spawn(finishPrisonCase,player,name)
	elseif action == "RequestCounselMenu" then
		local case=bookingCase[player]
		if player:GetAttribute("BookingState")=="Booking" and case then
			tell(player,"BookingReady",math.max(1,select(2,string.gsub(case.text,",",""))+1),case.text)
		end
	elseif action == "Bail" then
		if not inPrison(player) then
			return
		end
		local price = bailPrice(player)
		if price <= 0 then
			if sentenceEnd[player] then tell(player, "Notice", "No bail for death row or solitary inmates") end
			return
		end
		if charge(player, price) then
			task.spawn(release,player,"bail")
		else
			tell(player, "Notice", string.format("Bail is $%d - you can't afford it", price))
		end
	elseif action == "Sync" then
		sendJailState(player)
	end
end

---------------------------------------------------------------------------
-- compatibility: ServerStorage.ReportCrime (player, crimeName, stars)
---------------------------------------------------------------------------
local function external(player: any, crimeName: any, stars: any): boolean
	if typeof(player) ~= "Instance" or not player:IsA("Player") then
		return false
	end
	local name = tostring(crimeName or "Crime")
	local internal = Config.ExternalCrimes[name]
	local now = os.clock()
	-- the same murder is often reported both by us and by the civilian scripts
	if internal and recentCrime[player] and now - (recentCrime[player][internal] or 0) < 3 then
		return true
	end
	if internal then
		return Heat.addCrime(player, internal)
	end
	local n = math.clamp(math.floor(tonumber(stars) or 1), 1, 5)
	return Heat.addCrime(player, name, nil, nil, {
		Heat = Config.Heat.StarThresholds[n] + 5,
		MinStars = n,
		Hostile = n >= 2,
		Charge = name,
	})
end

---------------------------------------------------------------------------
-- v95 BASIC PRISON GUARD PROTOTYPE
-- Uses the user's Prison Mapper polygons as patrol destinations.  This is
-- intentionally a small, observable foundation: correctional officers walk
-- between mapped non-cell zones, automatically operate nearby prison doors,
-- and let those doors close/relock after they have passed.
---------------------------------------------------------------------------
local prisonGuardPatrols: { any } = {}

local function mappedZoneCenter(zone: Instance): Vector3?
	local cp=zone:FindFirstChild("ControlPoints")
	if cp then
		local pts={}
		for _,v in cp:GetChildren() do
			if v:IsA("Vector3Value") then table.insert(pts,v.Value) end
		end
		if #pts>0 then
			local sum=Vector3.zero
			for _,p in pts do sum+=p end
			local avg=sum/#pts
			local bottom=tonumber(zone:GetAttribute("BottomY")) or avg.Y
			local probe=Vector3.new(avg.X,bottom+5,avg.Z)
			local ground=Util.groundAt(probe,8,24)
			return ground and Vector3.new(avg.X,ground.Y+2.8,avg.Z) or Vector3.new(avg.X,bottom+2.8,avg.Z)
		end
	end
	if zone:IsA("BasePart") then return zone.Position end
	if zone:IsA("Model") then return zone:GetPivot().Position end
	return nil
end

local function prisonPatrolPoints(): { {zone:Instance,pos:Vector3,kind:string} }
	local result={}
	local map=prisonMapRoot()
	local zones=map and map:FindFirstChild("Zones")
	if not zones then return result end
	for _,zone in zones:GetChildren() do
		if zone:GetAttribute("PrisonZone")==true or zone:FindFirstChild("ControlPoints") then
			local kind=tostring(zone:GetAttribute("ZoneType") or zone.Name)
			local k=string.lower(kind)
			local n=string.lower(zone.Name)
			if not string.find(k,"cell",1,true) and not string.find(n,"cell",1,true) then
				local pos=mappedZoneCenter(zone)
				if pos then table.insert(result,{zone=zone,pos=pos,kind=kind}) end
			end
		end
	end
	return result
end

local function guardStartZones(points:{any}): {any}
	local towers={}
	for _,entry in points do
		local text=string.lower(entry.zone.Name.." "..entry.kind)
		if string.find(text,"tower",1,true) or string.find(text,"guard",1,true) then
			table.insert(towers,entry)
		end
	end
	if #towers>0 then return towers end
	local starts={}
	for i=1,math.min(2,#points) do table.insert(starts,points[i]) end
	return starts
end

local function nearestPatrolChoices(points:{any},from:Vector3):{any}
	local copy={}
	for _,entry in points do
		local d=Util.flat(entry.pos-from).Magnitude
		if d>10 and d<420 then table.insert(copy,{entry=entry,d=d}) end
	end
	table.sort(copy,function(a,b) return a.d<b.d end)
	local out={}
	for i=1,math.min(7,#copy) do table.insert(out,copy[i].entry) end
	return out
end

local function spawnPrisonPatrol(index:number,start:any,points:{any})
	local cop=nameEscort(escortCop(start.pos,Vector3.new(0,0,-1)),"CORRECTIONAL OFFICER")
	if not cop or not cop.model then return end
	cop.model.Name="PrisonGuard_"..tostring(index)
	cop.model:SetAttribute("PrisonGuardPrototype",true);game:GetService("CollectionService"):AddTag(cop.model,"PrisonCO")
	cop.model:SetAttribute("GuardHomeZone",start.zone.Name)
	cop.cfg.WalkSpeed=math.max(8,math.min(cop.cfg.WalkSpeed,11))
	prisonGuardPatrols[cop]=true
	task.spawn(function()
		local current=start
		local lastPos=cop.root.Position
		local lastProgress=os.clock()
		while cop.alive and cop.model.Parent and prison and prison.Parent do
			local choices=nearestPatrolChoices(points,cop.root.Position)
			local target=if #choices>0 then choices[math.random(1,#choices)] else current
			current=target
			cop.model:SetAttribute("PatrolZone",target.zone.Name)
			local deadline=os.clock()+36
			lastPos=cop.root.Position;lastProgress=os.clock()
			while cop.alive and os.clock()<deadline do
				openPrisonDoorsNear(cop.root.Position,30,4.5)
				openPrisonDoorsNear(target.pos,12,3.5)
				local dist=Util.flat(target.pos-cop.root.Position).Magnitude
				if dist<6 and math.abs(target.pos.Y-cop.root.Position.Y)<12 then break end
				cop:moveTo(target.pos,false);cop:updateAnim()
				if (cop.root.Position-lastPos).Magnitude>2 then
					lastPos=cop.root.Position;lastProgress=os.clock()
				elseif os.clock()-lastProgress>8 then
					openPrisonDoorsNear(cop.root.Position,42,5)
					break
				end
				task.wait(0.18)
			end
			cop:stop()
			task.wait(math.random(8,20)/10)
		end
		prisonGuardPatrols[cop]=nil
	end)
end

local function startPrisonGuardPrototype()
	if not prison then return end
	-- v116: guards patrol their assigned areas over the prison navigation graph
	if PrisonNav then
		local t0=os.clock()
		while not PrisonNav.ready and PrisonNav.building ~= false and os.clock()-t0<45 do task.wait(0.5) end
		if PrisonNav.ready then
			local spawned=0
			for _,zoneKey in PrisonNav.Config.PatrolZones do
				-- v200: a permanent, armed patrol post. If the officer is killed or
				-- removed, a replacement reports for duty after a short delay.
				local start=PrisonNav.patrolStart(zoneKey)
				if start then
					spawned+=1
					task.spawn(function()
						while prison and prison.Parent do
							local from=PrisonNav.patrolStart(zoneKey) or start
							local cop=nameEscort(escortCop(from,Vector3.new(0,0,-1)),"CORRECTIONAL OFFICER")
							if cop and cop.model then
								cop.model.Name="PrisonGuard_"..zoneKey
								cop.model:SetAttribute("PrisonGuardPrototype",true);game:GetService("CollectionService"):AddTag(cop.model,"PrisonCO")
								cop.model:SetAttribute("PatrolZone",zoneKey)
								cop.cfg.WalkSpeed=math.max(8,math.min(cop.cfg.WalkSpeed,11))
								prisonGuardPatrols[cop]=true
								pcall(function() cop:setGunOut(true) end)
								local ok,err=pcall(PrisonNav.patrol,cop,zoneKey,function()
									return cop.alive and cop.model~=nil and cop.model.Parent~=nil and prison~=nil and prison.Parent~=nil
								end)
								if not ok then warn("[PrisonNav] guard patrol error: "..tostring(err)) end
								prisonGuardPatrols[cop]=nil
								if cop.alive then pcall(function() cop:despawn("patrol ended") end) end
							end
							task.wait(30)
						end
					end)
				end
			end
			-- patrol loops holster between moves; keep every CO visibly armed
			task.spawn(function()
				while prison and prison.Parent do
					for cop in prisonGuardPatrols do
						if cop.alive then pcall(function() cop:setGunOut(true) end) end
					end
					task.wait(2)
				end
			end)
			if spawned>0 then
				print(("[PoliceSystem] PRISON GUARDS: %d graph patrol guard(s) (%s)"):format(spawned,table.concat(PrisonNav.Config.PatrolZones,", ")))
				return
			end
		end
	end
	local map=prisonMapRoot()
	if not map then
		warn("[PoliceSystem] PRISON GUARDS: no PrisonMap found; mapper patrol disabled")
		return
	end
	local points=prisonPatrolPoints()
	if #points<2 then
		warn("[PoliceSystem] PRISON GUARDS: fewer than 2 mapped non-cell zones; patrol disabled")
		return
	end
	local starts=guardStartZones(points)
	for i,start in starts do
		spawnPrisonPatrol(i,start,points)
	end
	print(("[PoliceSystem] PRISON GUARDS: %d patrol guard(s), %d mapped patrol zones"):format(#starts,#points))
end

---------------------------------------------------------------------------
-- v200 PRISON LIFE
--   * stationed armed COs at fixed posts in each cellblock (+ intake/booking),
--     replaced if killed, never recycled by the city dispatcher
--   * NPC inmates of each class in that class's uniform
--   * daily schedule from Config.PrisonSchedule + Lighting.ClockTime:
--     day = inmates in their cellblock common area; Lockdown/Count = they
--     walk to a cell door of their class and go in (no cell is reserved,
--     so player capacity is untouched); morning = they come back out.
---------------------------------------------------------------------------
-- Everything below lives in one do-block: the Justice module is close to
-- Luau's 200-local limit per function, and locals inside a block release
-- their registers when it ends. Only startPrisonLife is visible outside.
local startPrisonLife: () -> ()
do
local PL: any = {} -- all prison-life state and helpers (one local slot)
PL.PRISON_LIFE = {
	Posts = { "MAXIMUM_SECURITY", "MEDIUM_SECURITY", "LOW_SECURITY", "INTAKE", "BOOKING", "YARD", "CAFETERIA", "SUPERMAX", "INDOOR_YARD" },
	GuardRespawn = 30,
	Inmates = {
		{ class = "Low", count = 4, area = "LOW_SECURITY", cells = "LowSecurity" },
		{ class = "Medium", count = 5, area = "MEDIUM_SECURITY", cells = "MediumSecurity" },
		{ class = "High", count = 3, area = "MAXIMUM_SECURITY", cells = "HighSecurity" },
		{ class = "Maximum", count = 2, area = "MAXIMUM_SECURITY", cells = "MaximumSecurity" },
		{ class = "Supermax", count = 3, area = "SUPERMAX", cells = "Supermax" },
		{ class = "Death Row", count = 1, area = nil, cells = "DeathRow" }, -- walkway outside the cells
	},
	InCellBlocks = { Lockdown = true, Count = true },
}

function PL.prisonLifeInCells(): boolean
	local hour=game:GetService("Lighting").ClockTime
	for _,b in Config.PrisonSchedule.Blocks do
		if hour>=b.Start and hour<b.Finish then return PL.PRISON_LIFE.InCellBlocks[b.Name]==true end
	end
	return true
end

function PL.classRooms(category: string): { any }
	local list={}
	local map=PrisonNav and PrisonNav.mapRoot
	local doors=map and map:FindFirstChild("DoorMarkers")
	if not doors then return list end
	for name,pair in PrisonNav.CellPairs do
		if pair.category==category then
			local door=doors:FindFirstChild(pair.door)
			if door then
				table.insert(list,{door=door,pos=pair.pos,name=name,category=category,open=pair.open==true})
			end
		end
	end
	return list
end

PL.guards = {}

-- v211: the nearest stationed CO runs to `pos` (a prison fight), shouts, and
-- goes back to the post. Returns the officer's model, or nil if nobody can come.
function PL.coRespond(pos: Vector3): Model?
	local best,bestD=nil,math.huge
	for cop in PL.guards do
		if cop.alive and cop.root and not cop.responding then
			local d=(cop.root.Position-pos).Magnitude
			if d<bestD and d<220 then best,bestD=cop,d end
		end
	end
	if not best then return nil end
	local cop=best
	cop.responding=true
	task.spawn(function()
		local label=cop.model and cop.model:FindFirstChild("PrisonRoleLabel",true)
		local text=label and label:FindFirstChildOfClass("TextLabel")
		local old=text and text.Text
		if text then text.Text="BREAK IT UP!" end
		local t0=os.clock()
		while cop.alive and os.clock()-t0<18 and (cop.root.Position-pos).Magnitude>5 do
			openPrisonDoorsNear(cop.root.Position,14,6)
			cop:moveTo(pos,true)
			pcall(function() cop:updateAnim() end)
			task.wait(0.4)
		end
		if cop.alive then cop:stop();pcall(function() cop:face(pos) end) end
		task.wait(4)
		if text and old then text.Text=old end
		cop.responding=false
	end)
	return cop.model
end

-- v288l: COs answer like police. The inmate gets a pursuit (the same wanted-star system as the
-- street, held inside the walls - no city units), and the nearest COs are woken up and assigned to
-- it: they close in, use batons and tasers, cuff - lethal force once someone has been killed. The
-- arrest goes through Justice.jail -> solitary + the charges. More prison stars, more COs.
local ENGAGE_CRIME={fighting="Assault",["attempted escape"]="PrisonEscape",rioting="Assault",["inciting a riot"]="Assault",["assaulting staff"]="AssaultOfficer",["killing staff"]="Murder"}
function PL.coEngage(player: Player, reason: string): boolean
	local _,_,root=Util.charInfo(player)
	if not root or not sentenceEnd[player] then return false end
	local crime=ENGAGE_CRIME[reason]
	if not crime then return false end
	local p=Heat.get(player)
	if not p or not p.active or (p.stars or 0)<1 then
		PrisonFlow.engaging=player
		pcall(Heat.addCrime,player,crime,root.Position,if reason=="killing staff" then 60 else nil)
		PrisonFlow.engaging=nil
		p=Heat.get(player)
	elseif reason=="killing staff" then
		PrisonFlow.engaging=player
		pcall(Heat.addCrime,player,crime,root.Position,60)
		PrisonFlow.engaging=nil
	end
	if reason=="killing staff" and p then pcall(Heat.authorizeLethal,player,"an officer was killed") end
	if not p then return false end
	PrisonFlow.coIncident[player]=os.clock()
	PrisonFlow.coCops[player]={}
	local stars=tonumber(player:GetAttribute("PrisonStars")) or 1
	local want=math.clamp(1+stars,2,6)
	local list={}
	for cop in PL.guards do
		if cop.alive and cop.root and not cop.engaged then table.insert(list,{cop=cop,d=(cop.root.Position-root.Position).Magnitude}) end
	end
	table.sort(list,function(a,b) return a.d<b.d end)
	local n=0
	for i=1,math.min(want,#list) do
		local cop=list[i].cop
		if list[i].d>260 then break end
		cop.engaged=true;cop.responding=true
		table.insert(PrisonFlow.coCops[player],cop)
		pcall(function() cop:activate() end)
		pcall(function() cop:assign(p) end)
		n+=1
		task.spawn(function()
			local t0=os.clock()
			while cop.alive and p.active and Heat.get(player)==p and sentenceEnd[player] and os.clock()-t0<240 do task.wait(1) end
			-- incident over: this officer goes off shift, the post gets a fresh one
			if cop.alive then pcall(function() cop:despawn("incident over") end) end
		end)
	end
	-- v290: the internal response. The street AI can't find its way through the prison (it got
	-- stuck outside cellblocks), so the responders are driven here: they walk the prison's door
	-- map (PrisonNav) to the room the inmate is in, open the doors at it (a Supermax cell has two),
	-- and the first to reach him tasers and cuffs him; he's then escorted to solitary - or to
	-- protective custody (the same isolation cells) if he's a PC inmate.
	local responders={}
	for _,c in PrisonFlow.coCops[player] do if c.alive then c.aiScripted=true;table.insert(responders,c) end end
	if #responders>0 and not PrisonFlow.responding[player] then
		PrisonFlow.responding[player]=true
		task.spawn(function()
			local t0=os.clock()
			local subdued=false
			while os.clock()-t0<180 and player.Parent and sentenceEnd[player] and not player:GetAttribute("EscapeInProgress") do
				local _,hum,r=Util.charInfo(player)
				if not r or not hum or hum.Health<=0 then break end
				local any=false
				for _,cop in responders do
					if cop.alive and cop.root then
						any=true
						local d=Util.flat(cop.root.Position-r.Position).Magnitude
						local dy=math.abs(cop.root.Position.Y-r.Position.Y)
						if d<22 then openPrisonDoorsNear(r.Position,16,10) end
						if d<6 and dy<5 then
							subdued=true
							pcall(function() cop:stop();cop:face(r.Position) end)
							pcall(Heat.stun,player,4)
							print(("[PrisonLife] CO SUBDUED %s (taser) at %s"):format(player.Name,tostring(r.Position)))
							break
						end
						if not cop.navBusy then
							cop.navBusy=true
							task.spawn(function()
								pcall(function()
									PrisonNav.travel(cop,r.Position,{alive=function()
										local _,_,rr=Util.charInfo(player)
										return cop.alive and not subdued and rr~=nil and Util.flat(cop.root.Position-rr.Position).Magnitude>5
									end,maxTime=8,label="CO RESPOND "..player.Name,logRoute=false})
								end)
								cop.navBusy=nil
							end)
						end
					end
				end
				if subdued or not any then break end
				task.wait(0.4)
			end
			PrisonFlow.responding[player]=nil
			if subdued and player.Parent and sentenceEnd[player] then
				task.wait(2)
				PrisonFlow.coIncident[player]=nil
				if Heat.get(player) then Heat.clear(player,"Contained") end
				for _,cop in responders do if cop.alive then pcall(function() cop:despawn("inmate subdued") end) end end
				local X=PrisonFlow.extras
				if X and X.inSolitary and X.inSolitary[player] then
					-- he was already serving time in the hole and got out of it: straight back
					local room=PrisonFlow.pick(player,"Solitary")
					if room then
						custody[player]=true
						if PrisonFlow.deliver(player,"CORRECTIONAL OFFICER",room,"HOUSING_ESCORT") then
							housingAssignment[player]=room.cell;player:SetAttribute("AssignedCell",room.name)
						end
						custody[player]=nil
					end
				elseif X and X.solitaryPlayer then
					task.spawn(X.solitaryPlayer,player,reason,player:GetAttribute("ProtectiveCustody")==true)
				end
			else
				for _,cop in responders do if cop.alive then cop.aiScripted=nil end end
			end
		end)
	end
	print(("[PrisonLife] CO ENGAGE %s (%s, %d prison stars, %d heat stars): %d COs"):format(player.Name,reason,stars,p.stars or 0,n))
	return n>0
end
PrisonFlow.coEngage=PL.coEngage -- (PL is local to its block; the tower alarm reaches it through PrisonFlow)

function PL.startStationedGuards()
	for _,area in PL.PRISON_LIFE.Posts do
		task.spawn(function()
			local post=PrisonNav.patrolStart(area)
			if not post then warn("[PrisonLife] no post position for "..area);return end
			while prison and prison.Parent do
				local cop=nameEscort(escortCop(post,Vector3.new(0,0,-1)),"CORRECTIONAL OFFICER")
				if cop and cop.model then
					cop.model.Name="PrisonPost_"..area
					cop.model:SetAttribute("PrisonGuardPost",area);game:GetService("CollectionService"):AddTag(cop.model,"PrisonCO")
					prisonGuardPatrols[cop]=true
					PL.guards[cop]=area
					pcall(function() cop:setGunOut(true) end)
					local lookAt=post+Vector3.new(math.random(-10,10),0,math.random(-10,10))
					while cop.alive and cop.model and cop.model.Parent do
						if cop.responding then
							-- answering a fight call (PL.coRespond)
						elseif Util.flat(cop.root.Position-post).Magnitude>5 then
							cop:moveTo(post,false)
						else
							cop:stop()
							if math.random()<0.25 then lookAt=post+Vector3.new(math.random(-12,12),0,math.random(-12,12)) end
							pcall(function() cop:face(lookAt) end)
						end
						pcall(function() cop:updateAnim() end)
						task.wait(1.5)
					end
					prisonGuardPatrols[cop]=nil
					PL.guards[cop]=nil
				end
				task.wait(PL.PRISON_LIFE.GuardRespawn)
			end
		end)
	end
end

-- v205: the city pedestrian templates are old R6 bodies with no
-- HumanoidRootPart, which the prison navigation and escorts need. Every prison
-- NPC is a generated R15 rig wearing a pedestrian's clothes instead.
function PL.buildRig(look: Model?): Model?
	local ok,rig=pcall(function()
		return Players:CreateHumanoidModelFromDescription(Instance.new("HumanoidDescription"),Enum.HumanoidRigType.R15)
	end)
	if not ok or not rig then warn("[PrisonLife] couldn't generate an R15 rig: "..tostring(rig));return nil end
	if look then
		for _,c in look:GetChildren() do
			if c:IsA("Shirt") or c:IsA("Pants") or c:IsA("BodyColors") or c:IsA("ShirtGraphic") then
				if c:IsA("BodyColors") then local old=rig:FindFirstChildOfClass("BodyColors");if old then old:Destroy() end end
				local okc,copy=pcall(function() local a=c.Archivable;c.Archivable=true;local k=c:Clone();c.Archivable=a;return k end)
				if okc and copy then copy.Parent=rig end
			end
		end
	end
	-- v215: every NPC gets their own skin tone (independent of gang or class)
	do
		local tones={Color3.fromRGB(255,224,196),Color3.fromRGB(241,194,158),Color3.fromRGB(224,172,105),Color3.fromRGB(198,134,66),
			Color3.fromRGB(161,110,75),Color3.fromRGB(141,85,36),Color3.fromRGB(111,70,38),Color3.fromRGB(86,53,32),Color3.fromRGB(60,38,24)}
		local tone=tones[math.random(1,#tones)]
		local bc=rig:FindFirstChildOfClass("BodyColors") or Instance.new("BodyColors")
		bc.HeadColor3=tone;bc.TorsoColor3=tone;bc.LeftArmColor3=tone;bc.RightArmColor3=tone;bc.LeftLegColor3=tone;bc.RightLegColor3=tone
		bc.Parent=rig
	end
	PL.animate(rig)
	local rigHum=rig:FindFirstChildOfClass("Humanoid")
	if rigHum then
		-- prison NPCs never sit down on benches, seats or bunks and get stuck there
		rigHum:SetStateEnabled(Enum.HumanoidStateType.Seated,false)
	end
	return rig
end

-- v205: server-side walk/idle for prison NPC rigs (the rig's Animate script
-- is a LocalScript and never runs on a server-owned NPC).
function PL.animate(rig: Model)
	local hum=rig:FindFirstChildOfClass("Humanoid")
	if not hum then return end
	-- animations only load once the rig is in the workspace
	task.spawn(function()
	local t0=os.clock()
	while not rig:IsDescendantOf(Workspace) do
		if os.clock()-t0>60 then return end
		task.wait(0.5)
	end
	local animator=hum:FindFirstChildOfClass("Animator") or Instance.new("Animator",hum)
	local function load(id: string): AnimationTrack?
		local a=Instance.new("Animation");a.AnimationId=id
		local ok,t=pcall(function() return animator:LoadAnimation(a) end)
		return if ok then t else nil
	end
	local walk,idle=load("rbxassetid://507777826"),load("rbxassetid://507766388")
	if idle then idle.Looped=true;idle:Play() end
	if walk then walk.Looped=true end
	hum.Running:Connect(function(speed: number)
		if not walk then return end
		if speed>0.5 then
			if not walk.IsPlaying then walk:Play(0.2) end
			walk:AdjustSpeed(math.clamp(speed/8,0.5,1.6))
		elseif walk.IsPlaying then walk:Stop(0.2) end
	end)
	end)
end

-- CivilianServer moves Workspace.AIHolder into ServerStorage.CivilianTemplates
-- when it starts, which can be after this script: wait for it, then fall back to
-- the AIHolder models, then to an undressed rig.
function PL.cloneTemplate(): Model?
	local templates=ServerStorage:FindFirstChild("CivilianTemplates") or ServerStorage:WaitForChild("CivilianTemplates",30)
	local pool={}
	for _,m in (templates and templates:GetChildren() or {}) do
		if m:IsA("Model") and m:FindFirstChildOfClass("Humanoid") then table.insert(pool,m) end
	end
	if #pool==0 then
		local holder=workspace:FindFirstChild("AIHolder")
		for _,m in (holder and holder:GetChildren() or {}) do
			if m:IsA("Model") and m:FindFirstChildOfClass("Humanoid") then table.insert(pool,m) end
		end
	end
	return PL.buildRig(if #pool>0 then pool[math.random(1,#pool)] else nil)
end

function PL.makeInmateNpc(class: string): (Model?, Humanoid?, BasePart?)
	local npc=PL.cloneTemplate()
	if not npc then return nil end
	for _,d in npc:GetDescendants() do
		-- keep the walk animation; drop the civilian AI / dealer behaviour
		if d:IsA("BaseScript") and d.Name~="Animate" then d:Destroy() end
	end
	local hum=npc:FindFirstChildOfClass("Humanoid");local root=npc:FindFirstChild("HumanoidRootPart")
	if not hum or not root then npc:Destroy();return nil end
	for _,d in npc:GetChildren() do if d:IsA("Shirt") or d:IsA("Pants") or d:IsA("Accessory") then d:Destroy() end end
	-- the uniform goes on once the NPC is in the world (ApplyDescription needs it)
	npc.Name=class.." Inmate"
	npc:SetAttribute("PrisonNPCInmate",class)
	hum.DisplayName=class.." Inmate"
	hum.WalkSpeed=7
	hum.DisplayDistanceType=Enum.HumanoidDisplayDistanceType.Viewer
	for _,d in npc:GetDescendants() do if d:IsA("BasePart") then d.Anchored=false end end
	return npc,hum,root
end

-- One NPC inmate's day: common area by day, their cell at Lockdown/Count.
-- v211: walk an NPC somewhere without getting stuck: jump out of seats, hop
-- over snags, give up (false) after repeated stalls so the caller picks a new spot.
function PL.walk(npc: Model, hum: Humanoid, root: BasePart, target: Vector3, timeout: number?): boolean
	local deadline=os.clock()+(timeout or 20)
	local last,lastMove,stalls=root.Position,os.clock(),0
	while os.clock()<deadline and hum.Health>0 and npc.Parent do
		if npc:GetAttribute("SocietyBusy") then return false end
		if hum.Sit or hum.SeatPart then hum.Sit=false;hum.Jump=true end
		if Util.flat(root.Position-target).Magnitude<3 then return true end
		hum:MoveTo(target)
		if Util.flat(root.Position-last).Magnitude>1 then
			last,lastMove=root.Position,os.clock()
		elseif os.clock()-lastMove>1.6 then
			stalls+=1
			hum.Jump=true
			-- sidestep around whatever is in the way
			local side=root.CFrame.RightVector*(if math.random()<0.5 then 4 else -4)
			hum:MoveTo(root.Position+side)
			task.wait(0.5)
			lastMove=os.clock()
			if stalls>=3 then return false end
		end
		task.wait(0.35)
	end
	return false
end

function PL.inmateLife(npc: Model, hum: Humanoid, root: BasePart, group: any, room: any, folder: Instance)
	local door=if room.open then room.pos else PrisonFlow.approach(room)
	local function dayPoint(): Vector3
		if group.area then return PrisonNav.patrolStart(group.area) or door end
		return door+Vector3.new(math.random(-6,6),0,math.random(-6,6))
	end
	npc:SetAttribute("PrisonNPCInmate",group.class)
	local inCell=false
	while hum.Health>0 and (npc.Parent or inCell) and prison and prison.Parent do
		if PL.prisonLifeInCells() then
			if not inCell then
				-- lights out: walk to the cell and go in
				if not room.open then openPrisonDoorsNear(door,10,6) end
				npc:SetAttribute("SocietyBusy",nil)
				npc:SetAttribute("InCell",true)
				if not PL.walk(npc,hum,root,door,25) and Util.flat(root.Position-door).Magnitude>6 then
					npc:PivotTo(CFrame.new(door+Vector3.new(0,3,0))) -- a CO walks them in; don't leave them roaming
				end
				-- open (low security) cells have no door: they stay visible on their bunk
				if not room.open then npc.Parent=nil end
				inCell=true
			end
			task.wait(5)
		else
			if inCell then
				-- morning: out of the cell
				if not npc.Parent then npc:PivotTo(CFrame.new(door+Vector3.new(0,3,0)));npc.Parent=folder end
				pcall(function() root:SetNetworkOwner(nil) end)
				npc:SetAttribute("InCell",nil)
				inCell=false
			end
			if npc:GetAttribute("SocietyBusy") then
				task.wait(1) -- talking / trading / fighting (PrisonSociety)
			else
				PL.walk(npc,hum,root,dayPoint(),20)
				local rest=os.clock()+math.random(3,10)
				while os.clock()<rest and not npc:GetAttribute("SocietyBusy") do
					if hum.Sit then hum.Sit=false;hum.Jump=true end
					task.wait(0.5)
				end
			end
		end
	end
	if npc.Parent then task.wait(10);npc:Destroy() end
end

function PL.prisonNpcFolder(): Instance
	local folder=Workspace:FindFirstChild("PrisonNPCs") or Instance.new("Folder")
	folder.Name="PrisonNPCs";folder.Parent=Workspace
	return folder
end

function PL.inmateGroup(class: string): any?
	for _,group in PL.PRISON_LIFE.Inmates do if group.class==class then return group end end
	return nil
end

function PL.startNpcInmates()
	local folder=PL.prisonNpcFolder()
	for _,group in PL.PRISON_LIFE.Inmates do
		local rooms=PL.classRooms(group.cells)
		if #rooms==0 then warn("[PrisonLife] no "..group.cells.." cells for "..group.class.." inmates");continue end
		for index=1,group.count do
			task.spawn(function()
				task.wait(index*0.7)
				local room=rooms[(index-1)%#rooms+1]
				while prison and prison.Parent do
					local npc,hum,root=PL.makeInmateNpc(group.class)
					if not npc then warn("[PrisonLife] couldn't build inmate NPC; retrying");task.wait(30);continue end
					local door=PrisonFlow.approach(room)
					local start=if PL.prisonLifeInCells() then door else (if group.area then PrisonNav.patrolStart(group.area) or door else door)
					npc:PivotTo(CFrame.new(start+Vector3.new(0,3,0)))
					npc.Parent=folder
					if inmateClothes[group.class] then pcall(PrisonFlow.wearUniform,npc,inmateClothes[group.class]) end
					PL.prisonNpcCollision(npc)
					pcall(function() root:SetNetworkOwner(nil) end)
					PL.inmateLife(npc,hum,root,group,room,folder)
					task.wait(40) -- a new inmate is processed in later
				end
			end)
		end
	end
	print("[PrisonLife] NPC inmates and stationed COs online")
end

---------------------------------------------------------------------------
-- v201 NPC ARRESTS: a civilian is arrested in the city, driven to the prison
-- and walked through intake -> booking -> dress-out -> housing by an intake
-- officer (same navigation, doors and corridors as players), then joins the
-- NPC inmate population. NPCs wait OUTSIDE intake/booking cells so player
-- cell capacity is never used.
---------------------------------------------------------------------------
PL.NPC_ARRESTS = {
	Enabled = true,
	Interval = { 60, 180 }, -- seconds between arrests (v212: always one within 5 minutes)
	MaxInFlight = 3, -- arrests on the road / in intake at the same time
	MaxHoused = 30, -- arrested NPCs kept in the prison at once (PrisonExtras caps each class)
	IntakeHold = 30, -- v218/v288: same intake hold a player gets (30 s)
	BookingHold = 30,
	Classes = { { "Low", 40 }, { "Medium", 35 }, { "High", 20 }, { "Death Row", 5 } },
}
PL.npcArrestHoused = 0

function PL.rollClass(): string
	local total=0
	for _,c in PL.NPC_ARRESTS.Classes do total+=c[2] end
	local roll=math.random()*total
	for _,c in PL.NPC_ARRESTS.Classes do roll-=c[2];if roll<=0 then return c[1] end end
	return "Medium"
end

-- v204: a live city pedestrian to arrest, dealers weighted 4x. Anything not
-- spawned by CivilianServer (players, police, prison NPCs) is never picked.
function PL.pickCitySuspect(): (Model?, Humanoid?, BasePart?)
	local pool,total={},0
	for _,m in Workspace:GetChildren() do
		if m:IsA("Model") and m:GetAttribute("CityCivilian") and not m:GetAttribute("PoliceArrested") and not Players:GetPlayerFromCharacter(m) then
			local h=m:FindFirstChildOfClass("Humanoid");local r=m:FindFirstChild("HumanoidRootPart") or m:FindFirstChild("Torso") or m.PrimaryPart
			if h and r and h.Health>0 then
				local w=if m:GetAttribute("Dealer") then 4 else 1
				total+=w;table.insert(pool,{m=m,h=h,r=r,w=w})
			end
		end
	end
	if total==0 then return nil end
	local roll=math.random()*total
	for _,c in pool do roll-=c.w;if roll<=0 then return c.m,c.h,c.r end end
	local c=pool[#pool];return c.m,c.h,c.r
end

-- v204: prison NPCs never physically block a player's cuff-walk or an officer.
function PL.prisonNpcCollision(npc: Model)
	pcall(function()
		local physics=game:GetService("PhysicsService")
		if not physics:IsCollisionGroupRegistered("PrisonNPC") then physics:RegisterCollisionGroup("PrisonNPC") end
		for _,g in {"PrisonNPC","PrisonEscort","PoliceNPC"} do
			if physics:IsCollisionGroupRegistered(g) then physics:CollisionGroupSetCollidable("PrisonNPC",g,false) end
		end
		Util.setCollisionGroup(npc,"PrisonNPC")
	end)
end

function PL.makeCivilianNpc(): (Model?, Humanoid?, BasePart?)
	local npc=PL.cloneTemplate()
	if not npc then return nil end
	for _,d in npc:GetDescendants() do
		if d:IsA("BaseScript") and d.Name~="Animate" then d:Destroy() end
	end
	local hum=npc:FindFirstChildOfClass("Humanoid");local root=npc:FindFirstChild("HumanoidRootPart")
	if not hum or not root then npc:Destroy();return nil end
	for _,d in npc:GetDescendants() do if d:IsA("BasePart") then d.Anchored=false end end
	hum.WalkSpeed=8
	return npc,hum,root
end

function PL.npcLabel(npc: Model, text: string)
	local head=npc:FindFirstChild("Head")
	if not head then return end
	local gui=head:FindFirstChild("NpcCustodyLabel")
	if not gui then
		gui=Instance.new("BillboardGui");gui.Name="NpcCustodyLabel";gui.Size=UDim2.fromOffset(170,26);gui.StudsOffset=Vector3.new(0,2.6,0);gui.AlwaysOnTop=false;gui.MaxDistance=90;gui.Parent=head
		local l=Instance.new("TextLabel");l.Name="L";l.Size=UDim2.fromScale(1,1);l.BackgroundTransparency=0.35;l.BackgroundColor3=Color3.fromRGB(25,25,25);l.TextColor3=Color3.fromRGB(255,190,90);l.Font=Enum.Font.GothamBold;l.TextScaled=true;l.Parent=gui
	end
	gui.L.Text=text
end

-- Walk the NPC (cuffed) with `cop` to `goal` through the prison graph. The
-- navigation only reads `.Character` from the escortee, so a stand-in works.
function PL.npcEscortTo(cop: any, npc: Model, goal: Vector3, label: string): boolean
	local stand={Character=npc,Name=npc.Name,Parent=npc.Parent}
	openPrisonDoorsNear(cop.root.Position,24,8);openPrisonDoorsNear(goal,24,8)
	local ok,res=pcall(function()
		local deadline=os.clock()+90 -- v211: an NPC escort never retries forever
		return PrisonNav.escort(cop,stand,goal,{alive=function() return cop.alive and npc.Parent~=nil and os.clock()<deadline end,maxTime=90,label=label,ignoreCharacter=npc})
	end)
	if ok and res then return true end
	warn(("[NPCArrest] %s escort failed (%s); short reposition"):format(label,tostring(res)))
	-- NPC-only last resort: keep the pipeline moving
	npc:PivotTo(CFrame.new(goal+Vector3.new(0,3,0)));cop.model:PivotTo(CFrame.new(goal+Vector3.new(3,3,0)))
	return false
end

-- v218: NPC arrivals are held INSIDE a free intake / booking cell (door shut)
-- for the hold, like a player, instead of standing outside it.
PL.npcHeldRooms = {}
function PL.npcPickRoom(category: string): any?
	local free={}
	for _,room in PL.classRooms(category) do
		if not PL.npcHeldRooms[room.name] then
			local taken=false
			for _,plr in Players:GetPlayers() do
				local _,_,r=Util.charInfo(plr)
				if r and Util.flat(r.Position-room.pos).Magnitude<6 and math.abs(r.Position.Y-room.pos.Y)<8 then taken=true;break end
			end
			if not taken then table.insert(free,room) end
		end
	end
	return if #free>0 then free[math.random(1,#free)] else nil
end
function PL.npcHoldIn(cop: any, npc: Model, category: string, secs: number, label: string)
	local room=PL.npcPickRoom(category)
	local hum=npc:FindFirstChildOfClass("Humanoid")
	local root=npc:FindFirstChild("HumanoidRootPart") :: BasePart?
	if not room or not hum or not root then
		if cop then cop:stop() end
		task.wait(secs)
		return
	end
	PL.npcHeldRooms[room.name]=true
	PL.npcEscortTo(cop,npc,PrisonFlow.approach(room),label)
	if not room.open then pcall(openMarkedDoor,room.door,7) end
	hum.WalkSpeed=8;hum:MoveTo(room.pos)
	local t=os.clock()+6
	while os.clock()<t and npc.Parent and Util.flat(root.Position-room.pos).Magnitude>2 do task.wait(0.2) end
	if npc.Parent and Util.flat(root.Position-room.pos).Magnitude>3 then npc:PivotTo(CFrame.new(room.pos+Vector3.new(0,3,0))) end
	if cop then cop:stop() end
	print(("[NPCArrest] %s held in %s for %ds"):format(label,room.name,secs))
	task.wait(secs)
	if npc.Parent and not room.open then pcall(openMarkedDoor,room.door,7) end
	if npc.Parent then
		hum:MoveTo(PrisonFlow.approach(room))
		local t2=os.clock()+5
		while os.clock()<t2 and npc.Parent and Util.flat(root.Position-PrisonFlow.approach(room)).Magnitude>3 do task.wait(0.2) end
	end
	PL.npcHeldRooms[room.name]=nil
end

function PL.npcArrestOnce()
	if not PrisonNav or not PrisonNav.ready then warn("[NPCArrest] prison navigation not ready");return end
	if PL.npcArrestHoused>=PL.NPC_ARRESTS.MaxHoused then return end
	local fac=facilities[#facilities]
	if not fac then return end
	local players=Players:GetPlayers()
	local anchor:Vector3?=nil
	for _,plr in players do
		local _,_,r=Util.charInfo(plr)
		if r and not sentenceEnd[plr] then anchor=r.Position;break end
	end
	anchor=anchor or dropOffPoint(fac)
	local class=PL.rollClass()
	if not class then return end -- v212: every class is at its NPC capacity
	-- v204: arrest a real city pedestrian (drug dealers far more often);
	-- only when none is available is a stand-in suspect spawned on a road.
	local npc,hum,root=PL.pickCitySuspect()
	local spot
	if npc and root then
		spot=root.Position
		npc:SetAttribute("PoliceArrested",true) -- CivilianServer stops its wander and spawns a replacement
		print(("[NPCArrest] city %s picked up at %s (will be %s)"):format(if npc:GetAttribute("Dealer") then "dealer" else "pedestrian",tostring(spot),class))
		-- swap the R6 pedestrian for an escort-ready rig wearing their clothes
		local rig=PL.buildRig(npc)
		npc:Destroy()
		if not rig then return end
		npc=rig;hum=rig:FindFirstChildOfClass("Humanoid");root=rig:FindFirstChild("HumanoidRootPart")
		if not hum or not root then rig:Destroy();return end
		for _,d in rig:GetDescendants() do if d:IsA("BasePart") then d.Anchored=false end end
		hum.WalkSpeed=8
		rig:PivotTo(CFrame.new(spot+Vector3.new(0,1,0)))
	else
		spot=RoadGraph.randomPoint(anchor,150,600) or RoadGraph.randomPoint(anchor,50,1500)
		if not spot then warn("[NPCArrest] no road point near "..tostring(anchor));return end
		npc,hum,root=PL.makeCivilianNpc()
		if not npc or not hum or not root then warn("[NPCArrest] couldn't build a suspect NPC");return end
		npc:PivotTo(CFrame.new(spot+Vector3.new(0,3,0)))
		print(("[NPCArrest] suspect at %s (will be %s)"):format(tostring(spot),class))
	end
	npc.Name="Suspect";npc:SetAttribute("NPCSuspect",true)
	npc.Parent=PL.prisonNpcFolder()
	PL.prisonNpcCollision(npc)
	pcall(function() root:SetNetworkOwner(nil) end)
	PL.npcLabel(npc,"WANTED")
	-- 1) a cruiser comes for them
	local arrived,failed,van=false,false,nil
	local start=RoadGraph.randomPoint(spot,200,450) or (spot+Vector3.new(250,0,0))
	Van.spawn("Cruiser",CFrame.new(start),function() return root.Position end,function(v) van=v;arrived=true end,function() failed=true end,true)
	local deadline=os.clock()+90
	while not arrived and not failed and os.clock()<deadline and npc.Parent do task.wait(0.5) end
	if not arrived or not van or van.dead then npc:Destroy();return end
	PL.npcLabel(npc,"UNDER ARREST")
	hum.WalkSpeed=0
	task.wait(2)
	-- 2) cuffed and loaded
	local body=van.body
	root.CFrame=body.CFrame*CFrame.new(1.4,body.Size.Y/2+0.6,-1.5)
	local weld=Instance.new("WeldConstraint");weld.Part0=body;weld.Part1=root;weld.Parent=body
	for _,d in npc:GetDescendants() do if d:IsA("BasePart") then d.CanCollide=false;d.Massless=true end end
	local roadDone=false
	van.transporting=true
	-- v219: the sally-port gates open for the NPC transport exactly like a player's
	if fac.gates then
		task.spawn(function()
			while van.transporting and not van.dead and body.Parent do
				local near=math.huge
				for _,g in swingGates(fac.model) do
					local ok,cf=pcall(g.GetPivot,g)
					if ok then near=math.min(near,Util.flat(cf.Position-body.Position).Magnitude) end
				end
				for _,gateName in {"GATE","GATE1","GATE2"} do
					local leaf=fac.model:FindFirstChild(gateName)
					if leaf and leaf:IsA("Model") then near=math.min(near,Util.flat(leaf:GetPivot().Position-body.Position).Magnitude) end
				end
				if near<=80 then pcall(physicalGateOpen,fac.gates,8) end
				task.wait(0.35)
			end
		end)
	end
	if not van:driveTo(dropOffPoint(fac),true,function() roadDone=true end) then
		weld:Destroy();npc:Destroy();pcall(function() van:destroy() end);return
	end
	deadline=os.clock()+240
	while not roadDone and os.clock()<deadline and npc.Parent and not van.dead do task.wait(0.5) end
	if not npc.Parent or van.dead then pcall(function() van:destroy() end);return end
	-- v218: same as a player transport - the city road ends at the prison access
	-- road, so drive the last stretch through the sally-port gates to the intake
	-- handoff (the old unload point was outside the gates, where the intake
	-- officer can't walk to).
	local unloadAt: Vector3?=nil
	do
		local intakeGoal=fac.intake or fac.center
		if Util.flat(intakeGoal-body.Position).Magnitude>45 then
			local finalRoute=correctionalVehicleRoute(van.cfg,body.Position,intakeGoal)
			if finalRoute and #finalRoute>=2 then
				local done=false
				van.parked=false
				van.parts.ap.Enabled=true;van.parts.ao.Enabled=true
				for _,part in van.model:GetDescendants() do
					if part:IsA("BasePart") then part.Anchored=false;part.CanCollide=false end
				end
				body.Anchored=false
				pcall(function() body:SetNetworkOwner(nil) end)
				van.parts.ap.Position=body.Position;van.parts.ao.CFrame=body.CFrame.Rotation
				if fac.gates then pcall(physicalGateOpen,fac.gates,25) end
				print("[NPCArrest] final approach to intake handoff "..string.format("%.1f",Util.flat(intakeGoal-body.Position).Magnitude).." studs")
				van:drive(finalRoute,8,nil,function() done=true end)
				local t=os.clock()+45
				while not done and os.clock()<t and npc.Parent and not van.dead and Util.flat(intakeGoal-body.Position).Magnitude>20 do task.wait(0.4) end
			end
			if npc.Parent and Util.flat(intakeGoal-body.Position).Magnitude>60 then
				-- could not drive in: walk-in point next to the intake instead of the gate
				warn("[NPCArrest] cruiser could not reach intake handoff; unloading at intake")
				weld:Destroy()
				unloadAt=intakeGoal
				weld=Instance.new("WeldConstraint")
			end
		end
	end
	-- 3) unloaded at the prison and handed to an intake officer
	local unload=unloadAt or body.CFrame:PointToWorldSpace(Vector3.new(-(body.Size.X/2+3),0,0))
	weld:Destroy()
	for _,d in npc:GetDescendants() do if d:IsA("BasePart") then d.Massless=false;d.CanCollide=(d.Name=="HumanoidRootPart" or d.Name=="Head" or string.find(d.Name,"Torso")~=nil) end end
	npc:PivotTo(CFrame.new(unload+Vector3.new(0,3,0)))
	hum.WalkSpeed=8
	task.delay(8,function() van.transporting=false;pcall(function() van:destroy() end) end)
	local post=prisonPoint("IntakeOfficerPost",Vector3.new(3985.5,0.42,-2138.0))
	openPrisonDoorsNear(post,32,20)
	local cop=nameEscort(escortCop(post,unload-post),"INTAKE OFFICER")
	if not cop then npc:Destroy();return end
	moveEscortOnly(cop,unload,40)
	PL.npcLabel(npc,"INTAKE")
	PL.npcLabel(npc,"INTAKE HOLD")
	PL.npcHoldIn(cop,npc,"IntakeCell",PL.NPC_ARRESTS.IntakeHold,"NPC INTAKE")
	PL.npcLabel(npc,"BOOKING")
	PL.npcHoldIn(cop,npc,"BookingCell",PL.NPC_ARRESTS.BookingHold,"NPC BOOKING")
	-- 4) dress-out: uniform of the class
	local dress=PrisonFlow.findDressOutRoom()
	if dress then PL.npcEscortTo(cop,npc,PrisonFlow.approach(dress),"NPC DRESS OUT") end
	for _,d in npc:GetChildren() do if d:IsA("Shirt") or d:IsA("Pants") or d:IsA("Accessory") then d:Destroy() end end
	local outfit=inmateClothes[class]
	if outfit then
		pcall(PrisonFlow.wearUniform,npc,outfit)
	end
	task.wait(3)
	-- 5) housing: their class's cellblock, then normal inmate life
	local group=PL.inmateGroup(class)
	local rooms=group and PL.classRooms(group.cells) or {}
	if not group or #rooms==0 then warn("[NPCArrest] no housing for "..class);cop:despawn("npc housing unavailable");npc:Destroy();return end
	local room=rooms[math.random(1,#rooms)]
	PL.npcLabel(npc,"HOUSING")
	PL.npcEscortTo(cop,npc,if group.area then (PrisonNav.patrolStart(group.area) or PrisonFlow.approach(room)) else PrisonFlow.approach(room),"NPC HOUSING")
	cop:despawn("npc housed")
	local gui=npc:FindFirstChild("Head") and npc.Head:FindFirstChild("NpcCustodyLabel");if gui then gui:Destroy() end
	npc.Name=class.." Inmate";hum.DisplayName=class.." Inmate"
	print(("[NPCArrest] %s inmate housed via full intake"):format(class))
	PL.npcArrestHoused+=1
	task.spawn(function()
		PL.inmateLife(npc,hum,root,group,room,PL.prisonNpcFolder())
		PL.npcArrestHoused-=1
	end)
end

function PL.startNpcArrests()
	if not PL.NPC_ARRESTS.Enabled then return end
	-- v212: every arrest runs in its own thread (a housed NPC's prison life never
	-- returns, which used to stall this loop after the first arrest). A few can be
	-- on the road at once; one is always under way within 5 minutes.
	PL.arrestsInFlight=0
	task.spawn(function()
		task.wait(30)
		print("[NPCArrest] city arrests online")
		while prison and prison.Parent do
			if PL.arrestsInFlight<PL.NPC_ARRESTS.MaxInFlight then
				PL.arrestsInFlight+=1
				task.spawn(function()
					local ok,err=pcall(PL.npcArrestOnce)
					if not ok then warn("[NPCArrest] "..tostring(err)) end
					PL.arrestsInFlight-=1
				end)
			end
			task.wait(math.random(PL.NPC_ARRESTS.Interval[1],PL.NPC_ARRESTS.Interval[2]))
		end
	end)
end

---------------------------------------------------------------------------
-- v211 CELLBLOCK FREE TIME: during the day schedule, player inmates' cell doors
-- open so they can mix in their cellblock. Low / Medium get every free block,
-- High only gets the Yard block, Maximum / Supermax / Death Row get none. At
-- lockdown they have 60s to get back in; then a CO puts them in and locks up.
---------------------------------------------------------------------------
PL.FREE_TIME = { Low = "all", Medium = "all", High = "yard" }
PL.freeState = {}
PL.returnBy = {}

function PL.currentBlock(): string
	local hour=game:GetService("Lighting").ClockTime
	for _,b in Config.PrisonSchedule.Blocks do
		if hour>=b.Start and hour<b.Finish then return b.Name end
	end
	return "Lockdown"
end

function PL.cellOpenFor(class: string): boolean
	local block=PL.currentBlock()
	if PL.PRISON_LIFE.InCellBlocks[block] then return false end
	local rule=PL.FREE_TIME[class]
	return rule=="all" or (rule=="yard" and block=="Yard")
end

function PL.playerRoom(player: Player): any?
	local cell=housingAssignment[player]
	local pair=cell and PrisonNav.CellPairs[cell.Name]
	local map=PrisonNav.mapRoot
	local doors=map and map:FindFirstChild("DoorMarkers")
	local door=pair and doors and doors:FindFirstChild(pair.door)
	if not door then return nil end
	return {cell=cell,door=door,pos=pair.pos,name=cell.Name,category=pair.category,open=pair.open==true}
end

function PL.startCellFreeTime()
	task.spawn(function()
		while prison and prison.Parent do
			for player in housingAssignment do
				local ok,err=pcall(function()
					if not player.Parent or not sentenceEnd[player] or releaseBusy[player] then PL.freeState[player]=nil;return end
					if player:GetAttribute("CustodyOwner")~="INCARCERATED" then return end
					-- v212: solitary, a visit or an execution owns the inmate's door
					if player:GetAttribute("Solitary") or player:GetAttribute("Visiting") or player:GetAttribute("DeathRowExecutionStarted") then PL.freeState[player]=nil;return end
					-- Death Row (and solitary) cells never open for free time
					if player:GetAttribute("SecurityClass")=="Death Row" then PL.freeState[player]=nil;return end
					local room=PL.playerRoom(player)
					if not room or room.open then return end -- low security cells have no door
					local _,_,root=Util.charInfo(player)
					if not root then return end
					local class=tostring(player:GetAttribute("SecurityClass") or "")
					local state=PL.freeState[player]
					if PL.cellOpenFor(class) then
						openMarkedDoor(room.door,9)
						if state~="open" then
							PL.freeState[player]="open"
							tell(player,"Notice",(if class=="High" then "Yard time" else "Free time").." - your cell is open. Stay in the cellblock.")
						end
					elseif state=="open" then
						if PrisonNav.isInsideCell(room,root.Position) then
							pcall(PrisonFlow.closeCell,room)
							PL.freeState[player]=nil
						else
							PL.freeState[player]="returning"
							PL.returnBy[player]=os.clock()+60
							openMarkedDoor(room.door,9)
							tell(player,"Notice","LOCKDOWN - return to your cell within 60 seconds")
						end
					elseif state=="returning" then
						local inside=PrisonNav.isInsideCell(room,root.Position)
						if inside or os.clock()>(PL.returnBy[player] or 0) then
							if not inside then
								root.CFrame=CFrame.new(room.pos+Vector3.new(0,3,0))
								tell(player,"Notice","A correctional officer put you back in your cell")
							end
							task.wait(0.3)
							pcall(PrisonFlow.closeCell,room)
							PL.freeState[player]=nil
						else
							openMarkedDoor(room.door,9)
						end
					end
				end)
				if not ok then warn("[PrisonLife] free time: "..tostring(err)) end
			end
			task.wait(4)
		end
	end)
end

startPrisonLife = function()
	if not prison or not PrisonNav then return end
	local t0=os.clock()
	while not PrisonNav.ready and os.clock()-t0<60 do task.wait(1) end
	if not PrisonNav.ready then warn("[PrisonLife] prison navigation not ready; prison life disabled");return end
	PL.startStationedGuards()
	-- v212: regimen, NPC cells + sentences, solitary, executions and visits
	local extrasModule=script:FindFirstChild("PrisonExtras")
	if extrasModule then
		local ok,err=pcall(function()
			local X=require(extrasModule)
			X.init({
				PL=PL,PrisonFlow=PrisonFlow,PrisonNav=PrisonNav,Util=Util,Config=Config,tell=tell,
				openMarkedDoor=openMarkedDoor,openPrisonDoorsNear=openPrisonDoorsNear,markerFloorPosition=markerFloorPosition,
				escortCop=escortCop,nameEscort=nameEscort,custody=custody,sentenceEnd=sentenceEnd,
				housingAssignment=housingAssignment,releaseBusy=releaseBusy,
				release=function(p,how) return release(p,how) end,resetExecutedPlayer=resetExecutedPlayer,
				-- v219: an executed player is a brand-new free player: wipe, drop every
				-- custody flag (no "processing" left over), uncuff, respawn outside.
				finishExecution=function(p)
					resetExecutedPlayer(p)
					clearJusticeState(p)
					releaseBusy[p]=nil
					pcall(uncuff,p)
					for _,name in {"DeathRowExecutionStarted","DeathRowGasExposure","DeathRowExecutionComplete","Solitary","PoliceCuffed","Executing"} do p:SetAttribute(name,nil) end
					pcall(tell,p,"Released","executed")
					print("[DeathRow] "..p.Name.." executed - profile reset, released as a new player")
					task.delay(1,function() if p.Parent then pcall(respawn,p) end end)
				end,
				inmateClothes=inmateClothes,Van=Van,RoadGraph=RoadGraph,outsidePrison=outsidePrison,
				custodyTransportGhost=custodyTransportGhost,prisonExit=prisonExit,prison=prison,
			})
			PrisonFlow.execute=X.execute
			PrisonFlow.extras=X -- v241: HQ rides (X.ride), solitary for crimes inside (X.solitaryPlayer)
		end)
		if not ok then warn("[PrisonExtras] failed to start: "..tostring(err));PL.startNpcInmates() end
	else
		PL.startNpcInmates()
	end
	PL.startNpcArrests()
	PL.startCellFreeTime()
	-- PrisonSociety asks for a CO when inmates fight
	local respond=ServerStorage:FindFirstChild("PrisonCOResponse") or Instance.new("BindableFunction")
	respond.Name="PrisonCOResponse"
	respond.OnInvoke=function(pos) return PL.coRespond(pos) end
	respond.Parent=ServerStorage
	local engage=ServerStorage:FindFirstChild("PrisonCOEngage") or Instance.new("BindableFunction")
	engage.Name="PrisonCOEngage"
	engage.OnInvoke=function(player,reason) return PL.coEngage(player,reason) end
	engage.Parent=ServerStorage
end
end -- prison life block

function Justice.init()
	-- v212: PrisonExtras' remotes exist from the start (clients wait on them);
	-- its prison logic starts later with the prison navigation (startPrisonLife)
	local extrasModule=script:FindFirstChild("PrisonExtras")
	if extrasModule then pcall(require,extrasModule) end
	findPrison()
	loadFacilities()
	-- v240: every building mapped with the Facility Mapper (HQ, city jail, courthouse,
	-- law offices, bank, city). Unmapped buildings keep their old behaviour.
	do
		local fm=script:FindFirstChild("Facilities")
		if fm then
			local ok,F=pcall(require,fm)
			if ok then Justice.Facilities=F;State.Facilities=F;task.delay(4,function() pcall(F.report) end)
			else warn("[Facilities] failed to load: "..tostring(F)) end
		end
		-- v242: permanent criminal record + turn yourself in at the HQ front desk
		local rm=script:FindFirstChild("Records")
		if rm then
			local ok,R=pcall(require,rm)
			if ok then Justice.Records=R else warn("[Records] failed to load: "..tostring(R)) end
		end
		-- v254: bail at HQ booking, court dates, failures to appear
		local bm=script:FindFirstChild("Bail")
		if bm then
			local ok,BL=pcall(require,bm)
			if ok then
				Justice.Bail=BL
				pcall(BL.init,{tell=tell,charge=charge,payBank=payBank,Records=Justice.Records})
			else warn("[Bail] failed to load: "..tostring(BL)) end
		end
		-- v288: classification (intake desk, write-ups, reviews, charges inside)
		local clm=script:FindFirstChild("Classification")
		if clm then
			local ok,CLm=pcall(require,clm)
			if ok then
				Justice.Classification=CLm
				pcall(CLm.init,{Records=Justice.Records,court=nil,toDesk=function(p) return PrisonFlow.toDesk(p) end,
					rehouse=function(p,l,w) return PrisonFlow.rehouse(p,l,w) end,prisonCourt=function(p,t,s,c) return PrisonFlow.prisonCourt(p,t,s,c) end,
					housed=function(p) return sentenceEnd[p]~=nil and p:GetAttribute("BookingState")=="Housed" end,
					remaining=function(p) return if sentenceEnd[p] then sentenceEnd[p]-os.time() else nil end,
					tell=function(p,m) tell(p,"Custody",m) end})
			else warn("[Classification] failed to load: "..tostring(CLm)) end
		end
		-- v263: the day in court at the Clark County Courthouse (arraignment, plea, bench / jury trial)
		local cm=script:FindFirstChild("Court")
		if cm then
			local ok,CM=pcall(require,cm)
			if ok then
				Justice.Court=CM
				if Justice.Classification then pcall(function() (Justice.Classification :: any).setCourt(CM) end) end
				pcall(CM.init,{Records=Justice.Records})
				-- court dates for defendants out on bail are heard at the courthouse now
				if Justice.Bail and Justice.Bail.setCourt then
					pcall(Justice.Bail.setCourt, CM, function(p: Player, sec: number, txt: string, idx: number?) return PrisonFlow.remand(p, sec, txt, idx) end,
						-- v291: a defendant on bail sentenced at trial is cuffed and walked out by a court officer
						{ cuff = function(p: Player) cuff(p) end,
							walk = function(p: Player, goal: Vector3, t: number?): string
								local _, _, rw = Util.charInfo(p)
								local c = rw and nameEscort(escortCop(rw.Position + Vector3.new(3, 0, 3), goal - rw.Position), "COURT OFFICER")
								local how = PrisonFlow.hqWalk(p, goal, c, t or 60, function() return p.Parent ~= nil end)
								if c then c:despawn("done") end
								return how
							end })
				end
			else warn("[Court] failed to load: "..tostring(CM)) end
		end
		task.delay(5,function() pcall(PrisonFlow.setupTurnIn) end)
		-- v246-v249: crime log, interrogation, QTEs, snitching
		local im=script:FindFirstChild("Interrogation")
		if im then
			local ok,IM=pcall(require,im)
			if ok then
				Justice.Interrogation=IM;State.onCrime=IM.onCrime
				IM.init({F=Justice.Facilities,Heat=Heat,
					inCustody=function(p) return custody[p]==true or PrisonFlow.hq[p]~=nil or sentenceEnd[p]~=nil end})
			else warn("[Interrogation] failed to load: "..tostring(IM)) end
		end
		-- v245: guard tower snipers + spotlights (towers from the prison map)
		local gt=script:FindFirstChild("GuardTowers")
		if gt then
			task.delay(6,function()
				local ok,GT=pcall(require,gt)
				if not ok or not Justice.Facilities then warn("[GuardTowers] failed to load: "..tostring(GT));return end
				local okInit,err=pcall(GT.init,{
					F=Justice.Facilities,Util=Util,
					outside=function(pos) return prison~=nil and outsidePrison(pos,nil) end,
					isInmate=function(p) return sentenceEnd[p]~=nil end,
					isStaff=function(p) return isStaff(p) and not inPrison(p) end, -- v245c: staff may stand in the zones
					-- v245e: towers make you wanted, keep dispatch updated and use the police rubber-round ragdoll
					crime=function(p,name,pos) return Heat.addCrime(p,name,pos) end,
					spotted=function(p,pos) Heat.spotted(p,pos,"VISUAL") end,
					rubberStun=function(p,secs) return Heat.rubberStun(p,secs,false) end,
					surrendered=function(p) local h=Heat.get(p);local hum=p.Character and p.Character:FindFirstChildOfClass("Humanoid")
						return (h~=nil and h.surrendered==true) or (hum~=nil and hum:GetAttribute("PoliceCuffed")==true) end,
					tell=tell,
					notifyAll=function(text) for _,pl in Players:GetPlayers() do tell(pl,"Notice",text) end end,
					alarm=function(p,pos)
						radio(("PRISON ALARM - %s at the perimeter, towers engaging"):format(p.Name),pos,3)
						-- v290: an inmate in the perimeter / stun zone (not a confirmed escapee - the street
						-- response handles those): the COs come out for him, and it's written up
						if sentenceEnd[p] and not p:GetAttribute("EscapeInProgress") then
							if PrisonFlow.coEngage then task.spawn(PrisonFlow.coEngage,p,"attempted escape") end
							local ev=ServerStorage:FindFirstChild("PrisonWriteUp")
							if ev and ev:IsA("BindableEvent") then ev:Fire(p,"attempted escape",{PrisonEscape=true}) end
						end
					end,
					-- spec 1.8: shot dead by a tower while escaping = prison death (profile wipe)
					sniperKill=function(p)
						if sentenceEnd[p] then return end -- the Died handler already wipes inmates killed in prison
						warn(("[PrisonDeath] %s was shot dead by a tower sniper while escaping - profile reset"):format(p.Name))
						resetExecutedPlayer(p);clearJusticeState(p);releaseBusy[p]=nil;pcall(uncuff,p)
						for _,name in {"EscapeInProgress","EscapeDetected","EscapeRemainingSentence","PrisonKilledBy","TowerSniperKill"} do p:SetAttribute(name,nil) end
						if Heat.get(p) then Heat.clear(p,"Busted") end
						pcall(tell,p,"Released","killed")
					end,
				})
				if not okInit then warn("[GuardTowers] init failed: "..tostring(err)) end
			end)
		end
	end
	buildLandmarks()
	loadTeamGuns()
	setupDoors()
	-- v116: prison navigation graph, built from CorrectionalFacility.PrisonMap
	do
		local navModule = script:FindFirstChild("PrisonNavigation")
		if navModule and navModule:IsA("ModuleScript") and prison then
			local okNav, errNav = pcall(function()
				PrisonNav = require(navModule)
				PrisonNav.init({
					Util = Util,
					mapRoot = prisonMapRoot,
					facility = prison,
					openDoor = function(target: Instance, secs: number)
						-- Authorized staff must release the custody lock before opening.
						-- The generic opener intentionally refuses locked cell doors.
						local markers=prisonDoorMarkerFolder()
						if markers then
							for _,marker in markers:GetChildren() do
								if markerDoorTarget(marker)==target then openMarkedDoor(marker,secs);return end
							end
						end
						if openFor then pcall(openFor,target,secs) end
					end,
					openNear = function(pos: Vector3, radius: number, secs: number)
						openPrisonDoorsNear(pos, radius, secs)
					end,
					ignore = { State.folders and State.folders.Root or nil },
				})
				PrisonNav.addDestination("MEDICAL", prisonMedicalPoint())
				do
					local selected=prisonMapRoot()
					local zones=selected and selected:FindFirstChild("Zones")
					local doors=selected and selected:FindFirstChild("DoorMarkers")
					local routes=selected and selected:FindFirstChild("Routes")
					print(("[PrisonNav] MAP ROOT SELECTED: %s zones=%d doors=%d routes=%d"):format(
						selected and selected:GetFullName() or "nil",
						zones and #zones:GetChildren() or 0, doors and #doors:GetChildren() or 0, routes and #routes:GetChildren() or 0))
				end
                task.spawn(function()
                    for attempt=1,12 do
                        if PrisonNav.build() then PrisonFlow.capacity();return end
                        warn("[CustodyDiag] NAV NOT READY - retry "..attempt);task.wait(5)
                    end
                    warn("[CustodyDiag] NAV UNAVAILABLE - prisoners remain secured; inspect mapped polygons and door links")
                end)
			end)
			if not okNav then
				PrisonNav = nil
				warn("[PrisonNav] navigation unavailable - legacy prison movement: " .. tostring(errNav))
			end
		end
	end
	task.defer(startPrisonGuardPrototype)
	task.defer(startPrisonLife)

	-- who can be made wanted
	Heat.canBeWanted = function(player: Player, crimeName: string): boolean
		if custody[player] then
			return false
		end
		if inPrison(player) then
			return crimeName == "PrisonEscape" or PrisonFlow.engaging == player -- v288l: a CO response (PL.coEngage)
		end
		if Util.isLaw(player) then
			return crimeName == "Murder" or crimeName == "CopKilled" -- killing an innocent still counts
		end
		return true
	end
	Heat.bustHook = function(player: Player, pursuit: any)
		Justice.jail(player, nil, pursuit and pursuit.preferredTransport or nil)
	end
	State.criticalHook = function(player: Player, reason: string)
		Justice.medicalCustody(player,reason)
	end

	Heat.onCrime(function(player, crimeName, chargeName)
		if crimeName=="CopKilled" then
			policeOfficerKills[player]=(policeOfficerKills[player] or 0)+1
			local count=policeOfficerKills[player]
			player:SetAttribute("PoliceOfficersKilled",count)
			print(("[CustodyDiag] POLICE KILL COUNT %s %d/5"):format(player.Name,count))
			if count>=5 and player:GetAttribute("DeathRowTestOverride")~=true then
				player:SetAttribute("DeathRowTestOverride",true)
				warn(("[CustodyDiag] DEATH ROW TEST OVERRIDE ARMED %s after %d officer kills; one-minute sentence at booking"):format(player.Name,count))
			end
		end
		charges[player] = charges[player] or {}
		table.insert(charges[player], chargeName)
		crimeKeys[player] = crimeKeys[player] or {}
		crimeKeys[player][crimeName] = true
		recentCrime[player] = recentCrime[player] or {}
		recentCrime[player][crimeName] = os.clock()
	end)
	Heat.onChanged(function(player, p, oldStars, reason)
		mirror(player, p.stars)
		local now = os.clock()
		if now - (lastRadio[player] or 0) > 6 or p.stars >= oldStars + 1 then
			lastRadio[player] = now
			local what = if reason and Config.Crimes[reason] and Config.Crimes[reason].Charge then Config.Crimes[reason].Charge else (reason or "Wanted suspect")
			radio(string.format("%d★ %s - %s %s", p.stars, player.Name, what, Justice.placeName(p.lastSeenPos or Vector3.zero)), p.lastSeenPos, p.stars)
		end
	end)
	Heat.onCleared(function(player, _p, reason)
		mirror(player, 0)
		if reason == "Evaded" or reason == "Died" or reason == "Left" or reason == "Cleared" then
			charges[player] = nil
			crimeKeys[player] = nil
			policeOfficerKills[player]=nil
			player:SetAttribute("PoliceOfficersKilled",nil);player:SetAttribute("DeathRowTestOverride",nil)
		end
		if reason == "Evaded" then
			radio(string.format("Lost contact with %s", player.Name), nil, 0)
		end
	end)

	-- ServerStorage.ReportCrime for the bank / housing / civilian scripts
	local old = ServerStorage:FindFirstChild("ReportCrime")
	if old then
		old:Destroy()
	end
	local fn = Instance.new("BindableFunction")
	fn.Name = "ReportCrime"
	fn.OnInvoke = external
	fn.Parent = ServerStorage

	local r = remote()
	if r then
		r.OnServerEvent:Connect(onRequest)
	end

	-- v136: resetting a character must never become a prison escape.  The sentence and
	-- assigned housing cell belong to the Player, so a replacement character is restored
	-- to that same cell instead of being allowed to use the normal team spawn.
	local function restorePrisonRespawn(player: Player, char: Model): boolean
		if not sentenceEnd[player] or os.time() >= sentenceEnd[player] then return false end
		if player:GetAttribute("BookingState") ~= "Housed" and player:GetAttribute("CustodyPhase") ~= "SentencedPrisoner" then return false end
		local hum=char:FindFirstChildOfClass("Humanoid") or char:WaitForChild("Humanoid",5)
		local root=char:FindFirstChild("HumanoidRootPart") or char:WaitForChild("HumanoidRootPart",5)
		if not hum or not root or player.Character~=char then return false end
		local cell=housingAssignment[player]
		local assigned=tostring(player:GetAttribute("AssignedCell") or "")
		if (not cell or not cell.Parent) and assigned~="" then
			local fac=inmateFacility[player]
			local prison=fac and fac.model or nil
			if prison then
				for _,obj in prison:GetDescendants() do
					if obj.Name==assigned and (obj:IsA("Model") or obj:IsA("BasePart")) then cell=obj break end
				end
			end
		end
		if not cell then
			warn("[CustodyDiag] RESPAWN CELL MISSING "..player.Name.." assigned="..assigned)
			return false
		end
		housingAssignment[player]=cell
		local pos=mappedCellZoneCenter(cell) or cellStand(cell)
		if not pos then
			warn("[CustodyDiag] RESPAWN CELL POSITION MISSING "..player.Name.." cell="..cell.Name)
			return false
		end
		root.Anchored=false; hum.PlatformStand=false; hum.Sit=false; hum.AutoRotate=true
		root.CFrame=CFrame.new(pos+Vector3.new(0,3,0),pos+Vector3.new(0,3,1))
		hum.WalkSpeed=8; hum.JumpPower=50; hum.JumpHeight=7.2
		pcall(function() root:SetNetworkOwnershipAuto() end)
		PrisonFlow.state(player,"INCARCERATED",false)
		player:SetAttribute("CustodyRespawnGraceUntil",nil)
		print("[CustodyDiag] PRISON RESPAWN RESTORED "..player.Name.." -> "..cell.Name)
		sendJailState(player)
		return true
	end

	-- A busted player's Reset Character action does not return them to a public
	-- spawn. It recovers into a reserved intake cell, locks that mapped door, waits
	-- through the normal intake hold, and resumes the same booking case.
	-- v225: hidden spawn point on an intake cell floor used as a detainee's
	-- RespawnLocation, so a death in custody never respawns across the map
	function PrisonFlow.intakeSpawn(): SpawnLocation?
		local existing=Workspace:FindFirstChild("IntakeRespawn")
		if existing and existing:IsA("SpawnLocation") then return existing end
		if not PrisonNav or not PrisonNav.CellPairs then return nil end
		local pos=nil
		for _,pair in PrisonNav.CellPairs do
			if pair.category=="IntakeCell" and pair.pos then pos=pair.pos;break end
		end
		if not pos then return nil end
		local team=teamNamed("Intake Prisoners")
		local sp=Instance.new("SpawnLocation")
		sp.Name="IntakeRespawn"
		sp.Size=Vector3.new(3,0.2,3)
		sp.CFrame=CFrame.new(pos+Vector3.new(0,0.1,0))
		sp.Anchored=true;sp.CanCollide=false;sp.CanTouch=false;sp.CanQuery=false
		sp.Transparency=1;sp.Duration=0;sp.AllowTeamChangeOnTouch=false
		sp.Neutral=false;sp.Enabled=true
		if team then sp.TeamColor=team.TeamColor end
		local decal=sp:FindFirstChildOfClass("Decal");if decal then decal:Destroy() end
		sp.Parent=Workspace
		print("[CustodyDiag] INTAKE RESPAWN point created at "..tostring(pos))
		return sp
	end
	-- v222: still an arrested detainee going through intake / booking?
	function PrisonFlow.isDetainee(player: Player): boolean
		local team=player.Team and player.Team.Name
		if team=="Intake Prisoners" or team=="Booking Inmates" or team=="Police Custody" then return true end
		local bs=tostring(player:GetAttribute("BookingState") or "")
		if bs=="IntakeCell" or bs=="Intake" or bs=="IntakeOfficerDispatch" or bs=="IntakeTransfer" or bs=="Arrested" or bs=="Transport"
			or bs=="Booking" or bs=="Review" or bs=="AwaitingHousing" then return true end
		local owner=tostring(player:GetAttribute("CustodyOwner") or "")
		return owner=="INTAKE_CELL" or owner=="INTAKE_ESCORT" or owner=="BOOKING" or owner=="BOOKING_ESCORT" or owner=="CORRECTIONAL_HOLD"
	end
	---------------------------------------------------------------------------
	-- v239 CUSTODY STAGES. One answer to "where is this player in the custody
	-- pipeline?", derived from the older BookingState / CustodyOwner / sentence
	-- flags, and published as the CustodyStage attribute. Each stage owns where a
	-- new character appears (placed before anything yields, so the player's own
	-- client never takes the body over somewhere else).
	--   Arrest -> Transport -> Station -> Detention -> (Court) -> Serving -> Release
	--   Medical: critical custody (EMS)
	---------------------------------------------------------------------------
	PrisonFlow.STAGE_OF_BOOKING={
		Arrested="Arrest",TransportSceneHold="Arrest",
		Transport="Transport",SharedTransport="Transport",SharedTransportHold="Transport",TransportBlocked="Transport",
		Intake="Station",IntakeCell="Station",IntakeOfficerDispatch="Station",IntakeTransfer="Station",
		Booking="Detention",Review="Detention",AwaitingHousing="Detention",
		MedicalEMS="Medical",MedicalRecovery="Medical",MedicalOfficerDispatch="Medical",MedicalTransport="Medical",
		Housed="Serving",DeathRowExecution="Serving",
		Release="Release",Executed="Free",
		HQTransport="Transport",HQHolding="Station",HQBooking="Station",HQRelease="Release", -- v241/v242 Police HQ custody
		JailTransport="Transport",JailCell="Detention",JailDayRoom="Detention",JailRelease="Release", -- v243 City Jail
		TransferHolding="Detention",TransferDeparture="Transport", -- v244 prison transfer
		Interrogation="Station", -- v246
		Court="Court",LawyerVisit="Station", -- v263 the day in court / counsel at the station
	}
	-- where the NEW character appears for each stage
	PrisonFlow.RESPAWN_AT={
		Arrest="Intake",Transport="Intake",Station="Intake",Detention="Intake",Court="Intake",Medical="Intake",
		Serving="Cell",Release="None",Free="None",
	}
	function PrisonFlow.stageOf(player: Player): string
		if releaseBusy[player] then return "Release" end
		local bs=tostring(player:GetAttribute("BookingState") or "")
		if bs=="Executed" then return "Free" end
		if sentenceEnd[player] then return "Serving" end
		if criticalCustody[player] then return "Medical" end
		local stage=PrisonFlow.STAGE_OF_BOOKING[bs]
		if stage then return stage end
		if custody[player] or PrisonFlow.isDetainee(player) then return "Arrest" end
		return "Free"
	end
	function PrisonFlow.syncStage(player: Player, why: string?): string
		local stage=PrisonFlow.stageOf(player)
		local old=player:GetAttribute("CustodyStage")
		local new=if stage=="Free" then nil else stage
		if old~=new then
			player:SetAttribute("CustodyStage",new)
			print(("[Custody] STAGE %s %s -> %s (%s)"):format(player.Name,tostring(old or "Free"),stage,tostring(why or "sync")))
		end
		return stage
	end
	-- the spot a new character is placed at for its stage (nil = leave it alone)
	function PrisonFlow.respawnAnchor(player: Player, stage: string): CFrame?
		-- v241: Police HQ detainees respawn in the HQ holding cell, never at prison intake
		local hqRec=PrisonFlow.hq[player]
		if hqRec then return CFrame.new(hqRec.hold) end
		local where=PrisonFlow.RESPAWN_AT[stage]
		if where=="Intake" then
			local sp=PrisonFlow.intakeSpawn()
			return if sp then CFrame.new(sp.Position+Vector3.new(0,3.4,0)) else nil
		elseif where=="Cell" then
			-- the same spot restorePrisonRespawn uses, so the two never disagree
			local cell=housingAssignment[player]
			if cell and cell.Parent then
				local pos=mappedCellZoneCenter(cell) or cellStand(cell)
				if pos then return CFrame.new(pos+Vector3.new(0,3,0),pos+Vector3.new(0,3,1)) end
			end
		end
		return nil
	end
	-- some custody changes only touch internal tables (release, EMS, sentence):
	-- a light sweep keeps every player's CustodyStage honest
	task.spawn(function()
		while true do
			task.wait(2)
			for _,p in Players:GetPlayers() do
				pcall(PrisonFlow.syncStage,p,"tick")
			end
		end
	end)

	local function recoverCustodyRespawn(player: Player)
		if not custody[player] or criticalCustody[player] or not player.Parent then return end
		if custodyRecovery[player] then return end
		local token={}
		custodyRecovery[player]=token
		bookingGeneration[player]=(bookingGeneration[player] or 0)+1
		bookingBusy[player]=nil
		PrisonFlow.team(player,"Intake Prisoners")
		player:SetAttribute("CustodyResetRecoveryPending",true)
		task.spawn(function()
			while player.Parent and custody[player] and not criticalCustody[player] and custodyRecovery[player]==token do
				local char=player.Character
				if not char then task.wait(0.15);continue end
				local hum=char:FindFirstChildOfClass("Humanoid") or char:WaitForChild("Humanoid",5)
				local root=char:FindFirstChild("HumanoidRootPart") or char:WaitForChild("HumanoidRootPart",5)
				if not hum or not root or player.Character~=char then task.wait(0.1);continue end
				token.character=char
				local previous=PrisonFlow.pending[player]
				if previous then previous:despawn("custody character reset");PrisonFlow.pending[player]=nil end
				PrisonFlow.rooms[player]=nil;PrisonFlow.reserved[player]=nil
				PrisonFlow.claimCharacters[player]=nil;PrisonFlow.waiters[player]=nil
				local function alive()
					return player.Parent~=nil and custody[player]==true and not criticalCustody[player]
						and player.Character==char and hum.Health>0 and custodyRecovery[player]==token
				end
				-- v212: a death/reset in custody always lands in a cell: intake, then
				-- the holding cells, then any intake cell regardless of capacity
				local room=nil
				local waitUntil=os.clock()+10
				while alive() and not room and os.clock()<waitUntil do
					for _,category in {"IntakeCell","OverflowHolding","LongTermHolding"} do
						room=PrisonFlow.pick(player,category)
						if room then break end
					end
					if not room then task.wait(0.5) end
				end
				if not room and alive() and PrisonNav and PrisonNav.mapRoot then
					local zones=PrisonNav.mapRoot:FindFirstChild("Zones");local doors=PrisonNav.mapRoot:FindFirstChild("DoorMarkers")
					for name,pair in PrisonNav.CellPairs do
						if pair.category=="IntakeCell" and zones and doors then
							local cell,door=zones:FindFirstChild(name),doors:FindFirstChild(pair.door)
							if cell and door then
								room={cell=cell,door=door,pos=pair.pos,name=name,category="IntakeCell",open=false,capacity=pair.capacity or 1}
								warn("[CustodyDiag] RESET RECOVERY forced into "..name.." for "..player.Name)
								break
							end
						end
					end
				end
				if not room then
					if player.Character~=char then continue end
					warn("[CustodyDiag] RESET RECOVERY waiting for a mapped intake cell "..player.Name)
					task.wait(1);continue
				end
				if not alive() then continue end
				local doorFloor=markerFloorPosition(room.door) or room.pos
				root.Anchored=true;root.AssemblyLinearVelocity=Vector3.zero;root.AssemblyAngularVelocity=Vector3.zero
				hum.PlatformStand=false;hum.Sit=false;hum.AutoRotate=true
				root.CFrame=CFrame.lookAt(room.pos+Vector3.new(0,3.25,0),doorFloor+Vector3.new(0,3,0))
				-- v230: the player's own client also pulls its character to this spot
				-- (CustodyPinClient) - the server alone couldn't win against a client
				-- that kept the fresh character at its spawn point in the city
				player:SetAttribute("CustodyPinCF",root.CFrame)
				RunService.Heartbeat:Wait();RunService.Heartbeat:Wait()
				if not alive() then root.Anchored=false;player:SetAttribute("CustodyPinCF",nil);continue end
				-- v223: the fresh character can still be pulled back to its spawn point in
				-- the first moments after spawning: keep re-placing it until it stays put
				local placedCF=root.CFrame
				for _=1,16 do
					task.wait(0.25)
					if not alive() then break end
					if Util.flat(root.Position-room.pos).Magnitude>6 then
						warn("[CustodyDiag] RESET RECOVERY re-placing "..player.Name.." (character left the cell after spawn)")
						root.Anchored=true;root.CFrame=placedCF
					end
				end
				if not alive() then root.Anchored=false;continue end
				PrisonFlow.rooms[player]=room;PrisonFlow.reserved[player]=nil
				player:SetAttribute("ReservedPrisonCell",nil)
				player:SetAttribute("AssignedCell",room.name)
				player:SetAttribute("BookingState","IntakeCell")
				player:SetAttribute("CustodyPhase","INTAKE_CELL")
				PrisonFlow.state(player,"INTAKE_CELL",false)
				uncuff(player)
				local closed,closeWhy=PrisonFlow.closeCell(room)
				if not closed then warn("[CustodyDiag] RESET INTAKE DOOR CLOSE FAILED "..room.name..": "..tostring(closeWhy)) end
				print(("[CustodyDiag] RESET RECOVERY INTAKE CELL %s -> %s doorLocked=%s"):format(player.Name,room.name,tostring(closed)))
				tell(player,"Custody","Reset recovered inside intake. Booking will continue after the intake hold.")
				-- v225: the player's own client can still hold the new character at its
				-- spawn point once it is unanchored and push that position back to the
				-- server. For the whole intake hold, anyone found outside the cell is put
				-- straight back in (no second recovery, which used to cancel the hold).
				-- v234: the guard (and the client pin) stop the moment the intake hold is
				-- over - still running while the booking officer walked the player out,
				-- it yanked them back / fought the escort and threw them out of the jail
				local hold={over=false}
				task.spawn(function()
					local cellCF=CFrame.lookAt(room.pos+Vector3.new(0,3.25,0),doorFloor+Vector3.new(0,3,0))
					local pinned=false
					while not hold.over and alive() and PrisonFlow.rooms[player]==room and player:GetAttribute("BookingState")=="IntakeCell" do
						if Util.flat(root.Position-room.pos).Magnitude>8 or math.abs(root.Position.Y-room.pos.Y)>8 then
							root.AssemblyLinearVelocity=Vector3.zero
							root.CFrame=cellCF
							-- v228: the client kept winning (it owns the character's physics and
							-- held it at its spawn point, so every put-back was undone half a
							-- second later). Pin it server-side in the cell for the rest of the
							-- intake hold - an anchored root can't be moved by the client.
							if not pinned then
								pinned=true
								root.Anchored=true
								warn("[CustodyDiag] INTAKE HOLD GUARD: "..player.Name.." left the cell - pinned in "..room.name.." for the intake hold")
							end
						elseif pinned and not root.Anchored then
							root.Anchored=true
						end
						task.wait(0.5)
					end
					if pinned and root.Parent and player.Character==char then root.Anchored=false end
					player:SetAttribute("CustodyPinCF",nil)
				end)
				local held=PrisonFlow.intakeHold(player,alive)
				hold.over=true
				player:SetAttribute("CustodyPinCF",nil)
				if root.Parent and player.Character==char then root.Anchored=false end
				if held and alive() then
					local case=bookingCase[player]
					if not case then
						local stars=math.max(1,tonumber(player:GetAttribute("CustodyStars")) or 1)
						local fac=pickFacility(stars,{}) or facilities[#facilities]
						local secs=math.floor(sentenceFor(stars,{})*(if fac then fac.cfg.SentenceScale or 1 else 1))
						case={fac=fac,secs=secs,text=tostring(player:GetAttribute("CaseCharges") or "Obstruction of justice"),stars=stars}
						bookingCase[player]=case
						warn("[CustodyDiag] RESET RECOVERY rebuilt the booking case for "..player.Name)
					end
					if case then
						player:SetAttribute("CustodyResetRecoveryPending",nil)
						custodyRecovery[player]=nil
						task.spawn(book,player,case.fac,case.secs,case.text)
						return
					end
					warn("[CustodyDiag] RESET RECOVERY has no saved case for "..player.Name)
				end
			end
			-- v223: only clear our own claim, never a newer recovery's (two recoveries
			-- used to cancel each other and the intake hold / booking never ran)
			if custodyRecovery[player]==token then custodyRecovery[player]=nil end
		end)
	end

	-- v200 PRISON PERSISTENCE. A housed inmate's sentence (time left, class,
	-- charges, facility, pre-arrest team) is saved; rejoining puts them back in
	-- a cell of their class, in uniform, with the timer continuing.
	do
		local DataStoreService=game:GetService("DataStoreService")
		local okStore,store=pcall(DataStoreService.GetDataStore,DataStoreService,"LasVegas_PrisonData_v1")
		if not okStore then store=nil;warn("[PrisonSave] DataStore unavailable (publish the place / enable API access): "..tostring(store)) end
		local restoring=setmetatable({}, {__mode="k"})
		local hasRecord=setmetatable({}, {__mode="k"})
		local function key(player: Player): string return "prison_"..player.UserId end
		local function snapshot(player: Player): any
			local done=sentenceEnd[player]
			-- v288k: an escapee still owes the time; leaving changes nothing
			if not done and player:GetAttribute("EscapeInProgress")==true then
				local owed=tonumber(player:GetAttribute("EscapeRemainingSentence")) or 0
				if owed>0 then return {escaped=true,remaining=owed,class=player:GetAttribute("SecurityClass") or "Maximum",savedAt=os.time()} end
			end
			-- v288k: walked out of custody before a cell (arrest, ride, station, court, booking): the case
			-- is decided in absentia - they come back to a cell serving it
			if not done then
				local bc=bookingCase[player]
				local hq=PrisonFlow.hq and PrisonFlow.hq[player]
				local secs=(bc and tonumber(bc.secs)) or (hq and tonumber(hq.secs))
				if (custody[player] or hq) and secs and secs>0 then
					local stars=(bc and bc.stars) or tonumber(player:GetAttribute("CustodyStars")) or 3
					local class=if player:GetAttribute("DeathSentence")==true then "Death Row" elseif secs>1e7 then "Supermax" else securityFor(stars,secs)
					return {remaining=secs,class=class,charges=(bc and bc.text) or (hq and hq.text) or player:GetAttribute("CaseCharges"),
						facility="State Prison",absentia=true,savedAt=os.time()}
				end
				return nil
			end
			if not done or player:GetAttribute("BookingState")~="Housed" then return nil end
			local remaining=done-os.time()
			if remaining<=0 then return nil end
			local prev=previousTeam[player]
			return {remaining=remaining,class=player:GetAttribute("SecurityClass"),charges=player:GetAttribute("Charges"),
				facility=player:GetAttribute("Facility"),prevTeam=prev and prev.Name or nil,savedAt=os.time()}
		end
		PrisonSave={}
		PrisonFlow.save=PrisonSave
		function PrisonSave.save(player: Player)
			if not store or restoring[player] then return end
			local data=snapshot(player)
			if data then
				local ok,err=pcall(function() store:SetAsync(key(player),data) end)
				if ok then hasRecord[player]=true else warn("[PrisonSave] save failed "..player.Name..": "..tostring(err)) end
			elseif hasRecord[player] then
				PrisonSave.clear(player)
			end
		end
		function PrisonSave.clear(player: Player)
			hasRecord[player]=nil
			if store then pcall(function() store:RemoveAsync(key(player)) end) end
		end
		function PrisonSave.restore(player: Player)
			if not store then return end
			restoring[player]=true
			local ok,data=pcall(function() return store:GetAsync(key(player)) end)
			if not ok or type(data)~="table" or (tonumber(data.remaining) or 0)<=0 then restoring[player]=nil;return end
			hasRecord[player]=true
			-- v288k: an escapee who left comes back still on the run, still owing the time
			if data.escaped then
				player:SetAttribute("EscapeRemainingSentence",math.floor(tonumber(data.remaining) or 60))
				player:SetAttribute("EscapeInProgress",true)
				player:SetAttribute("SecurityClass",data.class)
				local ch=player.Character or player.CharacterAdded:Wait()
				task.wait(8) -- after the start menu
				local _,_,rr=Util.charInfo(player)
				if player.Parent then Heat.addCrime(player,"PrisonEscape",if rr then rr.Position else nil) end
				tell(player,"Custody","You're still an escaped convict - every cop in the city is looking for you")
				print(("[PrisonSave] RESTORED ESCAPEE %s, %ds owed"):format(player.Name,math.floor(tonumber(data.remaining) or 0)))
				local _=ch
				restoring[player]=nil
				return
			end
			if data.absentia then tell(player,"Custody","You left in custody - the case went ahead without you. Serving it now.") end
			local class=tostring(data.class or "Medium")
			local category=PrisonFlow.categoryFor(class)
			local char=player.Character or player.CharacterAdded:Wait()
			task.wait(2)
			local room=PrisonFlow.pick(player,category)
			local waitUntil=os.clock()+60
			while player.Parent and not room and os.clock()<waitUntil do task.wait(5);room=PrisonFlow.pick(player,category) end
			if not player.Parent or not room then
				warn("[PrisonSave] no free "..category.." cell to restore "..player.Name.."; record kept for next join")
				restoring[player]=nil;return
			end
			if type(data.prevTeam)=="string" then
				local t=game:GetService("Teams"):FindFirstChild(data.prevTeam)
				if t and not inmateTeamColors[t.Name] then previousTeam[player]=t end
			end
			-- v288m: into the cell FIRST (the record used to be restored wherever the player stood - out
			-- in the city - and the escape check fired at once)
			player:SetAttribute("CustodyRespawnGraceUntil",Workspace:GetServerTimeNow()+12)
			do
				local _,_,rr=Util.charInfo(player)
				if rr and room.pos then
					rr.AssemblyLinearVelocity=Vector3.zero
					rr.CFrame=CFrame.new(room.pos+Vector3.new(0,3.25,0))
					player:SetAttribute("CustodyPinCF",rr.CFrame)
					task.delay(4,function() player:SetAttribute("CustodyPinCF",nil) end)
				end
			end
			sentenceEnd[player]=os.time()+math.floor(tonumber(data.remaining) or 60)
			for _,fac in facilities do if fac.name==data.facility then inmateFacility[player]=fac end end
			player:SetAttribute("SecurityClass",class);player:SetAttribute("SentenceSeconds",tonumber(data.remaining))
			player:SetAttribute("SentenceEnd",sentenceEnd[player]);player:SetAttribute("Charges",data.charges)
			player:SetAttribute("Facility",data.facility);player:SetAttribute("AssignedCell",room.name)
			player:SetAttribute("BookingState","Housed");player:SetAttribute("CustodyPhase","SentencedPrisoner")
			player:SetAttribute("PrisonDressOutComplete",true)
			housingAssignment[player]=room.cell
			PrisonFlow.rooms[player]=room;PrisonFlow.reserved[player]=nil;player:SetAttribute("ReservedPrisonCell",nil)
			PrisonFlow.team(player,class..(if class=="Supermax" or class=="Death Row" then " Inmates" else " Security Inmates"))
			pcall(PrisonFlow.applyInmateClothes,player,class)
			if player.Character then pcall(restorePrisonRespawn,player,player.Character) end
			if room.door and not room.open then pcall(PrisonFlow.closeCell,room) end
			PrisonFlow.state(player,"INCARCERATED",false)
			sendJailState(player)
			tell(player,"Housed",room.name,class)
			print(("[PrisonSave] RESTORED %s -> %s [%s] %ds left"):format(player.Name,room.name,class,(sentenceEnd[player] or os.time())-os.time()))
			-- v288k: prison stars come back with you (the record keeps them)
			if Justice.Records then
				local okR,rec=pcall(Justice.Records.get,player)
				local st=okR and type(rec)=="table" and rec.prison and tonumber(rec.prison.stars)
				if st and st>0 then player:SetAttribute("PrisonStars",st) end
			end
			restoring[player]=nil
			-- the start menu assigns a team on join; re-assert once it has run
			task.delay(6,function()
				if player.Parent and sentenceEnd[player] then
					PrisonFlow.team(player,class..(if class=="Supermax" or class=="Death Row" then " Inmates" else " Security Inmates"))
				end
			end)
		end
		task.spawn(function()
			while true do
				task.wait(60)
				for _,player in Players:GetPlayers() do
					if sentenceEnd[player] or hasRecord[player] then task.spawn(PrisonSave.save,player) end
				end
			end
		end)
		game:BindToClose(function()
			for _,player in Players:GetPlayers() do PrisonSave.save(player) end
		end)
	end

	local function onPlayer(player: Player)
		task.spawn(PrisonSave.restore,player)
		-- v206: an inmate team is only valid while in custody or serving; a
		-- finished/executed inmate who lands on one (e.g. Low Security Inmates)
		-- is moved to the release team.
		player:GetPropertyChangedSignal("Team"):Connect(function()
			task.delay(5,function()
				local team=player.Team
				if player.Parent and team and (inmateTeamColors[team.Name] or team.Name==JCFG.PrisonerTeam)
					and not sentenceEnd[player] and not custody[player] and not releaseBusy[player] and not bookingBusy[player]
					and not player:GetAttribute("CustodyOwner") and not player:GetAttribute("EscapeInProgress")
				and not PrisonFlow.hq[player] then -- v245f: HQ / City Jail custody is custody too
					local t=releaseTargetTeam(player)
					if t and t~=team then
						warn(("[CustodyDiag] TEAM FIX %s was on %s with no sentence -> %s"):format(player.Name,team.Name,t.Name))
						player.Team=t
					end
				end
			end)
		end)
		-- nobody should start the game in prison without a sentence
		if player.Team and player.Team.Name == JCFG.PrisonerTeam and not inPrison(player) then
			local t = teamNamed(JCFG.ReleaseTeam)
			if t then
				player.Team = t
			end
		end
		-- v239: keep CustodyStage current whenever the older custody flags change
		player.AttributeChanged:Connect(function(name)
			if name=="BookingState" or name=="CustodyOwner" or name=="CustodyPhase" or name=="SentenceEnd" or name=="PoliceCritical" then
				PrisonFlow.syncStage(player,name)
			end
		end)
		-- v290: where the old character was when it went (a reset in custody puts the new one back there)
		PrisonFlow.lastRootCF = PrisonFlow.lastRootCF or setmetatable({}, {__mode="k"})
		player.CharacterRemoving:Connect(function(oldChar)
			local r=oldChar:FindFirstChild("HumanoidRootPart")
			if r and r:IsA("BasePart") and r.Position.Y > Workspace.FallenPartsDestroyHeight + 50 then PrisonFlow.lastRootCF[player]=r.CFrame end
		end)
		player.CharacterAdded:Connect(function(char)
			-- v239 (was v234, intake only): the new character goes straight to its
			-- custody stage's spot RIGHT NOW, before anything yields. Waiting even a
			-- fraction of a second let the player's client take the body over at its
			-- spawn point, and every later server teleport was overridden.
			local stage=PrisonFlow.syncStage(player,"respawn")
			-- v290: a Police HQ case is placed by the HQ branch below (the car, the desk, HQ holding) -
			-- this stage table would send "Transport" to prison intake
			local okAnchor,anchor=false,nil
			if not (PrisonFlow.hq[player] and not sentenceEnd[player]) then okAnchor,anchor=pcall(PrisonFlow.respawnAnchor,player,stage) end
			if okAnchor and anchor then
				pcall(function() char:PivotTo(anchor) end)
				print(("[Custody] RESPAWN %s stage=%s -> %s"):format(player.Name,stage,PrisonFlow.RESPAWN_AT[stage] or "?"))
				if PrisonFlow.RESPAWN_AT[stage]=="Cell" then
					-- the client also holds the character there while the cell is restored
					player:SetAttribute("CustodyPinCF",anchor)
					task.delay(6,function()
						if player:GetAttribute("CustodyPinCF")==anchor then player:SetAttribute("CustodyPinCF",nil) end
					end)
				end
			elseif not okAnchor then
				warn("[Custody] RESPAWN anchor failed for "..player.Name..": "..tostring(anchor))
			end
			-- v225: a detainee who dies respawns INSIDE intake (a hidden spawn on an
			-- intake cell floor) instead of at the team spawn across the map
			player:SetAttribute("PrisonKilledBy",nil) -- v237: fresh character, no killer on record
			local dh=char:WaitForChild("Humanoid",5)
			if dh then
				dh.Died:Connect(function()
					-- v237: an inmate KILLED in prison (a gang hit, a fight, a riot) is wiped
					-- like an executed player: a brand-new player. Resetting your own
					-- character or falling through the map never records a killer.
					local killer=player:GetAttribute("PrisonKilledBy")
					if type(killer)=="string" and sentenceEnd[player] and not deathRowExecutionActive[player]
						and player:GetAttribute("DeathRowExecutionStarted")~=true then
						player:SetAttribute("PrisonKilledBy",nil)
						warn(("[PrisonDeath] %s was killed in prison by %s - profile reset"):format(player.Name,killer))
						resetExecutedPlayer(player)
						clearJusticeState(player)
						releaseBusy[player]=nil
						pcall(uncuff,player)
						for _,name in {"Solitary","PoliceCuffed","SnitchedOn","CORespect"} do player:SetAttribute(name,nil) end
						pcall(tell,player,"Released","killed")
						for _,other in Players:GetPlayers() do
							if other~=player then pcall(tell,other,"Notice",player.Name.." was killed in prison") end
						end
						return
					end
					-- v290: a Police HQ case (arrest -> HQ booking / holding / arraignment) respawns at HQ, not prison intake
					if not sentenceEnd[player] and not releaseBusy[player] and not PrisonFlow.hq[player] and (custody[player] or PrisonFlow.isDetainee(player)) then
						local sp=PrisonFlow.intakeSpawn()
						if sp then
							-- v234: a team spawn only counts for its own team
							PrisonFlow.team(player,"Intake Prisoners")
							player.RespawnLocation=sp
						end
					elseif player.RespawnLocation and player.RespawnLocation.Name=="IntakeRespawn" then
						player.RespawnLocation=nil
					end
				end)
			end
			if player.RespawnLocation and player.RespawnLocation.Name=="IntakeRespawn" and not custody[player] and not PrisonFlow.isDetainee(player) then
				player.RespawnLocation=nil
			end
			-- v290: reset during a Police HQ case: back into the HQ holding cell (the HQ flow carries on
			-- with the new character) - it used to fall through to the prison-intake recovery below
			local hqRec=PrisonFlow.hq[player]
			if hqRec and hqRec.hold and not sentenceEnd[player] then
				if player.RespawnLocation and player.RespawnLocation.Name=="IntakeRespawn" then player.RespawnLocation=nil end
				task.wait(0.15)
				if not player.Parent or player.Character~=char then return end
				local _,hh,rr=Util.charInfo(player)
				local stage=tostring(player:GetAttribute("BookingState") or "")
				local where="HQ holding"
				local ride=PrisonFlow.rideSeat and PrisonFlow.rideSeat[player]
				if rr and hh then
					rr.AssemblyLinearVelocity=Vector3.zero
					if ride and ride.body and ride.body.Parent then
						-- on the way to HQ: back in the car, which drives on (it waits for no one)
						local body=ride.body
						rr.CFrame=body.CFrame*CFrame.new(-1.3,body.Size.Y/2+1.1,2.4);hh.Sit=true
						pcall(custodyTransportGhost,char,true)
						local w=Instance.new("WeldConstraint");w.Name="HQRideSeat";w.Part0=body;w.Part1=rr;w.Parent=body
						if ride.weld and ride.weld~=w then pcall(function() ride.weld:Destroy() end) end
						ride.weld=w
						pcall(function() rr:SetNetworkOwner(nil) end) -- the server carries them (no client pulling back to the spawn)
						pcall(cuff,player)
						where="the transport car"
					elseif stage=="HQBooking" and hqRec.desk then
						rr.CFrame=CFrame.new(hqRec.desk);pcall(cuff,player)
						where="the booking desk"
					elseif (stage=="Arrested" or stage=="Transport" or stage=="HQTransport") and PrisonFlow.lastRootCF and PrisonFlow.lastRootCF[player] then
						-- not in the car yet: back where the old character was (the officer is walking them to it).
						-- (Not ServerRootCF - that already tracks the NEW character at its spawn point.)
						rr.CFrame=PrisonFlow.lastRootCF[player];pcall(cuff,player)
						where="the arrest scene"
					else
						rr.CFrame=CFrame.new(hqRec.hold)
					end
					if not ride then
						player:SetAttribute("CustodyPinCF",rr.CFrame)
						task.delay(2,function() if player.Character==char then player:SetAttribute("CustodyPinCF",nil) end end)
					end
				end
				hqRec.char=char
				PrisonFlow.team(player,"Police Custody")
				print(("[CustodyDiag] RESPAWN %s in a Police HQ case (%s) - back to %s"):format(player.Name,stage,where))
				return
			end
			-- v222: anyone who is still a detainee (intake / booking, not yet sentenced)
			-- goes back to an intake cell, even if a flag got lost on the way (custody
			-- cleared by another flow, or a stale "critical" flag with no saved case)
			if not sentenceEnd[player] and not releaseBusy[player] and PrisonFlow.isDetainee(player) then
				if not custody[player] then
					warn("[CustodyDiag] RESPAWN detainee "..player.Name.." had no custody flag - restoring intake custody")
					custody[player]=true
				end
				if criticalCustody[player] and not bookingCase[player] and player:GetAttribute("BookingState")~="MedicalEMS" then
					criticalCustody[player]=nil;player:SetAttribute("PoliceCritical",nil)
				end
			end
			-- v212: dying while EMS had you still ends up in intake, not at a public spawn
			if custody[player] and criticalCustody[player] and bookingCase[player] then
				criticalCustody[player]=nil;player:SetAttribute("PoliceCritical",nil)
				player:SetAttribute("CustodyPhase","Detainee");player:SetAttribute("BookingState","Arrested")
			end
			if custody[player] and not criticalCustody[player] then
				player:SetAttribute("CustodyResetRecoveryPending",true)
				PrisonFlow.team(player,"Intake Prisoners")
			end
			-- Give the new character a short escape-check grace window while its cell is restored.
			if sentenceEnd[player] then player:SetAttribute("CustodyRespawnGraceUntil",Workspace:GetServerTimeNow()+6) end
			task.wait(0.15)
			if not player.Parent or player.Character ~= char then return end
			local restored=restorePrisonRespawn(player,char)
			if custody[player] and not criticalCustody[player] then recoverCustodyRespawn(player) end
			print(("[CustodyDiag] RESPAWN %s custody=%s critical=%s sentence=%s booking=%s phase=%s restored=%s recovery=%s"):format(
				player.Name,tostring(custody[player]),tostring(criticalCustody[player]),tostring(sentenceEnd[player]~=nil),
				tostring(player:GetAttribute("BookingState")),tostring(player:GetAttribute("CustodyPhase")),tostring(restored),tostring(custodyRecovery[player]~=nil)))
			-- v215 watchdog: a prisoner / detainee must never keep a public spawn
			task.delay(4,function()
				if not player.Parent or player.Character~=char then return end
				local _,h,r=Util.charInfo(player)
				if not h or not r or not outsidePrison(r.Position,nil) then return end
				-- v223: already standing in the assigned cell (intake cells sit outside the
				-- facility's bounding box) - leave the running recovery alone
				local room=PrisonFlow.rooms[player]
				if room and room.pos and Util.flat(r.Position-room.pos).Magnitude<12 and math.abs(r.Position.Y-room.pos.Y)<8 then return end
				if not custody[player] and not sentenceEnd[player] and not releaseBusy[player] and PrisonFlow.isDetainee(player) then custody[player]=true end
				-- v225: a recovery already running for this character keeps its own guard
				-- (restarting it cancelled the intake hold) - just put them back in the cell
				local running=custodyRecovery[player]
				if running and running.character==char then
					if room and room.pos then
						warn("[CustodyDiag] RESPAWN WATCHDOG: "..player.Name.." outside during recovery - back into "..tostring(room.name))
						r.AssemblyLinearVelocity=Vector3.zero
						r.CFrame=CFrame.new(room.pos+Vector3.new(0,3.25,0))
					end
					return
				end
				if custody[player] and not criticalCustody[player] then
					warn("[CustodyDiag] RESPAWN WATCHDOG: detainee "..player.Name.." still outside - restarting intake recovery")
					custodyRecovery[player]=nil
					recoverCustodyRespawn(player)
				elseif sentenceEnd[player] then
					warn("[CustodyDiag] RESPAWN WATCHDOG: inmate "..player.Name.." still outside - back to the assigned cell")
					if player:GetAttribute("BookingState")~="Housed" then player:SetAttribute("BookingState","Housed") end
					if not restorePrisonRespawn(player,char) then
						local room=PrisonFlow.rooms[player]
						if room and room.pos then r.CFrame=CFrame.new(room.pos+Vector3.new(0,3,0)) end
					end
				end
			end)
			if player:GetAttribute("PrisonClothesIssued")==true then
				PrisonFlow.applyInmateClothes(player,tostring(player:GetAttribute("SecurityClass") or "Medium"))
			end
			updateBadge(player, Heat.stars(player))
			if Util.isLaw(player) and not inPrison(player) then
				issueGear(player)
			end
		end)
		player:GetPropertyChangedSignal("Team"):Connect(function()
			if Util.isLaw(player) then
				issueGear(player)
			else
				revokeGear(player)
			end
		end)
		-- the bank script flags robbers with the old "Wanted" attribute
		player:GetAttributeChangedSignal("Wanted"):Connect(function()
			if player:GetAttribute("Wanted") == true and Heat.stars(player) == 0 and not inPrison(player) then
				external(player, "Bank robbery", 3)
			end
		end)
		if player.Character then
			task.spawn(issueGear, player)
		end
	end
	for _, player in Players:GetPlayers() do
		task.spawn(onPlayer, player)
	end
	Players.PlayerAdded:Connect(onPlayer)
	Players.PlayerRemoving:Connect(function(player)
		PrisonSave.save(player) -- before the sentence tables are cleared
		charges[player], sentenceEnd[player], previousTeam[player] = nil, nil, nil
		crimeKeys[player], inmateFacility[player] = nil, nil
		policeOfficerKills[player]=nil
		heldGuns[player], recentCrime[player], custody[player] = nil, nil, nil
		bookingCase[player], bookingBusy[player] = nil, nil
		bookingGeneration[player]=nil;custodyRecovery[player]=nil
		PrisonFlow.escortCollision(player,false);PrisonFlow.waiters[player]=nil;PrisonFlow.claimCharacters[player]=nil;PrisonFlow.rooms[player]=nil;PrisonFlow.reserved[player]=nil;PrisonFlow.jobs[player]=nil
		if PrisonFlow.pending[player] then PrisonFlow.pending[player]:despawn("player left");PrisonFlow.pending[player]=nil end
		lastTase[player], lastRadio[player] = nil, nil
	end)

	task.spawn(sentenceLoop)
end

return Justice

end

-- =====================================================================
-- MODULE: IncidentController
-- =====================================================================
__modules["IncidentController"] = function()
local Players=game:GetService("Players")
local Config=__require("Config")
local State=__require("State")
local Heat=__require("Heat")
local CopAI=__require("CopAI")
local IncidentController={}
local incidents={} :: {[Player]: any}
local serial=0

local function ensure(player: Player,p: any)
    local inc=incidents[player]
    if inc then return inc end
    serial+=1
    inc={id=serial,player=player,created=os.clock(),lastRole=0,lastSeen=nil,lastSeenAt=0,roles={}}
    incidents[player]=inc
    player:SetAttribute("PoliceIncidentId",serial)
    return inc
end

local function roleFor(c:any,index:number,total:number): string
    if c.unitType=="Riot" then return "Shield" end
    if c.beanbag or c.unitType=="Shotgunner" then return "LessLethal" end
    if index<=Config.Incident.MaxCloseContact then return if index==1 then "Contact" else "Arrest" end
    if index%3==0 then return "Containment" end
    if index%3==1 then return "Cover" end
    return "Search"
end

local function assign(inc:any,p:any,now:number)
    if now-inc.lastRole < Config.Incident.RoleRefresh then return end
    inc.lastRole=now
    local cops=CopAI.list(function(c) return c.alive and c.pursuit==p end)
    table.sort(cops,function(a,b)
        local pa=a.root and a.root.Position or Vector3.zero
        local pb=b.root and b.root.Position or Vector3.zero
        local target=p.lastSeenPos or Vector3.zero
        return (pa-target).Magnitude < (pb-target).Magnitude
    end)
    for i,c in cops do
        local role=roleFor(c,i,#cops)
        inc.roles[c]=role
        if c.model and c.model.Parent then
            c.model:SetAttribute("IncidentId",inc.id)
            c.model:SetAttribute("IncidentRole",role)
        end
    end
end

function IncidentController.step(_dt:number)
    if not Config.Incident.Enabled then return end
    local now=os.clock(); local active={}
    for _,p in Heat.pursuits do
        if p.player and p.player.Parent then
            active[p.player]=true
            local inc=ensure(p.player,p)
            if p.lastSeenPos and p.lastSeenTime and p.lastSeenTime>inc.lastSeenAt then
                inc.lastSeen=p.lastSeenPos; inc.lastSeenAt=p.lastSeenTime
                p.player:SetAttribute("PoliceLastSeenAt",p.lastSeenTime)
            end
            assign(inc,p,now)
        end
    end
    for player,inc in incidents do
        if not active[player] then
            for cop in inc.roles do
                if cop.model and cop.model.Parent then cop.model:SetAttribute("IncidentRole",nil);cop.model:SetAttribute("IncidentId",nil) end
            end
            incidents[player]=nil
            if player.Parent then player:SetAttribute("PoliceIncidentId",nil) end
        end
    end
end
function IncidentController.get(player:Player) return incidents[player] end
return IncidentController
end

-- =====================================================================
-- MODULE: PrisonSchedule
-- =====================================================================
__modules["PrisonSchedule"] = function()
local Lighting=game:GetService("Lighting")
local Players=game:GetService("Players")
local Config=__require("Config")
local PrisonSchedule={}
local function scheduledBlock(hour:number):string
    for _,b in Config.PrisonSchedule.Blocks do
        if hour>=b.Start and hour<b.Finish then return b.Name end
    end
    return "Lockdown"
end
function PrisonSchedule.step(_dt:number)
    if not Config.PrisonSchedule.Enabled then return end
    local base=scheduledBlock(Lighting.ClockTime)
    for _,p in Players:GetPlayers() do
        local phase=tostring(p:GetAttribute("CustodyPhase") or "")
        if phase=="SentencedPrisoner" or (p.Team and p.Team.Name==Config.Justice.PrisonerTeam) then
            local class=tostring(p:GetAttribute("SecurityClass") or "Unclassified")
            local state=Config.PrisonSchedule.ClassOverrides[class] or base
            p:SetAttribute("PrisonSchedule",state)
        elseif phase~="" then
            p:SetAttribute("PrisonSchedule","Processing")
        end
    end
end
return PrisonSchedule
end

-- =====================================================================
-- MODULE: PrisonAuthorization
-- =====================================================================
__modules["PrisonAuthorization"] = function()
local Players=game:GetService("Players")
local Workspace=game:GetService("Workspace")
local CollectionService=game:GetService("CollectionService")
local Config=__require("Config")
local Util=__require("Util")
local PrisonAuthorization={}
local elapsed=0

local function csvHas(value:any,wanted:string): boolean
    if value==nil or tostring(value)=="" or tostring(value)=="*" then return true end
    for token in string.gmatch(tostring(value),"[^,]+") do
        token=string.gsub(token,"^%s*(.-)%s*$","%1")
        if string.lower(token)==string.lower(wanted) then return true end
    end
    return false
end
local function bounds(inst:Instance):(CFrame?,Vector3?)
    if inst:IsA("BasePart") then return inst.CFrame,inst.Size end
    if inst:IsA("Model") then return inst:GetBoundingBox() end
    return nil,nil
end
local function pointInMapperPolygon(inst:Instance,pos:Vector3):boolean?
    local cp=inst:FindFirstChild("ControlPoints")
    if not cp then return nil end
    local pts={}
    for _,v in cp:GetChildren() do
        if v:IsA("Vector3Value") then table.insert(pts,v) end
    end
    table.sort(pts,function(a,b) return a.Name<b.Name end)
    if #pts<3 then return nil end
    local bottom=tonumber(inst:GetAttribute("BottomY")) or -math.huge
    local top=tonumber(inst:GetAttribute("TopY")) or math.huge
    if pos.Y<bottom or pos.Y>top then return false end
    local inside=false
    local j=#pts
    for i=1,#pts do
        local a=pts[i].Value;local b=pts[j].Value
        if ((a.Z>pos.Z)~=(b.Z>pos.Z)) then
            local x=(b.X-a.X)*(pos.Z-a.Z)/(b.Z-a.Z)+a.X
            if pos.X<x then inside=not inside end
        end
        j=i
    end
    return inside
end
local function contains(inst:Instance,pos:Vector3):boolean
    local poly=pointInMapperPolygon(inst,pos)
    if poly~=nil then return poly end
    local cf,size=bounds(inst); if not cf or not size then return false end
    local q=cf:PointToObjectSpace(pos)
    return math.abs(q.X)<=size.X/2 and math.abs(q.Y)<=size.Y/2 and math.abs(q.Z)<=size.Z/2
end
local function zones():{Instance}
    local out={}; local seen={}
    local folder=Workspace:FindFirstChild(Config.PrisonSecurity.ZoneFolder)
    if folder then for _,z in folder:GetChildren() do table.insert(out,z);seen[z]=true end end
    local prison=Workspace:FindFirstChild(Config.Justice.PrisonModel)
    local map=prison and prison:FindFirstChild("PrisonMap") or Workspace:FindFirstChild("PrisonMap")
    local mapped=map and map:FindFirstChild("Zones")
    if mapped then
        for _,z in mapped:GetChildren() do
            if not seen[z] and (z:GetAttribute("PrisonZone")==true or z:FindFirstChild("ControlPoints")) then
                table.insert(out,z);seen[z]=true
            end
        end
    end
    for _,z in CollectionService:GetTagged(Config.PrisonSecurity.ZoneTag) do if not seen[z] then table.insert(out,z) end end
    return out
end
function PrisonAuthorization.currentZone(player:Player):Instance?
    local _,_,root=Util.charInfo(player); if not root then return nil end
    local best=nil;local bestPriority=-math.huge
    for _,z in zones() do
        if contains(z,root.Position) then
            local pri=tonumber(z:GetAttribute("Priority")) or 0
            if pri>bestPriority then best=z;bestPriority=pri end
        end
    end
    return best
end
function PrisonAuthorization.isAuthorized(player:Player,zone:Instance?):(boolean,string)
    if not zone then return true,"Unzoned" end
    if zone:GetAttribute("AlwaysAuthorized")==true then return true,"Always" end
    local phase=tostring(player:GetAttribute("CustodyPhase") or player:GetAttribute("BookingState") or "")
    local class=tostring(player:GetAttribute("SecurityClass") or "Unclassified")
    local schedule=tostring(player:GetAttribute("PrisonSchedule") or "Unscheduled")
    local housing=tostring(player:GetAttribute("HousingUnit") or "")
    if player:GetAttribute("ActivePrisonEscort")==true and zone:GetAttribute("EscortAllowed")~=false then return true,"Escort" end
    if not csvHas(zone:GetAttribute("AllowedCustodyStages"),phase) then return false,"CustodyStage" end
    if not csvHas(zone:GetAttribute("AllowedClasses"),class) then return false,"Classification" end
    if not csvHas(zone:GetAttribute("AllowedSchedules"),schedule) then return false,"Schedule" end
    local zh=tostring(zone:GetAttribute("HousingUnit") or "")
    if zh~="" and housing~="" and string.lower(zh)~=string.lower(housing) then return false,"HousingUnit" end
    return true,"Policy"
end
function PrisonAuthorization.step(dt:number)
    if not Config.PrisonSecurity.Enabled then return end
    elapsed+=dt;if elapsed<Config.PrisonSecurity.CheckInterval then return end;elapsed=0
    for _,player in Players:GetPlayers() do
        local phase=player:GetAttribute("CustodyPhase")
        local inmate=player.Team and player.Team.Name==Config.Justice.PrisonerTeam
        if phase or inmate then
            local zone=PrisonAuthorization.currentZone(player)
            local ok,reason=PrisonAuthorization.isAuthorized(player,zone)
            player:SetAttribute("PrisonZone",zone and zone.Name or "Unzoned")
            player:SetAttribute("PrisonZoneAuthorized",ok)
            player:SetAttribute("PrisonZoneReason",reason)
            if not ok then
                if not player:GetAttribute("PrisonViolationSince") then player:SetAttribute("PrisonViolationSince",os.clock()) end
                player:SetAttribute("PrisonViolation","Unauthorized")
            else
                player:SetAttribute("PrisonViolationSince",nil);player:SetAttribute("PrisonViolation",nil)
            end
        end
    end
end
return PrisonAuthorization
end

-- =====================================================================
-- MODULE: Breach (v212)
-- =====================================================================
__modules["Breach"] = function()
--[[
	PoliceAI · Breach
	A wanted suspect (3+ stars) holed up INSIDE a building (the bank, a casino...)
	gets a real tactical entry instead of officers piling up at a wall:
	  1. STACK  - tactical officers form a single-file stack beside the entrance
	              and WAIT for the team (3+ officers, or 25s).
	  2. BANG   - the point man throws a flashbang AROUND THE CORNER (the first
	              point on the path in that the stack can't see), tear gas onto the
	              suspect's last known position and smoke in the doorway. At five
	              stars and lethal force the corner gets a frag instead.
	  3. ENTRY  - they go in single file behind the point man.
	  4. CLEAR  - once anyone has eyes on the suspect the squad fights / arrests
	              normally; while the suspect stays hidden inside, the nearest
	              officer keeps clearing the next corner with a flashbang (or frag).
]]
local Players = game:GetService("Players")
local Workspace = game:GetService("Workspace")
local PathfindingService = game:GetService("PathfindingService")

local Config = __require("Config")
local State = __require("State")
local Util = __require("Util")
local Heat = __require("Heat")
local CopAI = __require("CopAI")
local Weapons = __require("Weapons")

local Breach = {}
local ops: { [any]: any } = {}
local nextCheck: { [any]: number } = {}

local TACTICAL = { Shotgunner = true, SWAT = true, Riot = true, Heavy = true, SEAL = true, Juggernaut = true, Army = true }
local MIN_STARS = 3
local STACK_WAIT = 25
local STACK_READY = 3
local CLEAR_EVERY = 9

-- a roof over it and walls around it
local function indoors(pos: Vector3, ignore: { Instance }): (boolean, Instance?)
	local roof = Util.cast(pos + Vector3.new(0, 2.5, 0), Vector3.new(0, 70, 0), ignore)
	if not roof or not roof.Instance then
		return false, nil
	end
	local walls = 0
	for i = 0, 7 do
		local a = i * math.pi / 4
		local hit = Util.cast(pos + Vector3.new(0, 1.5, 0), Vector3.new(math.cos(a), 0, math.sin(a)) * 80, ignore)
		if hit then
			walls += 1
		end
	end
	if walls < 5 then
		return false, nil
	end
	local top: Instance = roof.Instance
	while top.Parent and top.Parent ~= Workspace do
		top = top.Parent
	end
	return true, top
end

local function suspectInfo(p: any): (Model?, Humanoid?, BasePart?)
	local char, hum, root = Util.charInfo(p.player)
	if not char or not hum or not root or hum.Health <= 0 or hum.SeatPart then
		return nil, nil, nil
	end
	return char, hum, root
end

local function team(p: any, near: Vector3): { any }
	local list = CopAI.list(function(c)
		return c.alive and c.pursuit == p and c.root ~= nil and TACTICAL[c.unitType] == true
			and (c.root.Position - near).Magnitude < 260
	end)
	if #list < STACK_READY then
		-- short on tactical officers: patrol officers on the call join the stack
		for _, c in CopAI.list(function(c)
			return c.alive and c.pursuit == p and c.root ~= nil and not TACTICAL[c.unitType]
				and (c.root.Position - near).Magnitude < 200
		end) do
			table.insert(list, c)
			if #list >= 4 then
				break
			end
		end
	end
	table.sort(list, function(a, b)
		return (a.root.Position - near).Magnitude < (b.root.Position - near).Magnitude
	end)
	return list
end

-- entry: the last outdoor point (stack) and the first indoor point on the
-- walking path from the officers to the suspect
local function findEntry(from: Vector3, to: Vector3, ignore: { Instance }): (Vector3?, Vector3?, { Vector3 }?)
	local path = PathfindingService:CreatePath({ AgentRadius = 2, AgentHeight = 5, AgentCanJump = true, WaypointSpacing = 4 })
	local ok = pcall(function()
		path:ComputeAsync(from, to)
	end)
	if ok and (path.Status == Enum.PathStatus.Success or path.Status == Enum.PathStatus.ClosestNoPath) then
		local pts = {}
		for _, wp in path:GetWaypoints() do
			table.insert(pts, wp.Position)
		end
		for i = 2, #pts do
			if indoors(pts[i], ignore) then
				local inside = {}
				for k = i, #pts do
					table.insert(inside, pts[k])
				end
				return pts[i - 1], pts[i], inside
			end
		end
	end
	return nil, nil, nil
end

-- first point along the inside path that the thrower can't see: "around the corner"
local function cornerPoint(eye: Vector3, inside: { Vector3 }?, suspectPos: Vector3, ignore: { Instance }): Vector3
	if inside then
		for _, pt in inside do
			local target = pt + Vector3.new(0, 1.5, 0)
			local hit = Util.cast(eye, target - eye, ignore)
			if hit and (hit.Position - target).Magnitude > 2.5 then
				return pt
			end
			if (pt - eye).Magnitude > 50 then
				return pt
			end
		end
	end
	return suspectPos
end

local function insidePathFrom(from: Vector3, to: Vector3): { Vector3 }?
	local path = PathfindingService:CreatePath({ AgentRadius = 2, AgentHeight = 5, AgentCanJump = true, WaypointSpacing = 4 })
	local ok = pcall(function()
		path:ComputeAsync(from, to)
	end)
	if not ok or (path.Status ~= Enum.PathStatus.Success and path.Status ~= Enum.PathStatus.ClosestNoPath) then
		return nil
	end
	local pts = {}
	for _, wp in path:GetWaypoints() do
		table.insert(pts, wp.Position)
	end
	return pts
end

local function throwAt(cop: any, p: any, target: Vector3, lethal: boolean)
	local from = cop.head.Position + cop.root.CFrame.LookVector * 1.2 + Vector3.new(0, 0.5, 0)
	cop:face(target)
	if lethal and (cop.ordnance or 0) > 0 then
		cop.ordnance -= 1
		Weapons.throwTacticalOrdnance("FRAG", from, target, function(pos)
			-- frags only hurt the wanted, never bystanders
			for _, plr in Players:GetPlayers() do
				local hp = Heat.get(plr)
				local _, h, r = Util.charInfo(plr)
				if hp and hp.stars > 0 and h and r then
					local d = (r.Position - pos).Magnitude
					if d < 14 then
						h:TakeDamage(60 * (1 - d / 14))
					end
				end
			end
		end)
		State.log(p.player.Name, "breach: frag around the corner")
	else
		Weapons.throwFlashbang(from, target)
		if cop.flashbangs and cop.flashbangs > 0 then
			cop.flashbangs -= 1
		end
		State.log(p.player.Name, "breach: flashbang around the corner")
	end
end

local function setScripted(c: any, on: boolean)
	if on then
		c.aiScripted = true
	else
		c.aiScripted = nil
		c.aiHoldPos = nil
	end
end

local function finish(p: any, why: string)
	local op = ops[p]
	if not op then
		return
	end
	for c in op.members do
		if c.alive then
			setScripted(c, false)
		end
	end
	ops[p] = nil
	nextCheck[p] = os.clock() + 12
	State.log(p.player.Name, "breach ended:", why)
end

local function start(p: any, root: BasePart, char: Model, now: number)
	local members = team(p, root.Position)
	if #members == 0 then
		return
	end
	local ignore = { char }
	local centroid = Vector3.zero
	for _, c in members do
		centroid += c.root.Position
	end
	centroid /= #members
	local stack, entry, inside = findEntry(centroid, root.Position, ignore)
	if not stack or not entry then
		return
	end
	local inward = Util.safeUnit(Util.flat(entry - stack), Vector3.zAxis)
	local side = Vector3.new(-inward.Z, 0, inward.X)
	local op = {
		phase = "STACK",
		started = now,
		stack = stack,
		entry = entry,
		inward = inward,
		side = side,
		inside = inside,
		members = {},
		order = {},
		trail = {},
		nextClear = 0,
		outsideSince = nil,
	}
	for i, c in members do
		op.members[c] = i
		op.order[i] = c
		setScripted(c, true)
		c:setGunOut(true)
	end
	ops[p] = op
	State.announce(p.player, "SWAT IS STACKING UP AT THE ENTRANCE", "danger")
	State.log(p.player.Name, "breach: stack at", tostring(stack), "entry", tostring(entry), "officers", #members)
end

local function slotFor(op: any, i: number): Vector3
	-- single file along the wall beside the doorway
	local p = op.stack + op.side * 2.2 - op.inward * (1.2 + (i - 1) * 2.3)
	return Util.groundAt(p, 6, 14) or p
end

local function step(p: any, now: number)
	local op = ops[p]
	local char, hum, root = suspectInfo(p)
	if not op then
		if not char or not root or p.stars < MIN_STARS or now < (nextCheck[p] or 0) then
			return
		end
		nextCheck[p] = now + 3
		local inside = indoors(root.Position, { char })
		if inside then
			start(p, root, char, now)
		end
		return
	end
	if not p.active or not char or not root or (hum and hum:GetAttribute("PoliceCuffed")) then
		finish(p, "suspect gone / in custody")
		return
	end
	-- drop the dead / reassigned
	for c in op.members do
		if not c.alive or c.pursuit ~= p then
			op.members[c] = nil
		end
	end
	local order = {}
	for _, c in op.order do
		if op.members[c] then
			table.insert(order, c)
		end
	end
	op.order = order
	if #order == 0 then
		finish(p, "no officers left")
		return
	end
	-- the suspect walked out: normal tactics outside
	local stillInside = indoors(root.Position, { char })
	if not stillInside then
		op.outsideSince = op.outsideSince or now
		if now - op.outsideSince > 4 then
			finish(p, "suspect left the building")
			return
		end
	else
		op.outsideSince = nil
	end
	-- late arrivals join the stack
	if op.phase == "STACK" then
		for _, c in team(p, op.stack) do
			if not op.members[c] then
				op.members[c] = #op.order + 1
				table.insert(op.order, c)
				setScripted(c, true)
			end
		end
	end

	local lethal = p.lethal == true and p.stars >= 5
	if op.phase == "STACK" then
		local ready = 0
		for i, c in op.order do
			local slot = slotFor(op, i)
			if Util.flat(c.root.Position - slot).Magnitude < 3.5 then
				ready += 1
				c:stop()
				c:face(op.entry)
			else
				c:moveTo(slot, true)
			end
		end
		if ready >= math.min(STACK_READY, #op.order) or now - op.started > STACK_WAIT then
			op.phase = "BANG"
			op.bangAt = now
			local lead = op.order[1]
			local eye = lead.head.Position
			local corner = cornerPoint(eye, op.inside, root.Position, { char })
			throwAt(lead, p, corner, lethal)
			-- gas onto the known position, smoke in the doorway
			local second = op.order[2] or lead
			local from = second.head.Position + Vector3.new(0, 0.5, 0)
			if (second.tearGas or 0) > 0 and (root.Position - from).Magnitude < 70 then
				second.tearGas -= 1
				Weapons.throwTearGas(from, root.Position, function(gasPos)
					local c2, h2, r2 = Util.charInfo(p.player)
					if c2 and h2 and r2 and (r2.Position - gasPos).Magnitude <= Config.TearGas.Radius then
						Heat.stun(p.player, Config.TearGas.Stun)
					end
				end)
			end
			local third = op.order[3] or lead
			Weapons.throwSmoke(third.head.Position + Vector3.new(0, 0.5, 0), op.entry + op.inward * 4)
			State.announce(p.player, "BREACH! BREACH! BREACH!", "danger")
		end
	elseif op.phase == "BANG" then
		for i, c in op.order do
			c:stop()
			c:face(op.entry)
		end
		if now - op.bangAt > Config.Flashbang.Fuse + 0.3 then
			op.phase = "ENTRY"
			op.entryAt = now
			op.trail = {}
		end
	elseif op.phase == "ENTRY" then
		local lead = op.order[1]
		local known = if State.ai and State.ai.knownPos then State.ai.knownPos(p) else nil
		local goal = known or root.Position
		lead:moveTo(goal, true)
		local last = op.trail[#op.trail]
		if not last or (last - lead.root.Position).Magnitude > 1.5 then
			table.insert(op.trail, lead.root.Position)
		end
		for i = 2, #op.order do
			local c = op.order[i]
			local idx = math.max(1, #op.trail - (i - 1) * 2)
			local target = op.trail[idx] or op.entry
			c:moveTo(target, true)
		end
		-- eyes on: everyone fights / arrests normally from here
		local aim = Util.aimPart(char) or root
		for _, c in op.order do
			if Util.canSee(c.head.Position, char, aim) then
				op.phase = "CLEAR"
				op.nextClear = now + CLEAR_EVERY
				for c2 in op.members do
					setScripted(c2, false)
				end
				State.log(p.player.Name, "breach: contact inside")
				break
			end
		end
		if op.phase == "ENTRY" and now - op.entryAt > 30 then
			op.phase = "CLEAR"
			op.nextClear = now
			for c2 in op.members do
				setScripted(c2, false)
			end
		end
	elseif op.phase == "CLEAR" then
		if now >= op.nextClear and stillInside then
			op.nextClear = now + CLEAR_EVERY
			local aim = Util.aimPart(char) or root
			local seen = false
			local nearest, nd = nil, math.huge
			for _, c in op.order do
				if Util.canSee(c.head.Position, char, aim) then
					seen = true
					break
				end
				local d = (c.root.Position - root.Position).Magnitude
				if d < nd then
					nearest, nd = c, d
				end
			end
			if not seen and nearest and nd < 90 and ((nearest.flashbangs or 0) > 0 or (lethal and (nearest.ordnance or 0) > 0)) then
				local pts = insidePathFrom(nearest.root.Position, root.Position)
				local corner = cornerPoint(nearest.head.Position, pts, root.Position, { char })
				throwAt(nearest, p, corner, lethal)
			end
		end
	end
end

local busy = false
local function run()
	local now = os.clock()
	for _, p in Heat.pursuits do
		if p.active and p.stars > 0 then
			local ok, err = pcall(step, p, now)
			if not ok then
				warn("[Breach] " .. tostring(err))
				pcall(finish, p, "error")
			end
		elseif ops[p] then
			finish(p, "pursuit over")
		end
	end
	for p in ops do
		if not p.active then
			finish(p, "pursuit over")
		end
	end
end

-- path queries yield, so a step runs in its own thread and never overlaps
function Breach.step(_dt: number)
	if busy then
		return
	end
	busy = true
	task.spawn(function()
		local ok, err = pcall(run)
		busy = false
		if not ok then
			warn("[Breach] " .. tostring(err))
		end
	end)
end

return Breach
end

-- =====================================================================
-- MODULE: Dispatcher
-- =====================================================================
__modules["Dispatcher"] = function()
--[[
	PoliceAI · Dispatcher
	The "police department". Decides how many cops exist and where they come from.

	  PATROLS   population = Base + PerPlayer × players (capped). Spawned out of sight near
	            players (or at your patrol points), recycled when far from everyone, topped up
	            after a delay when killed.
	  1 STAR    nearest patrols respond and try to arrest. If nobody's around, a patrol unit
	            is sent from off-screen.
	  2+ STARS  waves come out of the police station (run if it's close, drive if it's far,
	            appear off-screen if there's no station). Kill enough of a wave and you gain
	            a star; after a short breather the next, heavier wave rolls. At 5 stars every
	            wave you break comes back bigger. A wave that's still fighting after a while
	            gets reinforcements. Helicopters join per tier; at 5 stars SWAT fast-rope in.
]]

local Players = game:GetService("Players")
local Workspace = game:GetService("Workspace")

local Config = __require("Config")
local State = __require("State")
local Util = __require("Util")
local Heat = __require("Heat")
local Units = __require("Units")
local CopAI = __require("CopAI")
local Van = __require("Van")
local Heli = __require("Helicopter")
local RoadGraph = __require("RoadGraph")
local IncidentController = __require("IncidentController")

local Dispatcher = {}

local rng = Util.rng

local stations: { CFrame } = {}
local patrolPoints: { Vector3 } = {}
local queue: { any } = {}
local patrolCooldowns: { number } = {}
local lastPatrolSpawn = 0
local lastPatrolTick = 0
local lastRecycle = 0
local lastVanStep = 0
local patrolCars: { any } = {}
local carCooldowns: { number } = {}
local lastCarSpawn = 0
local lastCarTick = 0
local waveIds = 0

---------------------------------------------------------------------------
-- world discovery
---------------------------------------------------------------------------
local function groundCf(pos: Vector3, facing: Vector3?): CFrame?
	local g = Util.groundAt(pos, 4, 30)
	if not g then
		return nil
	end
	local f = Util.safeUnit(Util.flat(facing or Vector3.zAxis), Vector3.zAxis)
	return CFrame.lookAt(g, g + f)
end

local function isOurs(inst: Instance): boolean
	local root = State.folders.Root
	return root ~= nil and inst:IsDescendantOf(root)
end

function Dispatcher.refreshWorld()
	stations = {}
	patrolPoints = {}

	local folder = Workspace:FindFirstChild(Config.SpawnFolderName)
	if folder then
		for _, d in folder:GetDescendants() do
			if d:IsA("BasePart") then
				local cf = groundCf(d.Position + Vector3.new(0, 2, 0), d.CFrame.LookVector)
				table.insert(stations, cf or CFrame.new(d.Position - Vector3.new(0, d.Size.Y / 2, 0)))
			end
		end
	end

	-- v240: mapped Police HQ points (PoliceSpawn, else VehicleDropoff) when there's no PoliceSpawns folder
	if #stations == 0 and State.Facilities then
		for _, kind in { "PoliceSpawn", "VehicleDropoff" } do
			for _, p in State.Facilities.points("PoliceHQ", kind) do
				table.insert(stations, groundCf(p.position + Vector3.new(0, 2, 0), p.cframe.LookVector) or p.cframe)
			end
			if #stations > 0 then
				State.log("stations from mapped Police HQ", kind, #stations)
				break
			end
		end
	end
	if #stations == 0 then
		-- No PoliceSpawns folder: every top-level model named like a police station gets exits around it.
		local found: { Instance } = {}
		for _, d in Workspace:GetChildren() do
			if (d:IsA("Model") or d:IsA("BasePart")) and not isOurs(d) then
				local lname = string.lower(d.Name)
				for _, hint in Config.StationNameHints do
					if string.find(lname, hint, 1, true) then
						table.insert(found, d)
						break
					end
				end
			end
		end
		for _, best in found do
			local cf: CFrame, size: Vector3
			if best:IsA("Model") then
				cf, size = best:GetBoundingBox()
			else
				cf, size = (best :: BasePart).CFrame, (best :: BasePart).Size
			end
			local bottom = cf.Position.Y - size.Y / 2
			local radius = math.max(size.X, size.Z) / 2 + 8
			local before = #stations
			for i = 0, 11 do
				local a = i / 12 * math.pi * 2
				local probe = Vector3.new(cf.X + math.cos(a) * radius, bottom + 2, cf.Z + math.sin(a) * radius)
				local g = Util.groundAt(probe, 6, 40)
				if g and math.abs(g.Y - bottom) < 12 then
					local out = Util.flat(probe - cf.Position)
					table.insert(stations, CFrame.lookAt(g, g + Util.safeUnit(out, Vector3.zAxis)))
				end
			end
			State.log("station auto-detected:", best:GetFullName(), #stations - before, "exits")
		end
	end

	-- v245e: the prison's vehicle gates are a station exit too, so trouble at the
	-- prison (tower kill / stun zones, escapes) gets ground units rolling out of the prison
	do
		local prisonModel = Workspace:FindFirstChild("CorrectionalFacility")
		if prisonModel and prisonModel:IsA("Model") then
			local pcf = prisonModel:GetBoundingBox()
			local added = 0
			for _, d in prisonModel:GetChildren() do
				local n = string.upper(d.Name)
				if (n == "GATE" or n == "GATE1" or n == "GATE2") and (d:IsA("Model") or d:IsA("BasePart")) then
					local gpos = if d:IsA("Model") then d:GetPivot().Position else (d :: BasePart).Position
					local out = Util.safeUnit(Vector3.new(gpos.X - pcf.Position.X, 0, gpos.Z - pcf.Position.Z), Vector3.zAxis)
					local cf = groundCf(gpos + out * 25 + Vector3.new(0, 2, 0), out)
					if cf then
						table.insert(stations, cf)
						added += 1
					end
				end
			end
			if added > 0 then State.log("prison station exits", added) end
		end
	end

	local pf = Workspace:FindFirstChild(Config.PatrolFolderName)
	if pf then
		for _, d in pf:GetDescendants() do
			if d:IsA("BasePart") then
				local g = Util.groundAt(d.Position + Vector3.new(0, 2, 0), 4, 30)
				table.insert(patrolPoints, g or d.Position)
			end
		end
	end
	if #stations == 0 then
		State.log("no police station found: waves will arrive from off-screen")
	end
end

local function nearestStation(pos: Vector3): (CFrame?, number)
	local best: CFrame? = nil
	local bestD = math.huge
	for _, cf in stations do
		local d = (cf.Position - pos).Magnitude
		if d < bestD then
			bestD = d
			best = cf
		end
	end
	return best, bestD
end

local function livingPlayers(): { { player: Player, root: BasePart } }
	local out = {}
	for _, pl in Players:GetPlayers() do
		local _, _, root = Util.charInfo(pl)
		if root then
			table.insert(out, { player = pl, root = root })
		end
	end
	return out
end

local function farFromPlayers(pos: Vector3, minDist: number): boolean
	for _, v in livingPlayers() do
		if (v.root.Position - pos).Magnitude < minDist then
			return false
		end
	end
	return true
end

---------------------------------------------------------------------------
-- patrol goals (hook used by CopAI)
---------------------------------------------------------------------------
local function patrolGoal(from: Vector3): Vector3?
	local cfg = Config.Patrol
	local players = livingPlayers()
	local nearPlayer = #players > 0 and rng:NextNumber() < cfg.NearPlayerBias
	if #patrolPoints > 0 then
		local anchor = if nearPlayer then players[rng:NextInteger(1, #players)].root.Position else from
		local radius = if nearPlayer then 220 else cfg.WanderRadius
		local options = {}
		for _, pt in patrolPoints do
			local d = (pt - anchor).Magnitude
			if d <= radius and (pt - from).Magnitude > 12 then
				table.insert(options, pt)
			end
		end
		if #options == 0 then
			options = patrolPoints
		end
		return options[rng:NextInteger(1, #options)]
	end
	if nearPlayer then
		local pr = players[rng:NextInteger(1, #players)].root.Position
		local pt = Util.randomGroundPoint(pr, 30, 150, 30)
		if pt then
			return pt
		end
	end
	return Util.randomGroundPoint(from, 40, cfg.WanderRadius, 40)
end

---------------------------------------------------------------------------
-- spawn helpers
---------------------------------------------------------------------------
local function facingCf(pos: Vector3, toward: Vector3): CFrame
	local dir = Util.safeUnit(Util.flat(toward - pos), Vector3.zAxis)
	return CFrame.lookAt(pos, pos + dir)
end

-- Somewhere near `target` that no player can see.
local function hiddenCf(target: Vector3, minR: number, maxR: number): CFrame?
	local p = Util.hiddenPointNear(target, minR, maxR)
	if not p then
		return nil
	end
	if Util.visibleToAnyPlayer(p + Vector3.new(0, 3, 0), maxR * 1.6) then
		return nil
	end
	return facingCf(p, target)
end

local function stationCf(station: CFrame, target: Vector3): CFrame
	local jitter = station * CFrame.new(rng:NextNumber(-4, 4), 0, rng:NextNumber(-3, 3))
	return facingCf(jitter.Position, target)
end

local function enqueue(entry)
	table.insert(queue, entry)
end

---------------------------------------------------------------------------
-- PATROLS
---------------------------------------------------------------------------
local function isFootPatrol(c: any): boolean
	return c.role == "Patrol" and not c.homeCar
end

local function isFreePatrol(c: any): boolean
	-- v200: prison staff (guards, escort/processing officers) are not city
	-- patrols; the dispatcher used to despawn them as "excess"/"recycled".
	if c.prisonStaff or (c.model and c.model:GetAttribute("PrisonStaff")) then return false end
	return c.role == "Patrol" and c.pursuit == nil and c.alive
end

local function patrolSpawnCf(): CFrame?
	local players = livingPlayers()
	if #players == 0 then
		return nil
	end
	local anchor = players[rng:NextInteger(1, #players)].root.Position
	local away = Config.Patrol.SpawnAwayFromPlayers
	if #patrolPoints > 0 then
		for _ = 1, 8 do
			local pt = patrolPoints[rng:NextInteger(1, #patrolPoints)]
			local d = (pt - anchor).Magnitude
			if d > away and d < 450 and farFromPlayers(pt, away) and not Util.visibleToAnyPlayer(pt + Vector3.new(0, 3, 0), 400) then
				return facingCf(pt, anchor)
			end
		end
	end
	local cf = hiddenCf(anchor, math.max(away, 110), 280)
	if cf and farFromPlayers(cf.Position, away) then
		return cf
	end
	return nil
end

local function patrolStep(now: number)
	local cfg = Config.Patrol
	if not cfg.Enabled or not Units.isReady() then
		return
	end
	local players = #livingPlayers()
	local desired = if players == 0 then 0 else math.min(cfg.Max, math.floor(cfg.Base + cfg.PerPlayer * players + 0.5))

	for i = #patrolCooldowns, 1, -1 do
		if patrolCooldowns[i] <= now then
			table.remove(patrolCooldowns, i)
		end
	end
	local alive = CopAI.count(isFootPatrol)

	if alive + #patrolCooldowns < desired and now - lastPatrolSpawn > 1.5 then
		lastPatrolSpawn = now
		local cf = patrolSpawnCf()
		if cf then
			CopAI.new("Patrol", cf, {
				role = "Patrol",
				onDied = function()
					table.insert(patrolCooldowns, os.clock() + cfg.RespawnDelay)
				end,
			})
		end
	elseif alive > desired + 1 then
		for _, c in CopAI.list(function(c)
			return isFreePatrol(c) and not c.homeCar
		end) do
			if not Util.visibleToAnyPlayer(c.head.Position, 350) then
				c:despawn("excess")
				break
			end
		end
	end

	-- recycle patrols nobody will ever meet (they respawn closer to people)
	if players > 0 and now - lastRecycle > 5 then
		lastRecycle = now
		for _, c in CopAI.list(function(c)
			return isFreePatrol(c) and not c.homeCar
		end) do
			if farFromPlayers(c.root.Position, 700) and not Util.visibleToAnyPlayer(c.head.Position, 700) then
				c:despawn("recycled")
			end
		end
	end
end

local function assignResponders(p: any, want: number)
	local target = p.lastSeenPos
	if not target then
		return 0
	end
	local assigned = CopAI.count(function(c)
		return c.pursuit == p
	end)
	if assigned >= want then
		return assigned
	end
	local free = CopAI.list(isFreePatrol)
	table.sort(free, function(a, b)
		return (a.root.Position - target).Magnitude < (b.root.Position - target).Magnitude
	end)
	for _, c in free do
		if assigned >= want then
			break
		end
		if (c.root.Position - target).Magnitude <= Config.Patrol.RespondRadius then
			c:assign(p)
			assigned += 1
		end
	end
	return assigned
end

---------------------------------------------------------------------------
-- PATROL CRUISERS (drive the road network, two officers each)
---------------------------------------------------------------------------
local function patrolCarStep(now: number)
	local cfg = Config.PatrolCars
	if not cfg.Enabled or not RoadGraph.ready or not Units.isReady() then
		return
	end
	for i = #patrolCars, 1, -1 do
		local car = patrolCars[i]
		if car.dead or (car.crewTotal <= 0 and car.crewOut <= 0) then
			table.remove(patrolCars, i)
			if not car.dead then
				-- crew wiped out: the car stays as evidence, replacement comes later
				table.insert(carCooldowns, now + Config.Patrol.RespawnDelay * 2)
			end
		end
	end
	for i = #carCooldowns, 1, -1 do
		if carCooldowns[i] <= now then
			table.remove(carCooldowns, i)
		end
	end
	local players = livingPlayers()
	local desired = if #players == 0 then 0 else math.min(cfg.Max, math.floor(cfg.Base + cfg.PerPlayer * #players + 0.5))
	if #patrolCars + #carCooldowns < desired and now - lastCarSpawn > 4 then
		lastCarSpawn = now
		-- roll out of the station nearest a random player, or somewhere out of sight on the roads
		local anchor = players[rng:NextInteger(1, #players)].root.Position
		local st = nearestStation(anchor)
		local from = if st and not Util.visibleToAnyPlayer(st.Position + Vector3.new(0, 4, 0), 200) then st.Position else nil
		if not from then
			for _ = 1, 8 do
				local pt = RoadGraph.randomPoint(anchor, 250, 900)
				if pt and not Util.visibleToAnyPlayer(pt + Vector3.new(0, 4, 0), 260) then
					from = pt
					break
				end
			end
		end
		if from then
			local car = Van.spawnPatrol(from, cfg.Officers)
			if car then
				table.insert(patrolCars, car)
			end
		end
	elseif #patrolCars > desired + 1 then
		for i, car in patrolCars do
			if car:available() and not Util.visibleToAnyPlayer(car.body.Position + Vector3.new(0, 3, 0), 300) then
				car:destroy()
				table.remove(patrolCars, i)
				break
			end
		end
	end
end

local function pursuitTargetInVehicle(p: any): boolean
	local player=p and p.player
	local char=player and player.Character
	local hum=char and char:FindFirstChildOfClass("Humanoid")
	if not hum or not hum.SeatPart then return false end
	return hum.SeatPart:IsA("VehicleSeat")
end

-- v106: responding cruisers must not all compute the exact same final parking point.
-- Give each active car a stable slot around the incident. While the suspect is still
-- driving we chase the live position directly; once they are on foot, the slot spreads
-- the arriving cruisers around the scene instead of stacking them on one another.
local responseSlotByCar: {[any]: number} = {}
local function responseParkingPoint(p: any, car: any, fallbackSlot: number): Vector3?
	local target=p.lastSeenPos
	if not target then return nil end
	-- v113: reserved, de-conflicted stop slots in real lanes (PoliceAI.Parking)
	local ai=State.ai
	if ai and ai.parkingPoint then
		local ok,slot=pcall(ai.parkingPoint,p,car)
		if ok and slot then return slot end
	end
	if pursuitTargetInVehicle(p) then return target end
	local slot=responseSlotByCar[car] or fallbackSlot
	responseSlotByCar[car]=slot
	local ring=math.floor((slot-1)/6)
	local angle=((slot-1)%6)*(math.pi/3)
	local radius=34+ring*18
	return target+Vector3.new(math.cos(angle)*radius,0,math.sin(angle)*radius)
end

-- Send nearest cruising cars to the pursuit. If the suspect is still driving,
-- officers STAY IN THE CRUISER and the vehicle reacquires the moving target instead
-- of immediately unloading into an ineffective foot chase.
local function dispatchCruisers(p: any, want: number)
	local target = p.lastSeenPos
	if not target or want <= 0 then
		return
	end
	local already = 0
	for _, car in patrolCars do
		if car.pursuit == p and not car.dead then
			already += 1
		end
	end
	if already >= want then
		return
	end
	local free = {}
	for _, car in patrolCars do
		if car:available() and (car.body.Position - target).Magnitude <= Config.PatrolCars.RespondRadius then
			table.insert(free, car)
		end
	end
	table.sort(free, function(a, b)
		return (a.body.Position - target).Magnitude < (b.body.Position - target).Magnitude
	end)
	local spotter = p.spottedBy
	if spotter and p.spottedAt and os.clock() - p.spottedAt < 12 and spotter.available and spotter:available()
		and table.find(patrolCars, spotter) and not table.find(free, spotter) then
		table.insert(free, 1, spotter)
	elseif spotter and table.find(free, spotter) then
		table.remove(free, table.find(free, spotter)); table.insert(free, 1, spotter)
	end
	for _, car in free do
		if already >= want then
			break
		end
		local assignedSlot=already+1
		responseSlotByCar[car]=responseSlotByCar[car] or assignedSlot
		local function arrival(van, exits)
			if not p.active then
				van.pursuit=nil;van:cruise();return
			end
			-- v113: suspect is driving -> the pursuit coordinator takes this car (roles, trail, intercepts)
			local ai=State.ai
			if ai and ai.vehicleMode and ai.vehicleMode(p) then
				if ai.offerCar(p,van) then return end
				van.pursuit=nil;van:cruise();return
			end
			if not ai and pursuitTargetInVehicle(p) then
				-- Keep primary/secondary patrol officers aboard while the suspect is mobile.
				-- Reacquire a fresh road route from the cruiser's current position.
				van.pursuit=p
				task.delay(0.20,function()
					if not p.active or van.dead then return end
					local okAgain=van:respond(function() return if p.active then responseParkingPoint(p,van,assignedSlot) else nil end,arrival,State.ai~=nil)
					if not okAgain and p.active then task.delay(0.8,function() if p.active and not van.dead then van:cruise() end end) end
				end)
				return
			end
			van.pursuit = nil
			responseSlotByCar[van]=nil
			local n = van.crewTotal - van.crewOut
			for i = 1, n do
				local cf = exits[i] or exits[1]
				if cf then
					van.crewOut += 1
					local cop = CopAI.new("Patrol", cf, {
						role = "Patrol",pursuit = p,homeCar = van,
						flank = if i % 2 == 0 then 1 else -1,
						onRemoved = function(_cop, reason) if reason ~= "boarded" then van:crewLost() end end,
					})
					if not cop then van.crewOut -= 1 end
				end
			end
			if van.crewOut == 0 then van:cruise() end
		end
		local ok = car:respond(function()
			return if p.active then responseParkingPoint(p,car,assignedSlot) else nil
		end, arrival, State.ai ~= nil)
		if ok then
			car.pursuit = p
			already += 1
		end
	end
end

---------------------------------------------------------------------------
-- WAVES
---------------------------------------------------------------------------
local function waveLeft(wave: any): number
	return math.max(0, math.ceil(wave.planned * Config.Waves.ClearFraction) - wave.killed)
end

local function updateLabel(p: any)
	local d = p.dispatch
	if d.wave then
		local tier = Config.Waves.Tiers[d.wave.tier]
		p.waveLabel = string.format("WAVE %d · %s · %d to break", d.waveCount or 1, if tier then tier.Name else "Police", waveLeft(d.wave))
	elseif d.pendingAt then
		p.waveLabel = "Next wave incoming"
	else
		p.waveLabel = nil
	end
end

local waveCleared: (p: any, wave: any) -> ()

local function onWaveCopDied(p: any, wave: any)
	wave.killed += 1
	if wave.cleared or not p.active or p.dispatch.wave ~= wave then
		return
	end
	if waveLeft(wave) <= 0 then
		wave.cleared = true
		waveCleared(p, wave)
	end
	updateLabel(p)
end

local function spawnWaveCop(entry, cf: CFrame)
	local p = entry.pursuit
	local wave = entry.wave
	local cop = CopAI.new(entry.unit, cf, {
		role = entry.role,
		pursuit = p,
		flank = entry.flank,
		onDied = if wave
			then function()
				onWaveCopDied(p, wave)
			end
			else nil,
	})
	if cop and wave then
		wave.spawned += 1
		wave.members[cop] = true
	end
end

local function processQueue(now: number)
	local waveAlive = CopAI.count(function(c)
		return c.role == "Wave"
	end)
	local budget = 3
	local i = 1
	while i <= #queue and budget > 0 do
		local e = queue[i]
		if not e.pursuit.active then
			table.remove(queue, i)
			continue
		end
		if e.t > now then
			i += 1
			continue
		end
		if e.role == "Wave" and waveAlive >= Config.Waves.MaxWaveUnits then
			i += 1
			continue
		end
		table.remove(queue, i)
		local cf = e.cfFn()
		if cf then
			spawnWaveCop(e, cf)
			budget -= 1
			if e.role == "Wave" then
				waveAlive += 1
			end
		else
			-- nowhere good to spawn right now; retry shortly (give up after a while)
			e.expires = e.expires or (now + 8)
			if now < e.expires then
				e.t = now + 0.6
				table.insert(queue, e)
			end
		end
	end
end

local function nearbyWanted(p: any): number
	local n = 0
	local here = p.lastSeenPos
	if not here then
		return 0
	end
	for _, other in Heat.pursuits do
		if other ~= p and other.active and other.stars >= 2 and other.lastSeenPos and (other.lastSeenPos - here).Magnitude < 300 then
			n += 1
		end
	end
	return n
end

-- Where a squad on foot comes from, re-evaluated at spawn time.
local function footOrigin(p: any): () -> CFrame?
	return function()
		local target = p.lastSeenPos
		if not target then
			return nil
		end
		local station, dist = nearestStation(target)
		if station and dist <= Config.Waves.RunDistance * 1.25 then
			return stationCf(station, target)
		end
		return hiddenCf(target, 110, 230)
	end
end

local function dispatchWave(p: any, tier: number, reinforce: boolean?, override: any?)
	local tcfg = override or Config.Waves.Tiers[tier]
	local target = p.lastSeenPos
	if not tcfg or not target then
		return
	end
	local d = p.dispatch
	local now = os.clock()

	-- build the roster
	local mul = 1 + Config.Waves.PerExtraPlayer * nearbyWanted(p)
	if reinforce then
		mul *= 0.5
	end
	local roster: { string } = {}
	for _, group in tcfg.Units do
		local n = math.max(1, math.floor(group[2] * mul + 0.5))
		for _ = 1, n do
			table.insert(roster, group[1])
		end
	end
	local existingWave = d.wave
	-- v142 adaptive response: replacements reflect what is actually happening instead
	-- of blindly dumping another copy of the same squad onto the player.
	if reinforce and existingWave then
		local lossRatio = existingWave.killed / math.max(1, existingWave.planned)
		if lossRatio >= 0.35 then
			table.insert(roster, if tier >= 4 then "Riot" else "Shotgunner")
		end
		if p.lethal == true and tier >= 5 then table.insert(roster, "SWAT") end
	end

	if tier >= 5 and not reinforce then
		local extra = Config.Waves.TopTierGrowth * (d.topRepeats or 0)
		for k = 1, extra do
			local g = tcfg.Units[(k - 1) % #tcfg.Units + 1]
			table.insert(roster, g[1])
		end
	end

	local wave = existingWave
	if (reinforce or override) and wave and not wave.cleared then
		wave.planned += #roster
		wave.reinforced += 1
		State.announce(p.player, if override then tcfg.Announce else "Police reinforcements en route", if override then "danger" else "warn")
	else
		waveIds += 1
		wave = {
			id = waveIds,
			tier = tier,
			planned = #roster,
			spawned = 0,
			killed = 0,
			members = {},
			startedAt = now,
			reinforced = 0,
			cleared = false,
		}
		d.wave = wave
		d.waveCount = (d.waveCount or 0) + 1
		d.pendingAt = nil
		State.announce(p.player, tcfg.Announce, "danger")
		-- SWAT fast-roping out of a helicopter
		if tcfg.Rappel and Config.Helicopter.Enabled then
			wave.planned += tcfg.Rappel[2]
			d.rappelPending = { unit = tcfg.Rappel[1], count = tcfg.Rappel[2], wave = wave }
		end
	end
	updateLabel(p)
	State.log(p.player.Name, "wave", d.waveCount, "tier", tier, "units", #roster, if reinforce then "(reinforcement)" else "")

	-- how do they get there?
	local station, sdist = nearestStation(target)
	local n = #roster
	local function flankOf(i: number): number
		return (i - (n + 1) / 2) * (2.4 / math.max(n, 2)) + rng:NextNumber(-0.15, 0.15)
	end
	local function onFoot(from: () -> CFrame?)
		for i, unit in roster do
			enqueue({ unit = unit, cfFn = from, pursuit = p, wave = wave, flank = flankOf(i), t = now + (i - 1) * Config.Waves.SpawnGap, role = "Wave" })
		end
	end

	if station and sdist <= Config.Waves.RunDistance then
		onFoot(footOrigin(p))
		return
	end
	local vcfg = Config.Vehicles
	local vtype = tcfg.Vehicle
	local vehicleType = vtype and vcfg.Types[vtype]
	if not (vcfg.Enabled and vehicleType) then
		onFoot(footOrigin(p))
		return
	end

	-- split the roster into vehicle loads
	local loads: { { { unit: string, index: number } } } = {}
	local cap = math.max(1, vehicleType.Capacity)
	for i, unit in roster do
		local slot = math.floor((i - 1) / cap) + 1
		loads[slot] = loads[slot] or {}
		table.insert(loads[slot], { unit = unit, index = i })
	end

	local function unload(load: { { unit: string, index: number } }, exits: { CFrame }?)
		local t = os.clock()
		for k, member in load do
			local exitCf = if exits and #exits > 0 then exits[(k - 1) % #exits + 1] else nil
			local fromFn: () -> CFrame?
			if exitCf then
				fromFn = function()
					local tgt = p.lastSeenPos or exitCf.Position
					return facingCf(exitCf.Position, tgt)
				end
			else
				fromFn = function()
					local tgt = p.lastSeenPos
					return if tgt then hiddenCf(tgt, 90, 200) else nil
				end
			end
			enqueue({ unit = member.unit, cfFn = fromFn, pursuit = p, wave = wave, flank = flankOf(member.index), t = t + (k - 1) * 0.3, role = "Wave" })
		end
	end

	for li, load in loads do
		if Van.count() >= vcfg.MaxActive then
			unload(load, nil)
			continue
		end
		task.delay((li - 1) * 1.4, function()
			if not p.active then
				return
			end
			local goalNow = p.lastSeenPos or target
			local originCf: CFrame? = nil
			local st, sd = nearestStation(goalNow)
			if st and sd <= 1500 then
				originCf = st * CFrame.new((li - 1) * 3, 0, 0)
			else
				originCf = hiddenCf(goalNow, 220, 340)
			end
			if not originCf then
				unload(load, nil)
				return
			end
			Van.spawn(vtype, originCf, function()
				-- v113: every wave vehicle gets its own reserved stop (no piles of vans)
				local ai = State.ai
				if ai and ai.parkingPoint and p.active then
					local ok, slot = pcall(ai.parkingPoint, p, load)
					if ok and slot then
						return slot
					end
				end
				return p.lastSeenPos
			end, function(_van, exits)
				if p.active then
					unload(load, exits)
				end
			end, function(reason)
				State.log("vehicle failed:", reason, "- squad goes on foot")
				if p.active then
					unload(load, nil)
				end
			end, State.ai ~= nil)
		end)
	end
end

waveCleared = function(p: any, wave: any)
	local d = p.dispatch
	d.wave = nil
	local now = os.clock()
	if p.stars >= 5 then
		d.topRepeats = (d.topRepeats or 0) + 1
	end
	State.announce(p.player, "Wave broken! Brace yourself", "good")
	Heat.setStars(p.player, math.min(#Config.Heat.StarThresholds, p.stars + 1), "WaveCleared")
	d.pendingAt = now + Config.Waves.Interlude
	updateLabel(p)
	State.log(p.player.Name, "cleared wave", wave.id, "→ stars", p.stars)
end

---------------------------------------------------------------------------
-- helicopters
---------------------------------------------------------------------------
local function heliCount(d: any): number
	local n = 0
	for h in d.helis do
		if h.alive then
			n += 1
		else
			d.helis[h] = nil
		end
	end
	return n
end

local function helicopterStep(p: any, now: number)
	local hc = Config.Helicopter
	if not hc.Enabled then
		return
	end
	local d = p.dispatch
	d.helis = d.helis or {}
	local tcfg = Config.Waves.Tiers[math.min(p.stars, 6)]
	local want = if tcfg and tcfg.Helicopters then tcfg.Helicopters else 0
	-- once a heli has been earned it stays for the rest of the pursuit
	d.heliWant = math.max(d.heliWant or 0, want)
	local have = heliCount(d)

	if have < d.heliWant and Heli.count() < hc.MaxActive and now >= (d.heliReadyAt or 0) and p.lastSeenPos then
		local target = p.lastSeenPos :: Vector3
		local station, sd = nearestStation(target)
		local from: Vector3
		if station and sd < 900 then
			from = station.Position + Vector3.new(0, 110, 0)
		else
			local a = rng:NextNumber(0, math.pi * 2)
			from = target + Vector3.new(math.cos(a) * 480, 140, math.sin(a) * 480)
		end
		local heli = Heli.spawn(p, from, {
			onDown = function()
				d.heliReadyAt = os.clock() + hc.RespawnDelay
				if p.active then
					State.announce(p.player, "Police helicopter down!", "good")
				end
			end,
			onRemoved = function(h)
				d.helis[h] = nil
			end,
		})
		d.helis[heli] = true
		d.heliReadyAt = now + 5
		if have == 0 then
			State.announce(p.player, "Air support inbound", "warn")
		end
	end

	-- hand a pending fast-rope insertion to a helicopter
	local order = d.rappelPending
	if order then
		if not order.wave or order.wave.cleared or d.wave ~= order.wave then
			d.rappelPending = nil
		else
			for h in d.helis do
				if h.alive and h.state ~= "leave" and not h.rappelOrder and not h.rappelling then
					d.rappelPending = nil
					local wave = order.wave
					h:rappel(order.unit, order.count, function(cop)
						wave.spawned += 1
						wave.members[cop] = true
						cop.onDied = function()
							onWaveCopDied(p, wave)
						end
					end)
					break
				end
			end
		end
	end
end

---------------------------------------------------------------------------
-- per-pursuit logic
---------------------------------------------------------------------------
local function pursuitStep(p: any, now: number)
	if not p.active or p.stars <= 0 then
		return
	end
	if p.player and p.player:GetAttribute("SentenceEnd") ~= nil then return end -- v288l: an inmate: the COs
	local d = p.dispatch
	-- v113: with the tactical AI, "is it a vehicle pursuit" is what police KNOW (not x-ray),
	-- and PoliceAI.Pursuit owns the cruisers for it.
	local ai = State.ai
	local vehiclePursuit = if ai and ai.vehicleMode then ai.vehicleMode(p) else pursuitTargetInVehicle(p)
	local want = vehiclePursuit and 0 or (Config.Patrol.Responders[math.min(p.stars, #Config.Patrol.Responders)] or 2)
	local assigned = if want>0 then assignResponders(p, want) else 0
	if vehiclePursuit and not (ai and ai.ownsVehicles) and now>=(d.nextCruiserRefresh or 0) then
		d.nextCruiserRefresh=now+3
		local carWant=math.max(Config.PatrolCars.Responders[math.min(p.stars,#Config.PatrolCars.Responders)] or 1,math.min(3,math.max(1,p.stars)))
		task.spawn(dispatchCruisers,p,carWant)
	end

	-- v191: marked cruisers answer on-foot suspects too (the tactical AI only
	-- claimed cars for vehicle chases, so a wanted player on foot never drew a
	-- single car). A patrol car that SAW the suspect is sent first.
	if not vehiclePursuit and p.lastSeenPos then
		local spottedNew = p.spottedAt ~= nil and p.spottedAt > (d.spotHandledAt or 0)
		if spottedNew or now >= (d.nextFootCruiserAt or 0) then
			d.nextFootCruiserAt = now + 4
			if spottedNew then d.spotHandledAt = p.spottedAt end
			local carWant = (Config.PatrolCars.Responders[math.min(p.stars, #Config.PatrolCars.Responders)] or 1) + (if p.swatRequested then 1 else 0)
			task.spawn(dispatchCruisers, p, carWant)
		end
	end
	-- v191: violence toward any officer -> SWAT + air support now.
	if p.swatRequested and not d.swatSent and p.lastSeenPos and Units.isReady() then
		d.swatSent = true
		d.heliWant = math.max(d.heliWant or 0, Config.Waves.OfficerAssault.Helicopters or 1)
		dispatchWave(p, math.clamp(p.stars, 4, 5), false, Config.Waves.OfficerAssault)
	end

	-- nobody near enough to respond: send a unit from off-screen (on-foot suspects only)
	if not vehiclePursuit and assigned == 0 and p.lastSeenPos and now - (d.responderAt or 0) > 20 and Units.isReady() then
		d.responderAt = now
		local target = p.lastSeenPos
		for i = 1, math.min(want, 2) do
			enqueue({
				unit = "Patrol",
				cfFn = function()
					return hiddenCf(p.lastSeenPos or target, 90, 200)
				end,
				pursuit = p,
				wave = nil,
				flank = (i - 1.5) * 0.8,
				t = now + (i - 1) * 0.5,
				role = "Patrol",
			})
		end
	end

	if p.stars >= 2 and Units.isReady() then
		local tier = math.min(p.stars, 6)
		if d.pendingAt then
			if now >= d.pendingAt then
				d.pendingAt = nil
				dispatchWave(p, tier)
			end
		elseif not d.wave then
			dispatchWave(p, tier)
		else
			local wave = d.wave
			-- stars jumped well past this wave (bank job, helicopter down...): escalate now
			if tier - wave.tier >= 2 then
				dispatchWave(p, tier)
			elseif now - wave.startedAt > Config.Waves.ReinforceAfter and wave.reinforced < 3 and not p.searching then
				wave.startedAt = now
				dispatchWave(p, tier, true)
			end
		end
	end
	helicopterStep(p, now)
	updateLabel(p)
end

---------------------------------------------------------------------------
function Dispatcher.init()
	Dispatcher.refreshWorld()
	task.spawn(function()
		if RoadGraph.load() then
			State.log("road network loaded:", RoadGraph.nodeCount(), "nodes")
		end
	end)
	local rn=Workspace:FindFirstChild("RoadNetwork")
	if rn then
		local seenRevision=rn:GetAttribute("Revision") or 0
		rn:GetAttributeChangedSignal("Revision"):Connect(function()
			local rev=rn:GetAttribute("Revision") or 0
			if rev~=seenRevision then
				seenRevision=rev
				task.spawn(function()
					if RoadGraph.load() then
						State.log("road network reloaded:",RoadGraph.nodeCount(),"nodes revision",rev)
					end
				end)
			end
		end)
	end
	State.patrolGoal = patrolGoal
	State.nearestStation = function(pos: Vector3): Vector3?
		local cf = nearestStation(pos)
		return if cf then cf.Position else nil
	end

	-- keep station/patrol lists fresh if you add the folders while the server runs
	for _, name in { Config.SpawnFolderName, Config.PatrolFolderName } do
		Workspace.ChildAdded:Connect(function(child)
			if child.Name == name then
				task.delay(1, Dispatcher.refreshWorld)
			end
		end)
	end

	Heat.onChanged(function(_player, p, oldStars, _reason)
		if not p.active then
			return
		end
		-- v288l: trouble inside the prison is the COs' (PL.coEngage): no city units, cruisers, air
		if p.player and p.player:GetAttribute("SentenceEnd") ~= nil then return end
		local want = Config.Patrol.Responders[math.min(p.stars, #Config.Patrol.Responders)] or 2
		assignResponders(p, want)
		local cars = Config.PatrolCars.Responders[math.min(p.stars, #Config.PatrolCars.Responders)] or 1
		local ai = State.ai
		if not (ai and ai.vehicleMode and ai.vehicleMode(p)) then
			task.spawn(dispatchCruisers, p, cars)
		end
		if oldStars < 2 and p.stars >= 2 then
			State.announce(p.player, "Police are coming for you", "danger")
		end
	end)

	Heat.onCleared(function(_player, p, _reason)
		local d = p.dispatch
		for _, c in CopAI.list(function(c)
			return c.pursuit == p
		end) do
			c:release()
		end
		if d.helis then
			for h in d.helis do
				h:leave()
			end
		end
		for _, car in patrolCars do
			if car.pursuit == p then
				car.pursuit = nil
				if not car.parked and not car.dead then
					car:cruise() -- turned around before arriving
				end
			end
		end
		d.wave = nil
		d.pendingAt = nil
		d.rappelPending = nil
		for i = #queue, 1, -1 do
			if queue[i].pursuit == p then
				table.remove(queue, i)
			end
		end
	end)
end

function Dispatcher.step(_dt: number)
	local now = os.clock()
	if now - lastPatrolTick >= 1 then
		lastPatrolTick = now
		patrolStep(now)
	end
	if now - lastVanStep >= 1 then
		lastVanStep = now
		Van.step()
	end
	if now - lastCarTick >= 2 then
		lastCarTick = now
		task.spawn(patrolCarStep, now)
	end
	for _, p in Heat.pursuits do
		pursuitStep(p, now)
	end
	if not State.ai then
		IncidentController.step(_dt) -- legacy role tags; PoliceAI.Incidents replaces this
	end
	processQueue(now)
end

function Dispatcher.stationCount(): number
	return #stations
end

-- v113: pursuit cruisers dispatched by PoliceAI join the normal patrol fleet so the usual
-- population / retirement rules apply to them afterwards.
function Dispatcher.adoptPatrolCar(car: any)
	if car and not table.find(patrolCars, car) then
		table.insert(patrolCars, car)
	end
end

---------------------------------------------------------------------------
-- v212 CHIEF OF POLICE console (ReplicatedStorage.ChiefConsole). Only the
-- Chief of Police team, and only aquagaming22 (or Studio / the place owner).
---------------------------------------------------------------------------
do
	-- v290: this block is in the Dispatcher module, which never had ServerStorage (the chief's
	-- warrant / stars actions hit "attempt to index nil with FindFirstChild")
	local ServerStorage = game:GetService("ServerStorage")
	local ReplicatedStorage = game:GetService("ReplicatedStorage")
	local RunService = game:GetService("RunService")
	local CHIEF_UNITS = { "Patrol", "Officer", "Shotgunner", "SWAT", "Riot", "Heavy", "SEAL", "Juggernaut", "Army" }
	local allowedUnit = {}
	for _, u in CHIEF_UNITS do
		allowedUnit[u] = true
	end
	-- v235: crimes the Chief can put on a warrant (in severity order), plus the
	-- five-officer-kill charge that sends the suspect to Death Row at booking
	local WARRANT_CRIMES = {
		"Assault", "Drugs", "VehicleTheft", "Burglary", "ResistingArrest", "ShotsFired", "AssaultOfficer",
		"Robbery", "Murder", "CopKilled", "PrisonEscape", "BankRobbery", "HelicopterDown",
	}
	local FIVE_KILLS = "FiveCopKills"
	local function warrantCrimeList()
		local out = {}
		for _, key in WARRANT_CRIMES do
			local crime = Config.Crimes[key]
			if crime then
				table.insert(out, { key = key, charge = crime.Charge or key, stars = crime.MinStars or 1 })
			end
		end
		table.insert(out, { key = FIVE_KILLS, charge = "Murder of 5 police officers (Death Row)", stars = 5 })
		return out
	end
	local function isChief(player: Player): boolean
		if not player.Team or player.Team.Name ~= "Chief of Police" then
			return false
		end
		return player.Name == "aquagaming22" or RunService:IsStudio() or player.UserId == game.CreatorId
	end
	local function target(name: any): Player?
		if type(name) ~= "string" then
			return nil
		end
		local plr = Players:FindFirstChild(name)
		return if plr and plr:IsA("Player") then plr else nil
	end
	local function lawBroadcast(text: string)
		for _, plr in Players:GetPlayers() do
			if Util.isLaw(plr) then
				State.announce(plr, text, "warn")
			end
		end
	end
	local fn = ReplicatedStorage:FindFirstChild("ChiefConsole") or Instance.new("RemoteFunction")
	fn.Name = "ChiefConsole"
	fn.Parent = ReplicatedStorage
	fn.OnServerInvoke = function(chief: Player, action: any, a: any, b: any, c: any, d: any, e: any)
		if not isChief(chief) then
			return false, "Chief of Police only"
		end
		if action == "list" then
			local out = {}
			for _, plr in Players:GetPlayers() do
				table.insert(out, {
					name = plr.Name,
					display = (plr:GetAttribute("CharacterName") or plr.DisplayName),
					team = plr.Team and plr.Team.Name or "",
					stars = Heat.stars(plr),
					warrant = plr:GetAttribute("Warrant"),
				})
			end
			return true, out, CHIEF_UNITS, warrantCrimeList()
		end
		local plr = target(a)
		if not plr then
			return false, "No such player"
		end
		if action == "setWanted" then
			local stars = math.clamp(math.floor(tonumber(b) or 0), 0, #Config.Heat.StarThresholds)
			Heat.clear(plr, "Chief order")
			if stars > 0 then
				Heat.setStars(plr, stars, "Chief order")
			end
			State.log(chief.Name, "chief set", plr.Name, "wanted", stars)
			return true, ("%s is now %d-star wanted"):format(plr.Name, stars)
		elseif action == "warrant" then
			local note = if type(b) == "string" and b ~= "" then string.sub(b, 1, 80) else nil
			-- v235: the charges on the warrant are real crimes on the suspect's record:
			-- they set the wanted level, how police respond, and the case at booking
			local picked = {}
			if type(c) == "table" then
				local valid = { [FIVE_KILLS] = true }
				for _, key in WARRANT_CRIMES do
					valid[key] = true
				end
				for _, key in c do
					if type(key) == "string" and valid[key] and not table.find(picked, key) then
						table.insert(picked, key)
					end
				end
			end
			local names = {}
			-- (the crimes go on the record when the warrant is served - or now, with stars)
			for _, key in picked do
				if key == FIVE_KILLS then
					table.insert(names, "Murder of 5 police officers")
				else
					table.insert(names, Config.Crimes[key].Charge or key)
				end
			end
			if #names == 0 and not note then
				return false, "Pick at least one crime (or write a reason)"
			end
			local reason = table.concat(names, ", ")
			if note then
				reason = if reason == "" then note else reason .. " - " .. note
			end
			-- v260: warrants are NO-STAR by default - saved, served when an officer, a plate
			-- reader or a stop identifies them. d = true also sets stars now; e = severity 1-3.
			local alsoStars = d == true
			local severity = math.clamp(math.floor(tonumber(e) or 0), 0, 3)
			local api = ServerStorage:FindFirstChild("CityLifeApi")
			local okW, issued = false, false
			if api and api:IsA("BindableFunction") then
				okW, issued = pcall(api.Invoke, api, "chiefWarrant", plr, { reason = reason, crimes = picked, severity = severity, by = chief.Name })
			end
			if not (okW and issued) then
				-- CityLife isn't running: the old starred warrant
				plr:SetAttribute("Warrant", string.sub(reason, 1, 200))
				alsoStars = true
			end
			if alsoStars then
				for _, key in picked do
					if key == FIVE_KILLS then
						local have = tonumber(plr:GetAttribute("PoliceOfficersKilled")) or 0
						for _ = 1, math.max(1, 5 - have) do Heat.addCrime(plr, "CopKilled") end
						plr:SetAttribute("DeathRowTestOverride", true)
					else
						Heat.addCrime(plr, key)
					end
				end
				if Heat.stars(plr) < 2 then Heat.setStars(plr, 2, "Warrant") end
			elseif table.find(picked, FIVE_KILLS) then
				plr:SetAttribute("DeathRowTestOverride", true)
			end
			State.log(chief.Name, "chief warrant", plr.Name, reason, alsoStars and "stars" or "no-star")
			if alsoStars then
				State.announce(plr, "A WARRANT HAS BEEN ISSUED FOR YOUR ARREST: " .. reason, "danger")
			end
			lawBroadcast(("WARRANT: %s - %s%s"):format(plr.Name, reason, if alsoStars then "" else " (not yet located)"))
			return true, ("Warrant issued for %s (%d charge%s%s)"):format(plr.Name, #names, if #names == 1 then "" else "s", if alsoStars then ", wanted now" else ", no stars")
		elseif action == "clearWarrant" then
			plr:SetAttribute("Warrant", nil)
			local api = ServerStorage:FindFirstChild("CityLifeApi")
			if api and api:IsA("BindableFunction") then pcall(api.Invoke, api, "clearWarrant", plr, "Chief order") end
			Heat.clear(plr, "Chief order")
			return true, "Warrant cleared for " .. plr.Name
		elseif action == "dispatch" then
			local unit = if type(b) == "string" and allowedUnit[b] then b else "SWAT"
			local count = math.clamp(math.floor(tonumber(c) or 4), 1, 20)
			local vehicle = if d == "Cruiser" or d == "Van" or d == "Armored" or d == "None" then d else "Armored"
			local helis = math.clamp(math.floor(tonumber(e) or 0), 0, 3)
			if not Units.isReady() then
				return false, "Police units are still loading"
			end
			if Heat.stars(plr) < 2 then
				Heat.setStars(plr, 2, "Chief dispatch")
			end
			local p = Heat.get(plr)
			local _, _, root = Util.charInfo(plr)
			if not p or not root then
				return false, "Target has no character"
			end
			p.lastSeenPos = root.Position
			p.lastSeenTime = os.clock()
			local order = {
				Name = "Chief's order",
				Announce = ("Chief of Police dispatched %d %s"):format(count, unit),
				Units = { { unit, count } },
				Vehicle = if vehicle == "None" then nil else vehicle,
				Helicopters = helis,
			}
			if helis > 0 then
				p.dispatch.heliWant = math.max(p.dispatch.heliWant or 0, helis)
			end
			dispatchWave(p, math.max(p.stars, 2), false, order)
			lawBroadcast(("Chief dispatched %d %s to %s"):format(count, unit, plr.Name))
			return true, ("%d %s dispatched to %s"):format(count, unit, plr.Name)
		elseif action == "lethal" then
			Heat.authorizeLethal(plr, "armed standoff")
			return true, "Lethal force authorized on " .. plr.Name
		end
		return false, "Unknown action"
	end
end

return Dispatcher

end

